local config = {
  ui_story_5035_50350101_1_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_5035_50350101_2_dialog_content = "Periksa satu-dua-tiga!",
  ui_story_5035_50350101_3_dialog_content = "Hai-yah! Kamera ini cukup berat!",
  ui_story_5035_50350101_4_dialog_content = "Siapa yang harus difilmkan dulu...? Bagaimana denganmu, pengawas naskah?",
  ui_story_5035_50350101_5_dialog_content = "Siapa, aku?!",
  ui_story_5035_50350101_6_dialog_content = "Tapi tutup lensa masih di atas lensa...",
  ui_story_5035_50350101_7_dialog_content = "Apa? Ah, itu memalukan!",
  ui_story_5035_50350101_8_dialog_content = "Untung kita belum resmi mulai. Terima kasih untuk pengingatnya!",
  ui_story_5035_50350101_9_dialog_content = "J-Hanya melakukan pekerjaanku.",
  ui_story_5035_50350101_10_dialog_content = "Baiklah, sekarang sapa kamera!",
  ui_story_5035_50350101_11_dialog_content = "H-Halo, pemirsa. Kami datang kepada Anda secara langsung dari lokasi syuting film, <color=#FFB400>Rumah Ketakutan</color>. Aku...",
  ui_story_5035_50350101_12_dialog_content = "Anda tidak harus begitu formal. Kami hanya mendapatkan beberapa cuplikan di balik layar.",
  ui_story_5035_50350101_13_dialog_content = "Masalahnya, saya tidak tahu harus berkata apa lagi...",
  ui_story_5035_50350101_14_dialog_content = "Anda adalah filmnya <color=#FFB400>wanita terkemuka</color>, Lagipula. Mengapa saya tidak merekam Anda saja?",
  ui_story_5035_50350101_15_dialog_content = "Tidak mungkin, saya belum bersenang-senang!",
  ui_story_5035_50350101_16_dialog_content = "Kalau begitu... Direktur, tolong luangkan waktumu sebentar!",
  ui_story_5035_50350101_17_dialog_content = "Baiklah, karena pengawasnya pemalu kamera, mari kita beralih ke...",
  ui_story_5035_50350101_18_dialog_content = "Ta-da, sutradara filmnya, Pak Jonny!",
  ui_story_5035_50350101_19_dialog_content = "Haha, jika menurutmu syuting dengan kamera sangat menyenangkan...",
  ui_story_5035_50350101_20_dialog_content = "Anda akan punya banyak waktu untuk bermain dengannya nanti.",
  ui_story_5035_50350101_21_dialog_content = "Apa? Maksud kamu apa?",
  ui_story_5035_50350101_22_dialog_content = "Saya ingin mencoba sesuatu yang baru, <color=#FFB400>bergaya mockumentary</color> film horor.",
  ui_story_5035_50350101_23_dialog_content = "Saya ingin Anda mengambil kamera dan merekam penjelajahan rumah Anda.",
  ui_story_5035_50350101_24_dialog_content = "Ke mana Anda pergi, apa yang Anda katakan, bagaimana Anda bereaksi, semuanya akan ditangkap secara langsung.",
  ui_story_5035_50350101_25_dialog_content = "Apakah Anda pikir Anda bisa mengatasinya?",
  ui_story_5035_50350101_26_dialog_content = "Kamu pasti becanda. Ini bagus!!!",
  ui_story_5035_50350101_27_dialog_content = "Ha, percaya diri memang merupakan bagian dari pesona alammu. Ini pasti akan membuat Anda terkenal.",
  ui_story_5035_50350101_28_dialog_content = "Dan kau juga akan menjadi sutradara terkenal, Jonny!",
  ui_story_5035_50350101_29_dialog_content = "Saya harap begitu. Ketenaran dan saya telah menjadi orang asing untuk waktu yang lama.",
  ui_story_5035_50350101_30_dialog_content = "Meninggalkan jejak saya dengan film horor yang unik sudah cukup bagi saya.",
  ui_story_5035_50350101_31_dialog_content = "Heh, ini dia lagi!",
  ui_story_5035_50350101_32_dialog_content = "Pokoknya, biarkan aku memiliki kamera. Anda hanya duduk dan bersantai.",
  ui_story_5035_50350101_33_dialog_content = "Aah!",
  ui_story_5035_50350101_34_dialog_content = "Kau baik-baik saja?",
  ui_story_5035_50350101_35_dialog_content = "Hampir tersandung kabelnya, tapi aku baik-baik saja...",
  ui_story_5035_50350101_36_dialog_content = "Kameramen, ikuti dia dengan cermat, ya?",
  ui_story_5035_50350101_37_dialog_content = "Anda mendapatkannya. Saya akan memastikan peralatannya baik-baik saja.",
  ui_story_5035_50350101_38_dialog_content = "Baiklah. House of Dread, adegan 1, ambil 1. Aksi!",
  ui_story_5035_50350101_39_dialog_content = "Astaga, apakah ini rumah hantu legendaris di hadapanku?",
  ui_story_5035_50350101_40_dialog_content = "Betapa menakutkan! Aku akan masuk dan memeriksanya dengan teman-temanku.",
  ui_story_5035_50350101_41_dialog_content = "Aku sebenarnya berharap Jonny kecil di sana bergabung dengan kita di dalam.",
  ui_story_5035_50350101_42_dialog_content = "Tunggu, dimana Jonny? Apakah dia menghilang? Hadirin sekalian, kami baru saja mengalami pertemuan paranormal pertama kami!",
  ui_story_5035_50350101_43_dialog_content = "Memotong!",
  ui_story_5035_50350101_44_dialog_content = "Mengedit akan sulit jika Anda terus berbicara secara artifisial.",
  ui_story_5035_50350101_45_dialog_content = "Ada kemungkinan besar bahwa adegan terakhir akan dipotong. Anda hanya dapat berbicara secara normal mulai sekarang.",
  ui_story_5035_50350101_46_dialog_content = "Oke, saya mengerti. Mengerti!",
  ui_story_5035_50350101_47_dialog_content = "Omong-omong, di mana Jonny?",
  ui_story_5035_50350101_48_dialog_content = "Ada apa dengan ini? Produser pergi cuti kemarin, dan sekarang sutradara tidak terlihat.",
  ui_story_5035_50350101_49_dialog_content = "Jangan bilang mereka menyerahkan syutingnya padaku agar mereka bisa pergi entah kemana!",
  ui_story_5035_50350101_50_dialog_content = "Atau apakah mereka sudah ada di rumah, menyiapkan alat peraga untuk menakut-nakuti kita?",
  ui_story_5035_50350101_51_dialog_content = "Potong... kita harus membunuh bagian itu juga.",
  ui_story_5035_50350101_52_dialog_content = "Harap diingat bahwa inti dari mockumentary adalah aspek \"kenyataan\" darinya.",
  ui_story_5035_50350101_53_dialog_content = "Begitu kita berada di dalam, kita tidak bisa bertingkah seperti sedang membuat film sungguhan.",
  ui_story_5035_50350101_54_dialog_content = "Aku paham.",
  ui_story_5035_50350101_55_dialog_content = "<color=#e8d9bb>Suatu saat nanti</color>",
  ui_story_5035_50350101_56_dialog_content = "Di tikungan di depan ada desas-desus \"Stairway to Death.\"",
  ui_story_5035_50350101_57_dialog_content = "Kameramen, maukah Anda mengambil beberapa foto saya nanti untuk kenang-kenangan? Dan supervisor, saya akan mengandalkan Anda untuk melacak kemana saya pergi.",
  ui_story_5035_50350101_58_dialog_content = "Eh, tentu, tapi...",
  ui_story_5035_50350101_59_dialog_content = "Aku, eh, lebih suka tidak memimpin, jadi...",
  ui_story_5035_50350101_60_dialog_content = "Tidak masalah. Aku akan pergi dulu dengan kamera!",
  ui_story_5035_50350101_61_dialog_content = "Sekarang, di mana Tangga Kematian yang bagus...",
  ui_story_5035_50350101_62_dialog_content = "Perhatikan kepalamu di tangga ini, semuanya!",
  ui_story_5035_50350101_63_dialog_content = "Bukannya itu penting bagiku, tapi kalian berdua mungkin akan memukulmu—",
  ui_story_5035_50350101_64_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5035_50350101_65_dialog_content = "Aduh... terlambat...",
  ui_story_5035_50350101_66_dialog_content = "Saya tidak tahu apakah Anda berani atau hanya idiot.",
  ui_story_5035_50350101_67_dialog_content = "Apa yang saya pelajari dari semua film yang saya tonton adalah bahwa tipe Anda biasanya yang pertama mati dalam film horor.",
  ui_story_5035_50350101_68_dialog_content = "Eek!",
  ui_story_5035_50350101_69_dialog_content = "Ahhhhhhhh!",
  ui_story_5035_50350101_70_dialog_content = "Apa yang salah?!",
  ui_story_5035_50350101_71_dialog_content = "Itu…",
  ui_story_5035_50350101_72_dialog_content = "Sebuah jalan buntu! Tangga mengarah ke jalan buntu!",
  ui_story_5035_50350101_73_dialog_content = "... Itu dia?",
  ui_story_5035_50350101_74_dialog_content = "Nah, lalu mengapa Anda berteriak juga, pengawas?",
  ui_story_5035_50350101_75_dialog_content = "Aku mendengar seseorang di depanku berteriak, jadi aku...",
  ui_story_5035_50350101_76_dialog_content = "...",
  ui_story_5035_50350101_77_dialog_content = "Ternyata rumor tersebut sedikit berlebihan, heh. Saya harap pemirsa tidak keberatan.",
  ui_story_5035_50350101_78_dialog_content = "Pokoknya, mari kita menuju ke tempat berikutnya!",
  ui_story_5035_50350101_79_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5035_50350101_80_dialog_content = "Saya tidak tahu apakah itu hanya saya, tetapi baunya lucu di sini.",
  ui_story_5035_50350101_81_dialog_content = "Ini seperti... ada yang busuk.",
  ui_story_5035_50350101_82_dialog_content = "B-benarkah?",
  ui_story_5035_50350101_83_dialog_content = "Aku tidak tahu. Mungkin saya salah?",
  ui_story_5035_50350101_84_dialog_content = "Maksudku, tidak ada apa-apa selain sekumpulan boneka yang tampak lucu. di sini...",
  ui_story_5035_50350101_85_dialog_content = "Tunggu...",
  ui_story_5035_50350101_86_dialog_content = "Apakah aku, atau apakah boneka itu berputar dengan sendirinya?",
  ui_story_5035_50350101_87_dialog_content = "Apa?!",
  ui_story_5035_50350101_88_dialog_content = "Mengapa kita tidak memundurkan rekaman itu dan melihat apa yang sebenarnya terjadi?",
  ui_story_5035_50350101_89_dialog_content = "Pemikiran yang bagus, juru kamera!",
  ui_story_5035_50350101_90_dialog_content = "<color=#e8d9bb>Buzz—buzz</color>",
  ui_story_5035_50350101_91_dialog_content = "Betapa anehnya...",
  ui_story_5035_50350101_92_dialog_content = "<color=#e8d9bb>*Statis*</color>",
  ui_story_5035_50350101_93_dialog_content = "Hei, kameranya rusak!",
  ui_story_5035_50350101_94_dialog_content = "(Apakah saya harus membayarnya?)",
  ui_story_5035_50350101_95_dialog_content = "<color=#e8d9bb>*Statis*</color>",
  ui_story_5035_50350101_96_dialog_content = "(A-Apa itu?!)",
  ui_story_5035_50350101_97_dialog_content = "Apa yang terjadi di sini?",
  ui_story_5035_50350101_98_dialog_content = "Uh, well, aku ingin tahu... Mungkin jika kita melihat ke luar ruangan...",
  ui_story_5035_50350101_99_dialog_content = "Hei!",
  ui_story_5035_50350101_100_dialog_content = "Kamera bekerja normal lagi!",
  ui_story_5035_50350101_101_dialog_content = "Apa yang kamu lakukan?",
  ui_story_5035_50350101_102_dialog_content = "Anda harus menanyakan itu kepada kru produksi!",
  ui_story_5035_50350101_103_dialog_content = "Kami seharusnya syuting di rumah hantu, tapi tidak ada hal menakutkan yang terjadi di sini.",
  ui_story_5035_50350101_104_dialog_content = "<color=#e8d9bb>Kriek...</color>",
  ui_story_5035_50350101_105_dialog_content = "Dan basement ini adalah lokasi terakhir.",
  ui_story_5035_50350101_106_dialog_content = "Hari ini gagal jika tidak ada apa-apa di sini.",
  ui_story_5035_50350101_107_dialog_content = "<color=#e8d9bb>Tetes... Tetes...</color>",
  ui_story_5035_50350101_108_dialog_content = "Aneh, dari mana suara ini berasal?",
  ui_story_5035_50350101_109_dialog_content = "Itu hanya air yang menetes. Berhentilah menakuti diri sendiri.",
  ui_story_5035_50350101_110_dialog_content = "Hanya air?",
  ui_story_5035_50350101_111_dialog_content = "Tapi kamar mandinya di lantai atas..",
  ui_story_5035_50350101_112_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5035_50350101_113_dialog_content = "Uh, a-ada apa dengan lilin ini...?",
  ui_story_5035_50350101_114_dialog_content = "<color=#e8d9bb>Ding... Ding...</color>",
  ui_story_5035_50350101_115_dialog_content = "<anim type=Shake><size=50>Mengaum-!</size></anim>",
  ui_story_5035_50350101_116_dialog_content = "<anim type=Shake><size=50>Aaaaaaaaaaa!!!</size></anim>",
  ui_story_5035_50350101_117_dialog_content = "<anim type=Shake><size=50>Seseorang, tolong aku! aku tidak ingin—</size></anim>",
  ui_story_5035_50350101_118_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5035_50350101_119_dialog_content = "<color=#e8d9bb>Buzz...buzz...</color>",
  ui_story_5035_50350101_120_dialog_content = "<color=#e8d9bb>Soroz: Jembatan</color>",
  ui_story_5035_50350101_121_dialog_content = "Hah...",
  ui_story_5035_50350101_122_dialog_content = "Hmm?",
  ui_story_5035_50350101_123_dialog_content = "Bagaimana itu mungkin?!",
  ui_story_5035_50350101_124_dialog_content = "Apa yang kamu baca, Wakil?",
  ui_story_5035_50350101_125_dialog_content = "Oh, kamu sudah bangun. Selamat pagi!",
  ui_story_5035_50350101_126_dialog_content = "Saya memeriksa Scoop Harian hari ini.",
  ui_story_5035_50350101_127_dialog_content = "Bagaimana Anda mendapatkan kertas dari Umbraton pagi-pagi begini?",
  ui_story_5035_50350101_128_dialog_content = "Wendy membawanya ke saya di putaran nya. Itu terlihat menarik jadi saya menyimpannya.",
  ui_story_5035_50350101_129_dialog_content = "Datang dan periksa ini, PlayerName!",
  ui_story_5035_50350101_130_dialog_content = "Oke.",
  ui_story_5035_50350101_131_dialog_content = "\"Aktris Film B-Horror yang Sedikit Dikenal Hilang\"?!",
  ui_story_5035_50350101_132_dialog_content = "Hal semacam itu memang terjadi di Umbraton, tapi...",
  ui_story_5035_50350101_133_dialog_content = "Ini jeritan aksi publisitas, bukan?",
  ui_story_5035_50350101_134_dialog_content = "Tidak bukan itu, PlayerName, sedikit lebih tinggi...",
  ui_story_5035_50350101_135_dialog_content = "\"Live Boxing\", \"Penyanyi Populer Membuat Debut\"...",
  ui_story_5035_50350101_136_dialog_content = "<color=#FFB400>\"Pembukaan Rumah Hantu Anderson\"?!</color>",
  ui_story_5035_50350101_137_dialog_content = "Bingo!",
  ui_story_5035_50350101_138_dialog_content = "Mereka benar-benar menghipnotisnya... \"Rasakan pertemuan paranormal asli sampai tenggorokan Anda kering karena tangisan keputusasaan\"!",
  ui_story_5035_50350101_139_dialog_content = "(Jangan bilang Rumah Hantu Andersen ini...)",
  ui_story_5035_50350101_140_dialog_content = "Bagaimana menurutmu? Bukankah itu terdengar menarik?",
  ui_story_5035_50350101_141_dialog_content = "Tidak! Bahkan byline saja terdengar dangkal dan sensasional!",
  ui_story_5035_50350101_142_dialog_content = "Hai, PlayerName, Anda tidak tertarik sama sekali? Pertemuan paranormal nyata meskipun ...",
  ui_story_5035_50350101_143_dialog_content = "(Wakil tampaknya sangat tertarik untuk pergi...)",
  ui_story_5035_50350101_144_dialog_content = "Nah, Vice, bagaimana kalau kita...",
  ui_story_5035_50350101_145_dialog_content = "Dan jangan abaikan cetakan kecil, PlayerName!",
  ui_story_5035_50350101_146_dialog_content = "\"Spesial Grand Opening: Diskon 50% untuk pembelian dua tiket\"?",
  ui_story_5035_50350101_147_dialog_content = "Betul sekali, PlayerName! Hehehe.",
  ui_story_5035_50350101_148_dialog_content = "Sudah kuduga!!!",
  ui_story_5035_50350201_1_dialog_content = "<color=#e8d9bb>Pinggiran Umbraton: Rumah Hantu Andersen</color>",
  ui_story_5035_50350201_2_dialog_content = "Tempat ini pasti berada di antah berantah.",
  ui_story_5035_50350201_3_dialog_content = "Begitulah cara membangun suasana rumah hantu!",
  ui_story_5035_50350201_4_dialog_content = "Memang terlihat cukup menyeramkan pada pandangan pertama.",
  ui_story_5035_50350201_5_dialog_content = "Gerbang kumuh itu seharusnya menjadi pintu masuk.",
  ui_story_5035_50350201_6_dialog_content = "Ayo, PlayerName, dan siapkan tiket Anda juga.",
  ui_story_5035_50350201_7_dialog_content = "Oh? Bukankah ini Tuan Navigator?",
  ui_story_5035_50350201_8_dialog_content = "Aku punya firasat saat melihat nama rumah hantu itu.",
  ui_story_5035_50350201_9_dialog_content = "Senang bertemu denganmu lagi, Minos! Apakah Anda mengambil peran kepala pelayan di sini juga?",
  ui_story_5035_50350201_10_dialog_content = "Ya. Saya minta maaf karena tidak memiliki sambutan khusus untuk Anda.",
  ui_story_5035_50350201_11_dialog_content = "Tunjukkan tiket Anda jika Anda mau, tolong, PlayerName.",
  ui_story_5035_50350201_12_dialog_content = "Anda sopan seperti biasa, Pak Minos.",
  ui_story_5035_50350201_13_dialog_content = "Ini Vice, teman baikku.",
  ui_story_5035_50350201_14_dialog_content = "Selamat siang, pengambil tiket! Apakah semboyan itu benar? Akankah kita mengalami fenomena paranormal yang nyata?",
  ui_story_5035_50350201_15_dialog_content = "Eh, dan, dia penggemar paranormal.",
  ui_story_5035_50350201_16_dialog_content = "Ya, tentu saja, Nona Wakil. Itu semua asli atau uang kembali dijamin.",
  ui_story_5035_50350201_17_dialog_content = "Jangan ragu untuk berteriak sepenuh hati dan dapatkan pengalaman yang luar biasa dan menakutkan.",
  ui_story_5035_50350201_18_dialog_content = "Aku tak sabar untuk itu!",
  ui_story_5035_50350201_19_dialog_content = "Omong-omong, apakah ini usaha terbaru Nina?",
  ui_story_5035_50350201_20_dialog_content = "Benar. Dia baru-baru ini mengalihkan perhatiannya ke real estat dan menjadikan rumah berhantu ini sebagai daya tarik.",
  ui_story_5035_50350201_21_dialog_content = "Meskipun segala sesuatunya tidak berjalan persis seperti yang dia rencanakan, ini adalah properti pertamanya.",
  ui_story_5035_50350201_22_dialog_content = "Secara alami, saya harus melakukan semua yang saya bisa untuk mendukungnya.",
  ui_story_5035_50350201_23_dialog_content = "Rumah besar yang Anda lihat sebelum Anda dipilih oleh kami berdua setelah penyaringan yang cermat.",
  ui_story_5035_50350201_24_dialog_content = "Membeli rumah sebesar itu pasti menghabiskan banyak biaya.",
  ui_story_5035_50350201_25_dialog_content = "Yah, tidak juga. Itu luar biasa murah.",
  ui_story_5035_50350201_26_dialog_content = "Bahkan renovasi rumah hantu membutuhkan biaya yang tidak sedikit.",
  ui_story_5035_50350201_27_dialog_content = "Itu sebabnya saya percaya pada kesuksesan finansial proyek ini.",
  ui_story_5035_50350201_28_dialog_content = "<color=#e8d9bb>* Jangkrik *</color>",
  ui_story_5035_50350201_29_dialog_content = "Yah, itu baru saja dibuka, jadi saya yakin itu hanya perlu beberapa waktu untuk menangkapnya...",
  ui_story_5035_50350201_30_dialog_content = "Bukan begitu, Bu Nina?",
  ui_story_5035_50350201_31_dialog_content = "...",
  ui_story_5035_50350201_32_dialog_content = "Hmm, kurasa dia tidak mendengarku.",
  ui_story_5035_50350201_33_dialog_content = "Mengapa kita tidak pergi menyapa, PlayerName.",
  ui_story_5035_50350201_34_dialog_content = "Tolong, satu per satu!",
  ui_story_5035_50350201_35_dialog_content = "Ini dia, gadis tiket murahan!",
  ui_story_5035_50350201_36_dialog_content = "Cepat, giliranku!",
  ui_story_5035_50350201_37_dialog_content = "Pepi, jangan coba memotong antrean!",
  ui_story_5035_50350201_38_dialog_content = "Wah! Tuan Navigator dan Wakil!",
  ui_story_5035_50350201_39_dialog_content = "Selamat pagi, PlayerName. Sudah lama!",
  ui_story_5035_50350201_40_dialog_content = "Terima kasih telah datang ke Rumah Hantu Andersen. Saya akan memberi tahu Minos untuk memberi Anda diskon khusus.",
  ui_story_5035_50350201_41_dialog_content = "T-Terima kasih banyak!",
  ui_story_5035_50350201_42_dialog_content = "Itu adalah keputusan yang bijaksana bagi saya untuk membawa Anda bersama, PlayerName.",
  ui_story_5035_50350201_43_dialog_content = "Benar...",
  ui_story_5035_50350201_44_dialog_content = "Omong-omong, mengapa Anda ingin membangun rumah hantu sejak awal?",
  ui_story_5035_50350201_45_dialog_content = "Maksudku, aku akan berasumsi bahwa kau sangat takut dengan hal-hal seperti ini...",
  ui_story_5035_50350201_46_dialog_content = "Bagaimana ... Betapa kasarnya Anda, PlayerName!",
  ui_story_5035_50350201_47_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_5035_50350201_48_dialog_content = "Harap berpegang pada rintisan.",
  ui_story_5035_50350201_49_dialog_content = "Trims!",
  ui_story_5035_50350201_50_dialog_content = "Tapi bukankah pestamu? <color=#FFB400>satu orang pendek</color>?",
  ui_story_5035_50350201_51_dialog_content = "Apa?",
  ui_story_5035_50350201_52_dialog_content = "<size=50>Ah!</size>",
  ui_story_5035_50350201_53_dialog_content = "Berhentilah mempermalukan kami, gadis pwetty!",
  ui_story_5035_50350201_54_dialog_content = "Hee, maksud saya Anda perlu satu orang lagi untuk mendapatkan diskon!",
  ui_story_5035_50350201_55_dialog_content = "Datang dengan lebih banyak teman lain kali!",
  ui_story_5035_50350201_56_dialog_content = "A-Baiklah, kalau begitu kita masuk sekarang.",
  ui_story_5035_50350201_57_dialog_content = "Selamat datang!",
  ui_story_5035_50350201_58_dialog_content = "Kamu melihat, PlayerName, ada banyak orang yang takut hantu...",
  ui_story_5035_50350201_59_dialog_content = "Itu sebabnya saya membangun rumah berhantu!",
  ui_story_5035_50350201_60_dialog_content = "Dan itu berjalan persis seperti yang saya rencanakan!",
  ui_story_5035_50350201_61_dialog_content = "Itu agak... masuk akal.",
  ui_story_5035_50350201_62_dialog_content = "<color=#e8d9bb>Gemerisik, gemerisik...</color>",
  ui_story_5035_50350201_63_dialog_content = "Eh?",
  ui_story_5035_50350201_64_dialog_content = "Nina tidak merencanakan suara aneh itu juga, kan?",
  ui_story_5035_50350201_65_dialog_content = "Tunggu sebentar, dimana Nina?",
  ui_story_5035_50350201_66_dialog_content = "Aku tidak tahuaaaaa!",
  ui_story_5035_50350201_67_dialog_content = "Aum...",
  ui_story_5035_50350201_68_dialog_content = "Graaagh!",
  ui_story_5035_50350201_69_dialog_content = "Ini adalah sebuah Eclipsite!",
  ui_story_5035_50350201_70_dialog_content = "Ayo, berhenti menyelinap mencoba menakuti orang!",
  ui_story_5035_50350202_1_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5035_50350202_2_dialog_content = "Untungnya, pakaian saya tetap bersih.",
  ui_story_5035_50350202_3_dialog_content = "Ini salahmu, Minos. Mengapa Anda tidak menyadari bahaya yang mengintai?",
  ui_story_5035_50350202_4_dialog_content = "Tentu saja, Nona Nina. Aku pantas dihukum.",
  ui_story_5035_50350202_5_dialog_content = "(Nina tampaknya tidak seperti biasanya kejam dan keras hari ini.)",
  ui_story_5035_50350202_6_dialog_content = "PlayerName dan temannya baru saja tiba, jadi mengapa Anda tidak mengantar mereka masuk dan menjadi pemandu mereka?",
  ui_story_5035_50350202_7_dialog_content = "<color=#FFB400>Orang itu</color> di rumah masih menunggu Anda untuk pergi bernegosiasi dan menyusun kontrak.",
  ui_story_5035_50350202_8_dialog_content = "Anda sudah menunggu ini, bukan?",
  ui_story_5035_50350202_9_dialog_content = "Tidak sama sekali, Nona Nina. Yang kuinginkan hanyalah membuat rumah hantu itu menguntungkanmu...",
  ui_story_5035_50350202_10_dialog_content = "Cukup. Hukumanmu adalah menghilang dari pandanganku.",
  ui_story_5035_50350202_11_dialog_content = "Dimengerti, Nona Nina.",
  ui_story_5035_50350202_12_dialog_content = "<color=#e8d9bb>Rumah Hantu Andersen: Koridor Lantai Pertama</color>",
  ui_story_5035_50350202_13_dialog_content = "Ini adalah lantai pertama Rumah Hantu Andersen.",
  ui_story_5035_50350202_14_dialog_content = "Rumah ini memiliki tata ruang yang sangat kompleks dengan banyak pintu dan jendela palsu.",
  ui_story_5035_50350202_15_dialog_content = "Sangat mudah tersesat jika Anda tidak tahu jalannya.",
  ui_story_5035_50350202_16_dialog_content = "Jika Anda ingin melangkah lebih jauh di lantai pertama, Anda dapat mengikuti saya.",
  ui_story_5035_50350202_17_dialog_content = "Oh, maaf, maksud saya jika Anda ingin melanjutkan ke lantai dua.",
  ui_story_5035_50350202_18_dialog_content = "(Dia tampaknya terganggu.)",
  ui_story_5035_50350202_19_dialog_content = "Minos, apakah ada sesuatu yang terjadi antara kamu dan Nina?",
  ui_story_5035_50350202_20_dialog_content = "Siapa orang yang dimaksud Nina?",
  ui_story_5035_50350202_21_dialog_content = "Itu hanya pertengkaran kecil. Saya minta maaf karena membuat Anda semua terjebak dalam hal ini, PlayerName, Keburukan.",
  ui_story_5035_50350202_22_dialog_content = "Ketegangan dimulai karena seorang pria yang datang mengunjungi Miss Nina dua hari yang lalu.",
  ui_story_5035_50350202_23_dialog_content = "Rumah hantu itu baru saja dibuka, tetapi dia terus bersikeras untuk menyewanya dalam jangka panjang.",
  ui_story_5035_50350202_24_dialog_content = "Dia ingin menggunakannya sebagai set film atau semacamnya.",
  ui_story_5035_50350202_25_dialog_content = "Betulkah? Tapi rumah hantu itu sudah buka untuk bisnis.",
  ui_story_5035_50350202_26_dialog_content = "Itu adalah jawaban saya, tetapi dia tidak tergoyahkan dan bahkan membuat tawaran yang luar biasa.",
  ui_story_5035_50350202_27_dialog_content = "Jadi Anda menyetujuinya?",
  ui_story_5035_50350202_28_dialog_content = "Tentu saja tidak, tapi aku sekarang terjebak di tengah, jadi sudah... yah, tidak mudah.",
  ui_story_5035_50350202_29_dialog_content = "Tidak pernah berharap Anda berada di antara batu dan tempat yang sulit, Minos.",
  ui_story_5035_50350202_30_dialog_content = "Ha ha. Jangan menggodaku sekarang, PlayerName.",
  ui_story_5035_50350202_31_dialog_content = "Saya yakin sepertinya saya bisa menyelesaikan setiap masalah di bawah langit jika Anda hanya mempertimbangkan waktu saya telah berhasil, tetapi kadang-kadang saya mengalami kesulitan.",
  ui_story_5035_50350202_32_dialog_content = "Saya sebenarnya memiliki resolusi untuk situasi ini, Anda tahu.",
  ui_story_5035_50350202_33_dialog_content = "Jadi untuk sementara saya setuju untuk bekerja dengan pihak lain. Kecuali saya juga mengikatkan diri pada proyek sebagai produser sementara sehingga saya bisa bekerja dengannya.",
  ui_story_5035_50350202_34_dialog_content = "Setelah proyek selesai, saya akan memiliki semua informasi yang saya butuhkan untuk mengevaluasi apakah dia mitra bisnis yang cukup baik untuk Nona Nina.",
  ui_story_5035_50350202_35_dialog_content = "Apakah Anda menjalankannya dengan Nina?",
  ui_story_5035_50350202_36_dialog_content = "Yah, karena aku baru mengambil keputusan tadi malam...",
  ui_story_5035_50350202_37_dialog_content = "Hmm, aku bisa mengerti kenapa Nina marah.",
  ui_story_5035_50350202_38_dialog_content = "Bagaimanapun, kalian berdua adalah tamu kami, jadi tolong jangan khawatir tentang masalah ini.",
  ui_story_5035_50350202_39_dialog_content = "Silakan ikuti saya dalam tur berpemandu melalui rumah berhantu.",
  ui_story_5035_50350202_40_dialog_content = "Atau mungkin Anda lebih suka tamasya yang lebih spontan?",
  ui_story_5035_50350202_41_dialog_content = "Bagaimana menurutmu, Vice?",
  ui_story_5035_50350202_42_dialog_content = "Nah, kurang kaget dan asyiknya kalau dipandu oleh guide...",
  ui_story_5035_50350202_43_dialog_content = "Jadi saya pikir kita harus memutuskan sendiri ke mana kita pergi!",
  ui_story_5035_50350202_44_dialog_content = "Saya sangat menantikan apa yang disebut \"pertemuan paranormal nyata\"!",
  ui_story_5035_50350202_45_dialog_content = "Baiklah, setelah Anda, kemudian.",
  ui_story_5035_50350202_46_dialog_content = "Luar biasa!",
  ui_story_5035_50350202_47_dialog_content = "Omong-omong, Tuan Minos, saya benar-benar ingin tahu...",
  ui_story_5035_50350202_48_dialog_content = "Apakah benar-benar ada hantu di sini? Bukankah Nina takut pada mereka?",
  ui_story_5035_50350202_49_dialog_content = "Bagaimana Anda bisa membawa mereka ke sini?",
  ui_story_5035_50350202_50_dialog_content = "Yah, saya yakin dia tahu apa yang dia lakukan karena dia mengiklankannya seperti itu.",
  ui_story_5035_50350202_51_dialog_content = "Hmph, tentu saja hantu itu ada, dan mereka pasti ada di rumah ini!",
  ui_story_5035_50350202_52_dialog_content = "Siapa di sana?",
  ui_story_5035_50350202_53_dialog_content = "Saya datang murni karena keingintahuan ilmiah!",
  ui_story_5035_50350202_54_dialog_content = "Anda harus mempertimbangkan untuk bergabung dengan regu ekspedisi saya jika Anda juga tertarik!",
  ui_story_5035_50350202_55_dialog_content = "Ya, tentu saja!",
  ui_story_5035_50350202_56_dialog_content = "Oh tunggu, siapa kamu lagi?",
  ui_story_5035_50350202_57_dialog_content = "Saya Lilica, seorang detektif hantu terkenal!",
  ui_story_5035_50350202_58_dialog_content = "Tunggu sebentar!!",
  ui_story_5035_50350202_59_dialog_content = "Anda bertindak seolah-olah Anda belum pernah mendengar tentang saya.",
  ui_story_5035_50350202_60_dialog_content = "Kami-Kami tentu belum.",
  ui_story_5035_50350202_61_dialog_content = "*Mendesah...*",
  ui_story_5035_50350202_62_dialog_content = "Kalau begitu izinkan saya bertanya lagi: Apakah Anda bergabung dengan pasukan ekspedisi saya?",
  ui_story_5035_50350202_63_dialog_content = "Ini adalah kesempatan seumur hidup, lho!",
  ui_story_5035_50350202_64_dialog_content = "Peluang?",
  ui_story_5035_50350202_65_dialog_content = "Betul sekali. Lihat Cellulo di sebelah saya?",
  ui_story_5035_50350202_66_dialog_content = "Apakah yang Anda maksud: burung dengan kamera",
  ui_story_5035_50350202_67_dialog_content = "Itu lebih terlihat seperti kelelawar bagiku.",
  ui_story_5035_50350202_68_dialog_content = "Cellulo bukan burung atau kelelawar! Ini mitra film saya!",
  ui_story_5035_50350202_69_dialog_content = "(Mitra film?)",
  ui_story_5035_50350202_70_dialog_content = "Apakah dia yang sedang bernegosiasi denganmu, Minos?",
  ui_story_5035_50350202_71_dialog_content = "Tidak. Seingat saya, Nona Lilica adalah salah satu pengunjung hari ini.",
  ui_story_5035_50350202_72_dialog_content = "Aku tidak dengan siapa pun. Ini adalah proyek pribadi saya!",
  ui_story_5035_50350202_73_dialog_content = "Saya ingin mengabadikan seluruh petualangan saya di Rumah Hantu Andersen dalam film!",
  ui_story_5035_50350202_74_dialog_content = "Film-film bergaya realitas sedang marak di Umbraton akhir-akhir ini.",
  ui_story_5035_50350202_75_dialog_content = "Kalian mungkin menjadi bintang besar karena tampil di film saya!",
  ui_story_5035_50350202_76_dialog_content = "Oh, ngomong-ngomong, aku belum mendapatkan namamu.",
  ui_story_5035_50350202_77_dialog_content = "aku PlayerName. Ini adalah Wakil. Dan itu di sana...",
  ui_story_5035_50350202_78_dialog_content = "Mino, kan? Aku mendengar.",
  ui_story_5035_50350202_79_dialog_content = "Tampaknya Anda memiliki ingatan yang baik, Nona Lilica.",
  ui_story_5035_50350202_80_dialog_content = "Tentu saja, saya seorang detektif profesional! Ayo, tersenyum untuk kamera!",
  ui_story_5035_50350202_81_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_5035_50350202_82_dialog_content = "Oke, dengan foto itu, kalian bertiga sekarang menjadi anggota tim saya!",
  ui_story_5035_50350202_83_dialog_content = "Dengan senang hati!",
  ui_story_5035_50350202_84_dialog_content = "Apa pun untuk menyenangkan pelanggan.",
  ui_story_5035_50350202_85_dialog_content = "Seseorang setidaknya bisa bertanya padaku dulu...",
  ui_story_5035_50350301_1_dialog_content = "Oke, saya akan mulai syuting sekarang!",
  ui_story_5035_50350301_2_dialog_content = "Sebentar...",
  ui_story_5035_50350301_3_dialog_content = "Ada yang bisa saya bantu?",
  ui_story_5035_50350301_4_dialog_content = "Demi kesinambungan, bukankah saya harus keluar dan membuat celah di pintu masuk?",
  ui_story_5035_50350301_5_dialog_content = "Anda tahu, seperti...",
  ui_story_5035_50350301_6_dialog_content = "\"Halo, semuanya. Hari ini, saya di sini untuk membawa Anda ke dalam Rumah Hantu Andersen\" dan sebagainya.",
  ui_story_5035_50350301_7_dialog_content = "(Jadi hal-hal semacam ini biasanya semuanya dituliskan?!)",
  ui_story_5035_50350301_8_dialog_content = "Anda akan melihat pemiliknya, Nona Nina, di dekat gerbang. Keluar saja melalui pintu di sebelah kananmu.",
  ui_story_5035_50350301_9_dialog_content = "Jangan khawatir, tiket Anda akan tetap bagus, asalkan cuti tersebut bersifat sementara.",
  ui_story_5035_50350301_10_dialog_content = "Besar! Sampai jumpa lagi, kalau begitu!",
  ui_story_5035_50350301_11_dialog_content = "Lilica tampak sangat profesional.",
  ui_story_5035_50350301_12_dialog_content = "Harus dikatakan, saya agak tertarik melihat produk akhir sekarang.",
  ui_story_5035_50350301_13_dialog_content = "Anda tahu cara kerjanya, Wakil?",
  ui_story_5035_50350301_14_dialog_content = "Yah, tidak bisa mengatakan saya tahu banyak, hanya sedikit.",
  ui_story_5035_50350301_15_dialog_content = "<size=30>Saya telah menonton film seperti ini di lounge di Soroz sebelumnya...</size>",
  ui_story_5035_50350301_16_dialog_content = "Apa?!",
  ui_story_5035_50350301_17_dialog_content = "Kenapa aku tidak tahu tentang ini? Dari mana Anda bahkan mendapatkan kasetnya?",
  ui_story_5035_50350301_18_dialog_content = "Setiap kali kami datang ke Umbraton.",
  ui_story_5035_50350301_19_dialog_content = "Sebelum saya pergi, saya biasanya mengambil beberapa dengan harga murah.",
  ui_story_5035_50350301_20_dialog_content = "Oh, saya bahkan menemukan sutradara impian saya!",
  ui_story_5035_50350301_21_dialog_content = "Itu akan sedikit berlebihan, bukan begitu?",
  ui_story_5035_50350301_22_dialog_content = "Dia berspesialisasi dalam film horor dan saya menikmati semua yang dia buat!",
  ui_story_5035_50350301_23_dialog_content = "Jika Anda tertarik, PlayerName, saya bisa membagikannya! Saya merekomendasi-",
  ui_story_5035_50350301_24_dialog_content = "Berhenti sebentar! T-Itu tidak perlu.",
  ui_story_5035_50350301_25_dialog_content = "Penggemar film horor, ya?",
  ui_story_5035_50350301_26_dialog_content = "Saya ingin mendengar rekomendasi Anda.",
  ui_story_5035_50350301_27_dialog_content = "Pagi, Pak Joni. Apakah Anda bersiap-siap untuk menembak?",
  ui_story_5035_50350301_28_dialog_content = "Oke, bawa itu ke koridor barat, dan jangan menabrak apapun.",
  ui_story_5035_50350301_29_dialog_content = "Ya, Minos. Jika Anda tidak dapat membantu, beri jalan untuk tim prop.",
  ui_story_5035_50350301_30_dialog_content = "Bukan masalah.",
  ui_story_5035_50350301_31_dialog_content = "<color=#e8d9bb>Cincin—Cincin—</color>",
  ui_story_5035_50350301_32_dialog_content = "Apakah itu... salah satu alat peraga?",
  ui_story_5035_50350301_33_dialog_content = "Peti mati? Kami memecahkannya hanya untuk adegan-adegan penting. Terlihat nyata, bukan?",
  ui_story_5035_50350301_34_dialog_content = "Pengerjaannya paling indah.",
  ui_story_5035_50350301_35_dialog_content = "Dalam adegan apa itu akan ditampilkan?",
  ui_story_5035_50350301_36_dialog_content = "... Itu rahasia.",
  ui_story_5035_50350301_37_dialog_content = "Tunggu... \"Jonny\"? Seorang \"kru\"?",
  ui_story_5035_50350301_38_dialog_content = "(Pakaian...)",
  ui_story_5035_50350301_39_dialog_content = "AAA-Apakah kamu...",
  ui_story_5035_50350301_40_dialog_content = "Apakah kamu <color=#FFB400>sutradara jonny</color>, Jonny Madelin?",
  ui_story_5035_50350301_41_dialog_content = "Itu aku. Dan Anda...?",
  ui_story_5035_50350301_42_dialog_content = "Saya penggemar terbesar Anda!",
  ui_story_5035_50350301_43_dialog_content = "(Tidak mungkin, ini orangnya?)",
  ui_story_5035_50350301_44_dialog_content = "...",
  ui_story_5035_50350301_45_dialog_content = "Heh...",
  ui_story_5035_50350301_46_dialog_content = "Suatu kehormatan. Tunggu saja sampai film saya berikutnya, One Cut of Screams!, keluar.",
  ui_story_5035_50350301_47_dialog_content = "Saya akan terus menghasilkan film yang lebih baik.",
  ui_story_5035_50350301_48_dialog_content = "Inilah mengapa saya datang ke Rumah Hantu Andersen.",
  ui_story_5035_50350301_49_dialog_content = "Jadi, ini sudah malam. Sudahkah Anda memutuskan, Tuan Minos?",
  ui_story_5035_50350301_50_dialog_content = "Saya tidak pernah membuat keputusan bisnis besar dalam semalam, dan kesepakatan kami hanya sementara.",
  ui_story_5035_50350301_51_dialog_content = "Izinkan saya memperkenalkan Anda terlebih dahulu kepada para pemeran untuk film tersebut.",
  ui_story_5035_50350301_52_dialog_content = "Ini adalah Goldie. Dia akan membintangi bersama aktor lain yang akan tetap menjadi rahasia untuk saat ini, sehingga Anda bisa memanggilnya wanita terkemuka.",
  ui_story_5035_50350301_53_dialog_content = "Dia juga penyanyi yang baru debut. Yang populer pada saat itu juga.",
  ui_story_5035_50350301_54_dialog_content = "Hai! Terima kasih sebelumnya telah mendukung saya!",
  ui_story_5035_50350301_55_dialog_content = "Hei, kaulah yang kulihat di koran Umbraton...",
  ui_story_5035_50350301_56_dialog_content = "\"Live Boxing\", \"Penyanyi Populer Membuat Debut\"...",
  ui_story_5035_50350301_57_dialog_content = "<color=#FFB400>\"Pembukaan Rumah Hantu Anderson\"?!</color>",
  ui_story_5035_50350301_58_dialog_content = "Anda penyanyi ITU!",
  ui_story_5035_50350301_59_dialog_content = "Ya, itu saya. Cobalah untuk tidak berteriak terlalu keras!",
  ui_story_5035_50350301_60_dialog_content = "Jonny sangat beruntung karena mengontrak saya sebelum saya menjadi terkenal.",
  ui_story_5035_50350301_61_dialog_content = "Jika tidak, harga permintaan saya akan jauh lebih tinggi!",
  ui_story_5035_50350301_62_dialog_content = "Hmm…",
  ui_story_5035_50350301_63_dialog_content = "Hei, hanya bercanda! Lagipula aku masih pemula.",
  ui_story_5035_50350301_64_dialog_content = "Ini adalah film fitur pertama saya juga, jadi saya akan bekerja dua kali lebih keras.",
  ui_story_5035_50350301_65_dialog_content = "Keberuntunganku dan aku akan menjaga keberuntunganmu tetap utuh, Jonny!",
  ui_story_5035_50350301_66_dialog_content = "Ha, saya percaya pada potensi Anda.",
  ui_story_5035_50350301_67_dialog_content = "Oh, hampir lupa, ini Sadie, dia memainkan peran pendukung.",
  ui_story_5035_50350301_68_dialog_content = "...",
  ui_story_5035_50350301_69_dialog_content = "Jadi saya tidak pantas mendapatkan pengenalan lebih dari itu?",
  ui_story_5035_50350301_70_dialog_content = "Baiklah, saya tahu saya bukan siapa-siapa, jadi Anda tidak perlu menyanjung.",
  ui_story_5035_50350301_71_dialog_content = "Anda berada di hadapan Super Sadie, seorang jagoan yang tidak pernah bajingan.",
  ui_story_5035_50350301_72_dialog_content = "Kalian bisa memanggilku Sadie.",
  ui_story_5035_50350301_73_dialog_content = "Apakah berakting... bagian dari menjadi seorang jagoan?",
  ui_story_5035_50350301_74_dialog_content = "Yah, saya mengambil pekerjaan sampingan saat bisnis sedang lesu.",
  ui_story_5035_50350301_75_dialog_content = "Tapi saya telah melakukan ini dengan semangat swashbuckling sejati!",
  ui_story_5035_50350301_76_dialog_content = "Bagaimana dengan kalian, apakah kalian ekstra?",
  ui_story_5035_50350301_77_dialog_content = "Oh tidak sama sekali, kami di sini hanya untuk rumah hantu.",
  ui_story_5035_50350301_78_dialog_content = "Lebih tepatnya, kami di sini untuk melihat <color=#FFB400>\"pertemuan paranormal nyata\"</color>!",
  ui_story_5035_50350301_79_dialog_content = "\"Pertemuan paranormal nyata\"?",
  ui_story_5035_50350301_80_dialog_content = "Apakah hantu dan fenomena paranormal benar-benar ada?",
  ui_story_5035_50350301_81_dialog_content = "Ya, saya selalu percaya pada mereka!",
  ui_story_5035_50350301_82_dialog_content = "Dan mereka ada di sini... di Rumah Hantu Andersen?",
  ui_story_5035_50350301_83_dialog_content = "Ya. Itu kata Pak Minos.",
  ui_story_5035_50350301_84_dialog_content = "Katakan, jika kamu ketakutan, Sadie, aku akan melindungimu!",
  ui_story_5035_50350301_85_dialog_content = "Membosankan sekali.",
  ui_story_5035_50350301_86_dialog_content = "Hei!",
  ui_story_5035_50350301_87_dialog_content = "Itu hanya penipuan untuk menjual tiket. Aku tidak jatuh untuk itu.",
  ui_story_5035_50350301_88_dialog_content = "Tapi Anda jelas sangat menyukainya ...",
  ui_story_5035_50350301_89_dialog_content = "Ahaha, Miss Sadie adalah kepribadian yang cukup blak-blakan, sepertinya.",
  ui_story_5035_50350301_90_dialog_content = "Anda tidak punya banyak waktu lagi untuk memutuskan, Minos. Kami sudah mencari lokasi.",
  ui_story_5035_50350301_91_dialog_content = "Kalau begitu, bantu dirimu sendiri.",
  ui_story_5035_50350301_92_dialog_content = "Oke. Goldie, Sadie, ayo pergi.",
  ui_story_5035_50350301_93_dialog_content = "Sadi...?",
  ui_story_5035_50350301_94_dialog_content = "Aku, uh, kehilangan sesuatu, aku harus menemukannya.",
  ui_story_5035_50350301_95_dialog_content = "Sesuaikan dirimu. Lagi pula, Anda tidak ada di beberapa adegan berikutnya.",
  ui_story_5035_50350301_96_dialog_content = "Datang dengan Minos setelah Anda menemukannya.",
  ui_story_5035_50350301_97_dialog_content = "Ya, saya akan memastikan itu.",
  ui_story_5035_50350301_98_dialog_content = "Ayo bantu Sadie sambil menunggu Lilica.",
  ui_story_5035_50350301_99_dialog_content = "Ya, dia harus kembali saat itu.",
  ui_story_5035_50350301_100_dialog_content = "<color=#e8d9bb>Acak, acak ...</color>",
  ui_story_5035_50350301_101_dialog_content = "Aku mendengar dia datang!",
  ui_story_5035_50350301_102_dialog_content = "Di sini, Lilica!",
  ui_story_5035_50350301_103_dialog_content = "…?",
  ui_story_5035_50350301_104_dialog_content = "(Eclipsian) ... Berbicara dengan saya?",
  ui_story_5035_50350301_105_dialog_content = "II-Ini mengatakan sesuatu!",
  ui_story_5035_50350301_106_dialog_content = "Apakah Eclipsites ini tidak pernah tersesat?",
  ui_story_5035_50350301_107_dialog_content = "Anda kehilangan intinya, Anda berdua!",
  ui_story_5035_50350301_108_dialog_content = "Kita harus mengeluarkan mereka dari sini!",
  ui_story_5035_50350302_1_dialog_content = "Bagaimana mereka bisa masuk...?",
  ui_story_5035_50350302_2_dialog_content = "Nona Nina dan saya melakukan pemeriksaan keamanan rumah sebelum membuka bisnis.",
  ui_story_5035_50350302_3_dialog_content = "Tapi tata letak rumah ini rumit. Jika mereka masuk melalui pintu masuk lain, saya tidak akan dapat mendeteksi mereka dengan segera.",
  ui_story_5035_50350302_4_dialog_content = "(Semoga Nona Nina aman di pintu masuk...)",
  ui_story_5035_50350302_5_dialog_content = "Apa ada yang terluka?",
  ui_story_5035_50350302_6_dialog_content = "Nah, untuk mengalahkan Eclipsites itu mudah.",
  ui_story_5035_50350302_7_dialog_content = "Omong-omong, apa yang hilang darimu, Sadie?",
  ui_story_5035_50350302_8_dialog_content = "Nah, eh...",
  ui_story_5035_50350302_9_dialog_content = "Itu hanya alasan untuk menunda Jonny.",
  ui_story_5035_50350302_10_dialog_content = "Maksud saya, saya adalah seorang pemberani, jadi tidak mungkin saya kehilangan barang-barang saya.",
  ui_story_5035_50350302_11_dialog_content = "Saya hanya bosan mengikuti Jonny berkeliling dan mendengarkan dia berkhotbah.",
  ui_story_5035_50350302_12_dialog_content = "Benarkah?",
  ui_story_5035_50350302_13_dialog_content = "Dan saya kebetulan mengambil bagan lokasi filmnya ketika saya berbicara.",
  ui_story_5035_50350302_14_dialog_content = "(Tunggu sebentar, itu mencuri!)",
  ui_story_5035_50350302_15_dialog_content = "Saya hanya ingin tahu tentang lokasi pada grafik, tapi saya tidak bisa membuat kepala atau ekornya.",
  ui_story_5035_50350302_16_dialog_content = "Jadi saya membuang alasan untuk tetap tinggal.",
  ui_story_5035_50350302_17_dialog_content = "Ayo, bantu aku dan mari kita cari tahu apa isinya.",
  ui_story_5035_50350302_18_dialog_content = "Ah, aku mengerti sekarang!",
  ui_story_5035_50350302_19_dialog_content = "Sadie, Anda ingin bergabung dengan regu ekspedisi kami, kan?",
  ui_story_5035_50350302_20_dialog_content = "A-Apa?",
  ui_story_5035_50350302_21_dialog_content = "Tidak mungkin! Hentikan omong kosongmu, karena aku punya akal sehat!",
  ui_story_5035_50350302_22_dialog_content = "<anim type=Shake>Semua<size=45> itu </size>adalah <size=45>palsu</size> bisa <size=30>tidak pernah</size> membuat <size=45>sebuah</size> jagoan sejati <size=45>menjerit!</size></anim>",
  ui_story_5035_50350302_23_dialog_content = "<anim type=Shake><size=50>aku</size> hanya <size=45>di sini</size> untuk ruang lingkup<size=30> jika </size>rumah hantu<size=45> adalah obat bius!</size></anim>",
  ui_story_5035_50350302_24_dialog_content = "<anim type=Shake>Tidak seperti<size=45> Anda </size>mendengus, <size=30>Saya</size> akan<size=45> tidak pernah</size> jatuh untuk <size=45>aksi ini!</size></anim>",
  ui_story_5035_50350302_25_dialog_content = "(Dia sangat bersemangat.)",
  ui_story_5035_50350302_26_dialog_content = "Kalau begitu, mari kita lihat lokasi-lokasi ini, ya?",
  ui_story_5035_50350302_27_dialog_content = "Ini dia.",
  ui_story_5035_50350302_28_dialog_content = "Benar... sepertinya ada tiga tempat.",
  ui_story_5035_50350302_29_dialog_content = "Itu <color=#FFB400>kamar tidur lantai pertama</color>, <color=#FFB400>showroom lantai dua</color>, dan <color=#FFB400>ruang bawah tanah</color>.",
  ui_story_5035_50350302_30_dialog_content = "Hmm, ketiga ruangan tersebut menawarkan visual yang bagus dan sangat cocok untuk syuting.",
  ui_story_5035_50350302_31_dialog_content = "Mari kita periksa mereka secara berurutan!",
  ui_story_5035_50350302_32_dialog_content = "Meneliti? Periksa apa?",
  ui_story_5035_50350302_33_dialog_content = "Apakah ini berarti regu ekspedisi saya akan beraksi?",
  ui_story_5035_50350302_34_dialog_content = "Saya sudah selesai syuting urutan pembukaan. Bagaimana kabar kalian di sini?",
  ui_story_5035_50350302_35_dialog_content = "Kau kembali, Lilica!",
  ui_story_5035_50350302_36_dialog_content = "Ini dia Sadie, anggota terbaru regu kami!",
  ui_story_5035_50350302_37_dialog_content = "Saya bukan bagian dari ini.",
  ui_story_5035_50350302_38_dialog_content = "Hai, Sadi! Saya Lilica. Saya suka syuting, berburu hantu, dan makanan laut!",
  ui_story_5035_50350302_39_dialog_content = "Jangan seret aku ke dalam ini...",
  ui_story_5035_50350302_40_dialog_content = "Di sini, tersenyumlah ke kamera dan semoga kita menemukan lokasi paranormal yang sebenarnya!",
  ui_story_5035_50350302_41_dialog_content = "Aku bilang aku tidak mau... Baiklah, sudahlah. Senang bertemu denganmu.",
  ui_story_5035_50350302_42_dialog_content = "Ya!",
  ui_story_5035_50350302_43_dialog_content = "Semua anggota regu berkumpul!",
  ui_story_5035_50350302_44_dialog_content = "Jadi, apakah Anda sudah membuat kemajuan?",
  ui_story_5035_50350302_45_dialog_content = "Ya! Sadie mengambil bagan lokasi dari kru produksi dan kami memutuskan untuk mengikuti rute.",
  ui_story_5035_50350302_46_dialog_content = "Bagan lokasi? Betapa beruntung!",
  ui_story_5035_50350302_47_dialog_content = "Sadie, Anda telah memberikan kontribusi yang signifikan dalam pembuatan film Into the Haunted House!",
  ui_story_5035_50350302_48_dialog_content = "Saya akan menebalkan nama Anda dengan huruf besar di kredit pembuka!",
  ui_story_5035_50350302_49_dialog_content = "Tak perlu.",
  ui_story_5035_50350302_50_dialog_content = "Dan kredit bergulir di akhir, serta di poster!",
  ui_story_5035_50350302_51_dialog_content = "Tidak perlu minta maaf...",
  ui_story_5035_50350302_52_dialog_content = "Dan di bagian untuk Terima Kasih Khusus! Dan di sampul kaset video...",
  ui_story_5035_50350302_53_dialog_content = "...",
  ui_story_5035_50350302_54_dialog_content = "Kita harus bergegas ke lokasi pertama!",
  ui_story_5035_50350302_55_dialog_content = "Ya! Tujuan—kamar tidur di lantai pertama!",
  ui_story_5035_50350302_56_dialog_content = "Into the Haunted House telah resmi mulai syuting! Berteriak sepuasnya, semuanya!",
  ui_story_5035_50350401_1_dialog_content = "<color=#e8d9bb>Rumah Hantu Andersen: Koridor Lantai Pertama</color>",
  ui_story_5035_50350401_2_dialog_content = "(Semua liku-liku ini membuatku pusing...)",
  ui_story_5035_50350401_3_dialog_content = "Tunggu, semuanya, hanya dua koridor lagi di depan dan kita akan tiba.",
  ui_story_5035_50350401_4_dialog_content = "Minos penuh perhatian seperti biasanya.",
  ui_story_5035_50350401_5_dialog_content = "Kau tahu, aku suka apa yang kau lakukan dengan rumah hantu ini.",
  ui_story_5035_50350401_6_dialog_content = "Tangga ke mana-mana, jendela yang dirancang seperti sarang laba-laba... Pengunjung Anda pasti akan tersesat di sini.",
  ui_story_5035_50350401_7_dialog_content = "Sebenarnya, kami mempertahankan tata letak asli bangunan ini.",
  ui_story_5035_50350401_8_dialog_content = "Semua desain eksentrik ini harus dikaitkan dengan pemilik aslinya, Lady Astor.",
  ui_story_5035_50350401_9_dialog_content = "Siapa Nyonya Astor?",
  ui_story_5035_50350401_10_dialog_content = "Ooh, ini dia, eksposisi latar belakang!",
  ui_story_5035_50350401_11_dialog_content = "Menempatkannya di video akan membantu membangun suasana yang menakutkan!",
  ui_story_5035_50350401_12_dialog_content = "Berdiri di sini, Minos. Ya, sedikit lagi.",
  ui_story_5035_50350401_13_dialog_content = "Apakah ini baik-baik saja, Lilica?",
  ui_story_5035_50350401_14_dialog_content = "Ya! Sekarang Anda bisa mulai!",
  ui_story_5035_50350401_15_dialog_content = "Ahem. Meskipun kami tidak yakin berapa kali rumah ini telah berpindah tangan, rumah ini pada awalnya dimiliki oleh Lady Astor.",
  ui_story_5035_50350401_16_dialog_content = "Lady Astor tidak memiliki kerabat dekat. Dia tinggal di sini sendirian dengan pelayannya.",
  ui_story_5035_50350401_17_dialog_content = "Dia eksentrik dan menderita paranoia parah.",
  ui_story_5035_50350401_18_dialog_content = "Begitu matahari terbenam, dia akan selalu khawatir bahwa sesuatu yang najis akan masuk ke dalam rumah dan mencoba membunuhnya...",
  ui_story_5035_50350401_19_dialog_content = "Aghhh!",
  ui_story_5035_50350401_20_dialog_content = "A-Apa-apaan ini, Wakil?!",
  ui_story_5035_50350401_21_dialog_content = "Heh, aku baik-baik saja, aku hanya bisa berteriak di saat-saat penting seperti itu.",
  ui_story_5035_50350401_22_dialog_content = "Lalu apa, lalu apa?",
  ui_story_5035_50350401_23_dialog_content = "Jadi...",
  ui_story_5035_50350401_24_dialog_content = "Dia menghabiskan semua asetnya dan mengubah mansion menjadi labirin.",
  ui_story_5035_50350401_25_dialog_content = "Dia menambahkan banyak jendela dan tangga tanpa tujuan dan tidur di kamar tidur yang berbeda setiap malam.",
  ui_story_5035_50350401_26_dialog_content = "Lilin di samping tempat tidurnya akan menyala sepanjang malam, membuat bayangan bahunya yang menggigil di dinding.",
  ui_story_5035_50350401_27_dialog_content = "Aaaah!",
  ui_story_5035_50350401_28_dialog_content = "Dia akan berteriak ketika lilin padam, cukup keras dan menusuk untuk mengejutkan semua pelayan.",
  ui_story_5035_50350401_29_dialog_content = "Akhirnya, dia tewas dalam kebakaran.",
  ui_story_5035_50350401_30_dialog_content = "Lilin-lilin membakar ruangan, dan Lady Astor melarikan diri dengan panik.",
  ui_story_5035_50350401_31_dialog_content = "Labirin yang dia bangun berubah menjadi sangkar yang mematikan.",
  ui_story_5035_50350401_32_dialog_content = "Para pelayan mencoba menemukannya tetapi akhirnya tewas dalam api itu sendiri.",
  ui_story_5035_50350401_33_dialog_content = "Seharusnya, pemilik sebelumnya masih bisa mendengar suara pelayan yang berlari di malam hari.",
  ui_story_5035_50350401_34_dialog_content = "Aku memeriksa seluruh rumah, tapi aku masih tidak yakin mayat mereka tidak tergeletak di sudut dan celah yang belum ditemukan...",
  ui_story_5035_50350401_35_dialog_content = "Aghhh!",
  ui_story_5035_50350401_36_dialog_content = "Yah, itu akhir dari itu, saya kira.",
  ui_story_5035_50350401_37_dialog_content = "Memotong! Itu luar biasa!",
  ui_story_5035_50350401_38_dialog_content = "Tepat pada waktunya bagi kita untuk mencapai kamar tidur lantai pertama. Silahkan...",
  ui_story_5035_50350401_39_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5035_50350401_40_dialog_content = "Aduh!",
  ui_story_5035_50350401_41_dialog_content = "Seperti yang Anda tahu, saya baru saja membuka pintu palsu.",
  ui_story_5035_50350401_42_dialog_content = "Harap berhati-hati agar Anda tidak berjalan tepat ke dinding seperti yang baru saja saya lakukan.",
  ui_story_5035_50350401_43_dialog_content = "Apakah Anda yakin Anda baik-baik saja?",
  ui_story_5035_50350401_44_dialog_content = "Pintu yang benar ada di sebelah kanan. Ikuti aku.",
  ui_story_5035_50350401_45_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5035_50350401_46_dialog_content = "Ya-",
  ui_story_5035_50350401_47_dialog_content = "-Hah?",
  ui_story_5035_50350401_48_dialog_content = "Ruangan ini terlihat... polos, bahkan sedikit compang-camping.",
  ui_story_5035_50350401_49_dialog_content = "Namun pencahayaannya sangat cocok untuk menciptakan suasana seram.",
  ui_story_5035_50350401_50_dialog_content = "Tolong berikan saya grafiknya, Sadie, jadi saya bisa melihat berapa banyak adegan yang direncanakan di sini.",
  ui_story_5035_50350401_51_dialog_content = "Ini dia.",
  ui_story_5035_50350401_52_dialog_content = "Ah, hmm, aku mengerti...",
  ui_story_5035_50350401_53_dialog_content = "Hei, semuanya, ayo lihat ini!",
  ui_story_5035_50350401_54_dialog_content = "Ini adalah replika televisi yang sangat realistis!",
  ui_story_5035_50350401_55_dialog_content = "Mari kita berfoto bersama dengannya!",
  ui_story_5035_50350401_56_dialog_content = "Itu bukan penyangga untuk rumah hantu atau bagian dari set film.",
  ui_story_5035_50350401_57_dialog_content = "Itu salah satu yang selamat dari kebakaran.",
  ui_story_5035_50350401_58_dialog_content = "(Wow, sejauh yang saya tahu, Anda hanya dapat menemukan hal-hal itu di Illumina...)",
  ui_story_5035_50350401_59_dialog_content = "Hmph, itu tidak lebih dari sebuah relik biasa.",
  ui_story_5035_50350401_60_dialog_content = "Jangan remehkan televisi! Ini bisa menjadi prop film horor yang efektif jika digunakan dengan benar.",
  ui_story_5035_50350401_61_dialog_content = "Misalnya, Anda bisa melihat pantulan sosok tak dikenal di layar gelap...",
  ui_story_5035_50350401_62_dialog_content = "Atau seorang wanita menakutkan berambut panjang bisa merangkak keluar dari situ...",
  ui_story_5035_50350401_63_dialog_content = "Yuk, kita foto di sebelahnya!",
  ui_story_5035_50350401_64_dialog_content = "<color=#e8d9bb>Ting…</color>",
  ui_story_5035_50350401_65_dialog_content = "Um…",
  ui_story_5035_50350401_66_dialog_content = "Tidak mungkin, tidak mungkin...!",
  ui_story_5035_50350401_67_dialog_content = "Jangan bilang…",
  ui_story_5035_50350401_68_dialog_content = "<color=#e8d9bb>Ksss... Ksss...</color>",
  ui_story_5035_50350401_69_dialog_content = "Halo.",
  ui_story_5035_50350401_70_dialog_content = "Ahhhh, ini dia!!!!",
  ui_story_5035_50350401_71_dialog_content = "Ini dia! Menarik sekali! Aku harus merekamnya!",
  ui_story_5035_50350401_72_dialog_content = "Halo. Apakah Anda bagian dari pemeran, cabul bertopeng, atau roh rekaman video?",
  ui_story_5035_50350401_73_dialog_content = "(Tidak ada yang namanya roh rekaman video!)",
  ui_story_5035_50350401_74_dialog_content = "Anda tidak mengenal saya, tetapi saya mengenal Anda.",
  ui_story_5035_50350401_75_dialog_content = "Tidak apa-apa, aku tahu kamu sekarang. Katakan halo ke kamera! Keju!",
  ui_story_5035_50350401_76_dialog_content = "Saya ingin memainkan sebuah permainan.",
  ui_story_5035_50350401_77_dialog_content = "Tentu, bukan masalah!",
  ui_story_5035_50350401_78_dialog_content = "(Mengapa dia begitu antusias tentang hal itu ...)",
  ui_story_5035_50350401_79_dialog_content = "Jika Anda bertanya kepada saya, ini jelas difilmkan sebelumnya.",
  ui_story_5035_50350401_80_dialog_content = "Orang bertopeng itu tidak pernah menjawab pertanyaan Lilica.",
  ui_story_5035_50350401_81_dialog_content = "Tidak perlu bagi saya untuk menjawab setiap pertanyaan.",
  ui_story_5035_50350401_82_dialog_content = "?!",
  ui_story_5035_50350401_83_dialog_content = "Karena tiga teka-teki saya menunggu Anda.",
  ui_story_5035_50350401_84_dialog_content = "Sekarang, biarkan permainan dimulai.",
  ui_story_5035_50350401_85_dialog_content = "Ruangan ini terkunci di belakang Anda segera setelah Anda masuk.",
  ui_story_5035_50350401_86_dialog_content = "<color=#e8d9bb>Berdetak...</color>",
  ui_story_5035_50350401_87_dialog_content = "Itu tidak bergeming... I-Hal itu mengatakan yang sebenarnya!",
  ui_story_5035_50350401_88_dialog_content = "Hanya agar Anda tidak sepenuhnya dirugikan ...",
  ui_story_5035_50350401_89_dialog_content = "Saya akan memberi Anda petunjuk tentang di mana saya menyembunyikan kuncinya.",
  ui_story_5035_50350401_90_dialog_content = "Apakah Anda hidup atau mati sepenuhnya terserah Anda.",
  ui_story_5035_50350401_91_dialog_content = "Uh, Minos, apa yang terjadi di sini?",
  ui_story_5035_50350401_92_dialog_content = "Sangat penting bagi kepala pelayan untuk tetap tenang setiap saat, PlayerName, tetapi dengan menyesal saya harus memberi tahu Anda bahwa ...",
  ui_story_5035_50350401_93_dialog_content = "Perkembangan saat ini tidak ada dalam pengaturan saya.",
  ui_story_5035_50350401_94_dialog_content = "Dengarkan baik-baik sekarang: Pertanyaan 1, siapa pemilik rumah besar ini?",
  ui_story_5035_50350401_95_option_content = "Nyonya Astor",
  ui_story_5035_50350401_96_dialog_content = "Sulit dipercaya...",
  ui_story_5035_50350401_97_dialog_content = "Anda benar-benar lupa siapa yang menghembuskan kehidupan baru ke dalam rumah ini.",
  ui_story_5035_50350401_98_dialog_content = "Sayang sekali Anda tidak akan mendapatkan kesempatan untuk meminta maaf kepadanya secara langsung sekarang.",
  ui_story_5035_50350401_99_dialog_content = "Jangan lupakan Nona Nina, PlayerName...",
  ui_story_5035_50350401_100_option_content = "Nona Nina",
  ui_story_5035_50350401_101_dialog_content = "Sulit dipercaya...",
  ui_story_5035_50350401_102_dialog_content = "Anda benar-benar mengabaikan pemilik aslinya.",
  ui_story_5035_50350401_103_dialog_content = "Anda dapat memberi hormat ketika Anda melihatnya di neraka.",
  ui_story_5035_50350401_104_dialog_content = "Saya menceritakan kisah Lady Astor kepada Anda hanya sepuluh menit yang lalu, PlayerName...",
  ui_story_5035_50350401_105_dialog_content = "Tidak adil! Ini adalah situasi yang tidak menguntungkan!",
  ui_story_5035_50350401_106_dialog_content = "Pertanyaan 2, berapa banyak pintu yang dimiliki rumah ini?",
  ui_story_5035_50350401_107_dialog_content = "(Bagus, pertanyaan yang seharusnya memiliki satu jawaban konkret...)",
  ui_story_5035_50350401_108_dialog_content = "Aku mengandalkanmu, Minos.",
  ui_story_5035_50350401_109_dialog_content = "Untungnya, saya memiliki peta rumah pada saya, untuk berjaga-jaga. Biar saya cek...",
  ui_story_5035_50350401_110_dialog_content = "Siapa yang tahu itu? Saya tidak berpikir bahkan Anda melakukannya, dasar bajingan bertopeng!",
  ui_story_5035_50350401_111_dialog_content = "...",
  ui_story_5035_50350401_112_dialog_content = "Oh, tidak!",
  ui_story_5035_50350401_113_dialog_content = "Tidak menjawab tetaplah sebuah jawaban. Kasihan itu salah.",
  ui_story_5035_50350401_114_dialog_content = "Apa? Saya tidak pernah mengatakan saya menjawab! Ini konyol!",
  ui_story_5035_50350401_115_dialog_content = "Anda sebaiknya mempertimbangkan apa yang akan dipikirkan pemirsa saya tentang Anda setelah video saya dirilis!",
  ui_story_5035_50350401_116_dialog_content = "Pada tingkat ini, kita kacau jika kita tidak bisa menjawab pertanyaan terakhir dengan benar...",
  ui_story_5035_50350401_117_dialog_content = "Pertanyaan 3, tidak ada kunci di bawah televisi.",
  ui_story_5035_50350401_118_dialog_content = "Apa? Itu pertanyaan atau pernyataan?",
  ui_story_5035_50350401_119_dialog_content = "Untuk amannya, mari kita periksa, PlayerName.",
  ui_story_5035_50350401_120_dialog_content = "Biarkan aku yang melakukannya!",
  ui_story_5035_50350401_121_dialog_content = "Ah!",
  ui_story_5035_50350401_122_dialog_content = "Sebuah kunci! Hal ini tampaknya ... menipu mudah.",
  ui_story_5035_50350401_123_dialog_content = "aku meraihnya...",
  ui_story_5035_50350401_124_dialog_content = "Salah. Anda jatuh untuk pengalihan sederhana, jalan keluar yang mudah.",
  ui_story_5035_50350401_125_dialog_content = "Selamat karena tidak ada yang benar. Sekarang ini <color=#FFB400>waktu hukuman</color>.",
  ui_story_5035_50350401_126_dialog_content = "Apa?!",
  ui_story_5035_50350401_127_dialog_content = "Ini gila... Tidak bisakah kamu melakukan sesuatu, Minos?",
  ui_story_5035_50350401_128_dialog_content = "Ya, bukankah ada seperti, jalan rahasia atau kunci cadangan?",
  ui_story_5035_50350401_129_dialog_content = "Ini adalah saat yang paling tepat untuk comeback!",
  ui_story_5035_50350401_130_dialog_content = "<color=#e8d9bb>Gruduk… Gruduk…</color>",
  ui_story_5035_50350401_131_dialog_content = "Saya pikir ada sesuatu yang datang dengan cara ini.",
  ui_story_5035_50350401_132_dialog_content = "Aku akan membuat ini singkat. Saya hanya punya satu saran—",
  ui_story_5035_50350401_133_dialog_content = "Graagh!",
  ui_story_5035_50350401_134_dialog_content = "<anim type=Shake><size=45>Groar!</size></anim>",
  ui_story_5035_50350401_135_dialog_content = "Ini mendobrak pintu. Lari sekarang!",
  ui_story_5035_50350501_1_dialog_content = "Grah...",
  ui_story_5035_50350501_2_dialog_content = "Saatnya saya untuk bersinar!",
  ui_story_5035_50350501_3_dialog_content = "Grah...",
  ui_story_5035_50350501_4_dialog_content = "(Huh, Eclipsite ini terasa agak lembut untuk pukulan ...)",
  ui_story_5035_50350501_5_dialog_content = "(Ini seperti saya sedang memukuli bantal yang sangat empuk!)",
  ui_story_5035_50350501_6_dialog_content = "Tunggu, aku harus tetap fokus dan tidak terganggu!",
  ui_story_5035_50350501_7_dialog_content = "Serang, Selulo!",
  ui_story_5035_50350501_8_dialog_content = "Astaga!",
  ui_story_5035_50350501_9_dialog_content = "(Itu jatuh sebelum dipukul! Apakah... melakukan ini dengan sengaja?)",
  ui_story_5035_50350501_10_dialog_content = "Tidak menyangka kamu sebaik ini.",
  ui_story_5035_50350501_11_dialog_content = "Hmph!",
  ui_story_5035_50350501_12_dialog_content = "Yah, aku!",
  ui_story_5035_50350501_13_dialog_content = "Maksudku, aku kapten regu ekspedisi.",
  ui_story_5035_50350501_14_dialog_content = "Di sini, kami memiliki terobosan! Into the Haunted House semakin menarik!",
  ui_story_5035_50350501_15_dialog_content = "*Squeal* Pengalaman yang hanya akan dialami oleh karakter utama!",
  ui_story_5035_50350501_16_dialog_content = "Mari kita mengisi, PlayerName!",
  ui_story_5035_50350501_17_dialog_content = "Siap!",
  ui_story_5035_50350501_18_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5035_50350501_19_dialog_content = "Aduh...",
  ui_story_5035_50350501_20_dialog_content = "Tunggu, kamu...",
  ui_story_5035_50350501_21_dialog_content = "Permainan telah berakhir.",
  ui_story_5035_50350501_22_dialog_content = "?!",
  ui_story_5035_50350501_23_dialog_content = "(Itu <color=#FFB400>dia</color> suara.)",
  ui_story_5035_50350501_24_dialog_content = "II-Apakah semangat rekaman video itu terwujud?",
  ui_story_5035_50350501_25_dialog_content = "Maafkan aku karena menyebutmu bajingan bertopeng!",
  ui_story_5035_50350501_26_dialog_content = "Seperti yang Anda lihat, pemirsa, ini adalah salah satu hantu yang tersembunyi di rumah.",
  ui_story_5035_50350501_27_dialog_content = "Kameranya agak goyah, tetapi mengungkapkan paranormal adalah tugas saya.",
  ui_story_5035_50350501_28_dialog_content = "Aku tidak akan mundur dalam ketakutan dengan mudah, a-dan...",
  ui_story_5035_50350501_29_dialog_content = "Saya... Saya akan mengambil satu langkah lebih dekat agar Anda dapat melihat lebih jelas.",
  ui_story_5035_50350501_30_dialog_content = "A-Dan langkah lain...",
  ui_story_5035_50350501_31_dialog_content = "...",
  ui_story_5035_50350501_32_dialog_content = "Tolong kembali sekarang, Lilica!",
  ui_story_5035_50350501_33_dialog_content = "Keburukan, PlayerName, jika yang terburuk terjadi pada saya, tolong ambil rekamannya...",
  ui_story_5035_50350501_34_dialog_content = "Kalian semua...",
  ui_story_5035_50350501_35_dialog_content = "*Menangis...*",
  ui_story_5035_50350501_36_dialog_content = "Tidak ada jalan keluar.",
  ui_story_5035_50350501_37_dialog_content = "<color=#e8d9bb>Berdengung...!</color>",
  ui_story_5035_50350501_38_dialog_content = "J-Jadi Eclipsites *sedang* memegang gergaji?!",
  ui_story_5035_50350501_39_dialog_content = "(Tunggu, mengapa saya mengharapkan ini sejak awal?)",
  ui_story_5035_50350501_40_dialog_content = "Pergi, anak laki-laki, dan buat mereka berteriak.",
  ui_story_5035_50350502_1_dialog_content = "(Ini aneh, tapi saya tidak akan pernah percaya adanya paranormal.)",
  ui_story_5035_50350502_2_dialog_content = "(Jika entitas bertopeng dapat mengontrol Eclipsites, itu mungkin berafiliasi dengan Eclipse.)",
  ui_story_5035_50350502_3_dialog_content = "(Tapi saya tidak merasakan Darkflow darinya.)",
  ui_story_5035_50350502_4_dialog_content = "(Mungkinkah itu benar-benar paranormal?)",
  ui_story_5035_50350502_5_dialog_content = "Rapid Torrent!",
  ui_story_5035_50350502_6_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5035_50350502_7_dialog_content = "(Ini menghindari seranganku!)",
  ui_story_5035_50350502_8_dialog_content = "Lagi! torrent cepat...",
  ui_story_5035_50350502_9_dialog_content = "Tunggu!",
  ui_story_5035_50350502_10_dialog_content = "Hah?",
  ui_story_5035_50350502_11_dialog_content = "Ini sejauh yang akan saya lakukan sebelum seseorang terluka parah.",
  ui_story_5035_50350502_12_dialog_content = "Benar bahwa.",
  ui_story_5035_50350502_13_dialog_content = "Ya, sebut saja berhenti sekarang.",
  ui_story_5035_50350502_14_dialog_content = "Sangat panas dalam kostum ini.",
  ui_story_5035_50350502_15_dialog_content = "Korgon, Kuma, Pengy?!",
  ui_story_5035_50350502_16_dialog_content = "Jadi ini berarti bahwa entitas bertopeng adalah...",
  ui_story_5035_50350502_17_dialog_content = "Heh, apakah semua orang menemukan bagian Shark Tooth Saw menarik?",
  ui_story_5035_50350502_18_dialog_content = "Biarkan aku mengantarmu keluar dari sini sekarang.",
  ui_story_5035_50350502_19_dialog_content = "Jadi itu Nina!",
  ui_story_5035_50350502_20_dialog_content = "Kau membuatku takut, Nina!",
  ui_story_5035_50350502_21_dialog_content = "Saya kira tidak ada yang tahu kecuali Pak Minos?",
  ui_story_5035_50350502_22_dialog_content = "Tidak heran Minos menyuruhku berhenti syuting saat pertempuran usai.",
  ui_story_5035_50350502_23_dialog_content = "Saya pikir itu semacam tabu, tapi dia hanya melindungi rahasia dagang!",
  ui_story_5035_50350502_24_dialog_content = "Izinkan saya untuk membela diri. Ini semua rencana Miss Nina untuk kegiatan rumah hantu.",
  ui_story_5035_50350502_25_dialog_content = "Saya tidak menyadari itu dia sampai dia membuka pintu dan masuk.",
  ui_story_5035_50350502_26_dialog_content = "Lagi pula, aku tahu suara dan posturnya dalam tidurku.",
  ui_story_5035_50350502_27_dialog_content = "Aduh...",
  ui_story_5035_50350502_28_dialog_content = "(Saya bahkan berusaha keras untuk menyembunyikan tingkah laku saya yang biasa juga!)",
  ui_story_5035_50350502_29_dialog_content = "Mino benar. Ini adalah pengalaman bonus yang saya siapkan untuk para pengunjung.",
  ui_story_5035_50350502_30_dialog_content = "Karena ini adalah pertunjukan perdana, jangan ragu untuk memberi saya umpan balik!",
  ui_story_5035_50350502_31_dialog_content = "Oke, saya akan mulai.",
  ui_story_5035_50350502_32_dialog_content = "Pertama, meskipun Anda berinteraksi dengan kami, pidato televisi terlalu kaku.",
  ui_story_5035_50350502_33_dialog_content = "Ah, mengerti.",
  ui_story_5035_50350502_34_dialog_content = "Pertanyaannya jelek dan membuat kami merasa seperti baru saja dikerjai.",
  ui_story_5035_50350502_35_dialog_content = "Aku tahu.",
  ui_story_5035_50350502_36_dialog_content = "Belum lagi demi-human Aurorian yang memainkan Eclipsites—",
  ui_story_5035_50350502_37_dialog_content = "Ahem! Oke, giliranku!",
  ui_story_5035_50350502_38_dialog_content = "Lihatlah kostum Eclipsite mereka!",
  ui_story_5035_50350502_39_dialog_content = "Hei, ini terasa seperti...",
  ui_story_5035_50350502_40_dialog_content = "Itu benar, saya membuatnya khusus untuk mereka!",
  ui_story_5035_50350502_41_dialog_content = "Itu membuat mereka kebal terhadap Luminatics normal dan tidak merasakan sakit saat dipukul!",
  ui_story_5035_50350502_42_dialog_content = "Ya, tapi satu-satunya kelemahan adalah ...",
  ui_story_5035_50350502_43_dialog_content = "Ini sangat panas di kostum.",
  ui_story_5035_50350502_44_dialog_content = "(Bagaimana dia bisa mengembangkan sesuatu yang begitu aneh?)",
  ui_story_5035_50350502_45_dialog_content = "Jadi dengan cara ini, rata-rata pengunjung juga bisa merasakan teror dan serunya melawan Eclipsites!",
  ui_story_5035_50350502_46_dialog_content = "Itulah pertemuan paranormal yang nyata dan gamblang yang saya banggakan!",
  ui_story_5035_50350502_47_dialog_content = "Tidak ada Aurorian yang mampu mengatasi ketakutan mereka akan kegelapan, ditambah...",
  ui_story_5035_50350502_48_dialog_content = "Saya merasa sangat lucu melihat wajah-wajah ketakutan di kamera keamanan.",
  ui_story_5035_50350502_49_dialog_content = "Oh-hohohoho!",
  ui_story_5035_50350502_50_dialog_content = "(Cara yang menggelikan untuk menggunakan kamera keamanan yang langka dan mahal...)",
  ui_story_5035_50350502_51_dialog_content = "(Dia tampaknya telah membangkitkan beberapa kesenangan aneh ...)",
  ui_story_5035_50350502_52_dialog_content = "Saya mengerti. Setidaknya idenya lebih solid dari komisi Jonny.",
  ui_story_5035_50350502_53_dialog_content = "Apakah Anda melakukan segalanya mulai dari membangun set dan merekrut orang hingga membuat kostum?",
  ui_story_5035_50350502_54_dialog_content = "Itu sangat mengesankan. Saya mengagumi semangat wirausaha Anda.",
  ui_story_5035_50350502_55_dialog_content = "Anda lakukan?!",
  ui_story_5035_50350502_56_dialog_content = "Kalau begitu... Silakan bekerja di Rumah Hantu Andersen!",
  ui_story_5035_50350502_57_dialog_content = "Biarkan aku merebus itu untuk sementara waktu.",
  ui_story_5035_50350502_58_dialog_content = "Saya mengambil pekerjaan Jonny di burung, tapi saya masih ingin menyelesaikannya.",
  ui_story_5035_50350502_59_dialog_content = "Hmm... Jadi begitulah...",
  ui_story_5035_50350502_60_dialog_content = "\"Pertemuan paranormal nyata\" sebenarnya mengacu pada aktor dalam kostum Eclipsite.",
  ui_story_5035_50350502_61_dialog_content = "Ada apa, Wakil? Sebagai pemimpin regu, saya rasa Anda agak kempes!",
  ui_story_5035_50350502_62_dialog_content = "Itu karena saya sudah menantikan ini sejak saya melihatnya di koran.",
  ui_story_5035_50350502_63_dialog_content = "Melihat pengungkapannya terasa sama buruknya dengan mempelajari rahasia di balik trik sulap.",
  ui_story_5035_50350502_64_dialog_content = "(Saya mengerti sekarang bagaimana ini bisa menjadi kekecewaan besar bagi Wakil ...)",
  ui_story_5035_50350502_65_dialog_content = "Tidak apa-apa, Wakil... Mungkin apa yang Anda harapkan ada di beberapa sudut yang belum kami jelajahi.",
  ui_story_5035_50350502_66_dialog_content = "Menurutmu begitu, ya?",
  ui_story_5035_50350502_67_dialog_content = "(Ups, apa yang saya katakan?)",
  ui_story_5035_50350502_68_dialog_content = "Maaf, Nona Wakil, baik Nona Nina maupun saya tidak menyadari bagaimana perasaan pengunjung seperti Anda.",
  ui_story_5035_50350502_69_dialog_content = "Maaf, Wakil.",
  ui_story_5035_50350502_70_dialog_content = "Tidak masalah. Lagipula, gagasan tentang makhluk paranormal adalah—",
  ui_story_5035_50350502_71_dialog_content = "Mungkin!",
  ui_story_5035_50350502_72_dialog_content = "Apa?",
  ui_story_5035_50350502_73_dialog_content = "Sebagai pemburu hantu, saya percaya paranormal mungkin ada di rumah ini!",
  ui_story_5035_50350502_74_dialog_content = "Tapi bahkan Nina dan Pak Minos bilang...",
  ui_story_5035_50350502_75_dialog_content = "Itu benar, tetapi mereka hanya menunjukkan kepada kita bagian yang dipentaskan.",
  ui_story_5035_50350502_76_dialog_content = "Bagaimana dengan bagian dan lokasi yang tidak dipentaskan?",
  ui_story_5035_50350502_77_dialog_content = "Yah, kita tidak tahu pasti...",
  ui_story_5035_50350502_78_dialog_content = "Tetapi jika itu tidak sepenuhnya tidak mungkin, itu berarti itu mungkin!",
  ui_story_5035_50350502_79_dialog_content = "Moto pasukan kami adalah, \"Hantu ada sampai terbukti sebaliknya!\"",
  ui_story_5035_50350502_80_dialog_content = "Ini hanya tujuan pertama kami. Bagaimana kita akan tahu tanpa melangkah lebih jauh?",
  ui_story_5035_50350502_81_dialog_content = "Itu masuk akal!",
  ui_story_5035_50350502_82_dialog_content = "(Kamu yakin tentang itu?!)",
  ui_story_5035_50350502_83_dialog_content = "Ya, Lilica benar, dan saya masih harus mencari lokasi untuk film itu.",
  ui_story_5035_50350502_84_dialog_content = "Kita harus melakukannya selagi kita masih punya waktu.",
  ui_story_5035_50350502_85_dialog_content = "Ya! Ayo pergi ke showroom di lantai dua kalau begitu!",
  ui_story_5035_50350502_86_dialog_content = "Ke Rumah Hantu, kembali beraksi!",
  ui_story_5035_50350502_87_dialog_content = "Dalam hal ini, izinkan saya untuk tinggal bersama Anda dan memberikan bimbingan.",
  ui_story_5035_50350502_88_dialog_content = "Namun, Anda harus berhati-hati, Nona Nina, karena beberapa Eclipsites nyata telah terlihat di tempat itu.",
  ui_story_5035_50350502_89_dialog_content = "Sungguh?",
  ui_story_5035_50350502_90_dialog_content = "Itu kelalaian saya... Tentu saja, Anda juga!",
  ui_story_5035_50350502_91_dialog_content = "Mengingat itu, mungkin kita harus membantu bos.",
  ui_story_5035_50350502_92_dialog_content = "Biarkan saya mengarahkan gergaji saya ke target yang sebenarnya sekarang.",
  ui_story_5035_50350502_93_dialog_content = "Hitung kami semua! Dengan pembayaran ekstra, tentu saja!",
  ui_story_5035_50350502_94_dialog_content = "Dan AC yang cukup.",
  ui_story_5035_50350502_95_dialog_content = "Kurasa di sinilah kita berpisah. Anda semua berhati-hati!",
  ui_story_5035_50350601_1_dialog_content = "<color=#e8d9bb>Buzz ... Buzz ...</color>",
  ui_story_5035_50350601_2_dialog_content = "Eh?",
  ui_story_5035_50350601_3_dialog_content = "Ada apa, Lilika?",
  ui_story_5035_50350601_4_dialog_content = "Jendela bidik saya... baru saja berkedip.",
  ui_story_5035_50350601_5_dialog_content = "Apakah itu rusak?",
  ui_story_5035_50350601_6_dialog_content = "Apa yang rusak?",
  ui_story_5035_50350601_7_dialog_content = "T-Tidak ada! Aku akan memeriksanya dengan sangat cepat!",
  ui_story_5035_50350601_8_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5035_50350601_9_dialog_content = "Mengendus...",
  ui_story_5035_50350601_10_dialog_content = "Hatsyiii!",
  ui_story_5035_50350601_11_dialog_content = "Baunya lembab di sini, seperti karpet berjamur di udara.",
  ui_story_5035_50350601_12_dialog_content = "<color=#e8d9bb>Guyuran!</color>",
  ui_story_5035_50350601_13_dialog_content = "Ugh, karpetnya sangat basah dan basah kuyup.",
  ui_story_5035_50350601_14_dialog_content = "Maaf tentang itu! Cobalah untuk tidak tergelincir.",
  ui_story_5035_50350601_15_dialog_content = "Akhir-akhir ini sangat lembab. Kami akan terus meningkatkan ventilasi.",
  ui_story_5035_50350601_16_dialog_content = "Semua kelembapan ini tidak akan berhasil. Ini akan merusak semua pernak-pernik di sini.",
  ui_story_5035_50350601_17_dialog_content = "Apakah itu sisa dari pemilik aslinya?",
  ui_story_5035_50350601_18_dialog_content = "Ya. Kami menemukan bahwa setiap penyewa sejak itu telah menjaga mereka dalam kondisi baik.",
  ui_story_5035_50350601_19_dialog_content = "Karena rasa hormat, Nona Nina menjaga ruangan itu seperti semula.",
  ui_story_5035_50350601_20_dialog_content = "Dengan cara ini, para tamu juga bisa menghargai selera pemilik sebelumnya.",
  ui_story_5035_50350601_21_dialog_content = "Ini adalah pilihan yang cukup baik untuk menggunakan tempat ini sebagai lokasi pemotretan.",
  ui_story_5035_50350601_22_dialog_content = "Gaya mantan pemilik itu... benar-benar unik.",
  ui_story_5035_50350601_23_dialog_content = "Menyingkirkan semua perabotan aneh ini...",
  ui_story_5035_50350601_24_dialog_content = "Hanya boneka-boneka ini... Mereka agak aneh untuk dilihat.",
  ui_story_5035_50350601_25_dialog_content = "Oh, debu yang bagus juga dibutuhkan. Sulit untuk membersihkan dengan benar setelah debu menumpuk ...",
  ui_story_5035_50350601_26_dialog_content = "Um... Nona Vice, tolong jangan terlalu merepotkan diri sendiri. Bagaimanapun, Anda adalah tamu kami.",
  ui_story_5035_50350601_27_dialog_content = "Tidak apa-apa. Sekarang bersih dan rapi!",
  ui_story_5035_50350601_28_dialog_content = "Ada handuk tangan di dekat pintu. Biarkan saya mendapatkannya untuk Anda.",
  ui_story_5035_50350601_29_dialog_content = "Hah?",
  ui_story_5035_50350601_30_dialog_content = "Nona Lilica, mengapa Anda berdiri di dekat pintu? Apakah ada yang bisa saya bantu?",
  ui_story_5035_50350601_31_dialog_content = "Saya, eh, menunggu fenomena supernatural terjadi!",
  ui_story_5035_50350601_32_dialog_content = "(Bisakah kamu menunggu hal semacam itu?!)",
  ui_story_5035_50350601_33_dialog_content = "Eeek!",
  ui_story_5035_50350601_34_dialog_content = "Astaga—Apakah ada yang terjadi? Apakah itu?",
  ui_story_5035_50350601_35_dialog_content = "Saya tidak memperhatikan sebelumnya, tetapi ada kartu yang tersembunyi di tengah boneka-boneka ini.",
  ui_story_5035_50350601_36_dialog_content = "Er... Apakah itu salah satu alat peraga horor Nina?",
  ui_story_5035_50350601_37_dialog_content = "Saya kira demikian. Ada semacam puisi pendek dan aneh yang tertulis di sana.",
  ui_story_5035_50350601_38_dialog_content = "Oh, uh, bisakah kau memegangnya lebih dekat? Saya ingin memotretnya di kamera.",
  ui_story_5035_50350601_39_dialog_content = "Dalam hal ini, di sini, Anda memegangnya. Anda juga bisa membacanya untuk semua orang yang menonton.",
  ui_story_5035_50350601_40_dialog_content = "A-Baiklah. Aku akan membacanya kalau begitu. Katakan saja padaku untuk berhenti jika ada yang takut!",
  ui_story_5035_50350601_41_dialog_content = "\"Satu kecil, dua kecil...\"",
  ui_story_5035_50350601_42_dialog_content = "<color=#e8d9bb>*Bunyi kotak musik penutup*</color>",
  ui_story_5035_50350601_43_dialog_content = "\"Satu boneka kecil, dua boneka kecil, tiga boneka kecil \"",
  ui_story_5035_50350601_44_dialog_content = "\"Empat boneka kecil, lima boneka kecil, enam boneka kecil \"",
  ui_story_5035_50350601_45_dialog_content = "\"Tujuh boneka kecil, delapan boneka kecil, sembilan boneka kecil \"",
  ui_story_5035_50350601_46_dialog_content = "\"Sembilan boneka kecil—tapi hanya delapan kepala kecil \"",
  ui_story_5035_50350601_47_dialog_content = "<color=#e8d9bb>Tetes... Tetes...</color>",
  ui_story_5035_50350601_48_dialog_content = "T-Rekaman ini...",
  ui_story_5035_50350601_49_dialog_content = "Itu terlalu jelek, terlepas dari itu!",
  ui_story_5035_50350601_50_dialog_content = "Haha, sepertinya gimmick Miss Nina cukup transparan.",
  ui_story_5035_50350601_51_dialog_content = "Kartu inilah yang memicu perekaman.",
  ui_story_5035_50350601_52_dialog_content = "Fiuh... Itu benar-benar mengejutkan saya.",
  ui_story_5035_50350601_53_dialog_content = "Jadi kamu juga takut, ya, Lilica?",
  ui_story_5035_50350601_54_dialog_content = "Aku akan mengatakan itu lebih kegembiraan daripada ketakutan.",
  ui_story_5035_50350601_55_dialog_content = "Jangan khawatir. Dalam semangat Swashbuckler's Way, saya dapat membantu melindungi Anda jika Anda takut.",
  ui_story_5035_50350601_56_dialog_content = "Tentu saja, saya harus mengenakan biaya untuk layanan ini.",
  ui_story_5035_50350601_57_dialog_content = "Anda telah melihat sendiri bahwa semua ini dibuat-buat dan dilakukan dengan buruk.",
  ui_story_5035_50350601_58_dialog_content = "Kualitas suaranya buruk, dan ritme suara tetesan di latar belakang tidak aktif. Belum lagi balada tidak berima dengan baik.",
  ui_story_5035_50350601_59_dialog_content = "Itu terus berulang seperti kaset rusak juga.",
  ui_story_5035_50350601_60_dialog_content = "Terima kasih atas saran Anda. Saya akan terus meningkatkan pengaturan ini dengan Nona Nina. Adapun ...",
  ui_story_5035_50350601_61_dialog_content = "<color=#e8d9bb>*penghentian kaset*</color>",
  ui_story_5035_50350601_62_dialog_content = "Aneh, kenapa rekamannya berhenti?",
  ui_story_5035_50350601_63_dialog_content = "I-Tidak mungkin karena roh rekaman mendengar apa yang kita katakan, kan?",
  ui_story_5035_50350601_64_dialog_content = "Aku akan pergi melihat di ruang kontrol. Tolong bisakah semua orang tetap di sini sebentar?",
  ui_story_5035_50350601_65_dialog_content = "(Reaksi Lilica benar-benar membuat 180 ...)",
  ui_story_5035_50350601_66_dialog_content = "Jangan takut, Lilica. Itu hanya kebetulan bahwa itu terjadi untuk berhenti.",
  ui_story_5035_50350601_67_dialog_content = "Bukannya kita bisa menghentikannya dan memulai sesuka hati.",
  ui_story_5035_50350601_68_dialog_content = "T-Itu benar. Seperti, bahkan jika kita berteriak \"Mainkan!\" saat ini, tidak ada yang akan...",
  ui_story_5035_50350601_69_dialog_content = "<color=#e8d9bb>*Bunyi kotak musik penutup*</color>",
  ui_story_5035_50350601_70_dialog_content = "\"Satu boneka kecil, dua boneka kecil, tiga boneka kecil \"",
  ui_story_5035_50350601_71_dialog_content = "\"Empat kecil, lima kecil \"",
  ui_story_5035_50350601_72_dialog_content = "A-Ahhhh!!!! Itu kembali!",
  ui_story_5035_50350601_73_dialog_content = "... Tenang! Dengarkan saja kata-katanya. Tidak ada yang berubah setelah kritik saya.",
  ui_story_5035_50350601_74_dialog_content = "Saya kira itu mungkin karena Minos berhasil memperbaiki rekamannya, kan?",
  ui_story_5035_50350601_75_dialog_content = "Itu pasti...",
  ui_story_5035_50350601_76_dialog_content = "<color=#e8d9bb>Tetes... Tetes...</color>",
  ui_story_5035_50350601_77_dialog_content = "<color=#e8d9bb>Tetes, tetes... Tetes...</color>",
  ui_story_5035_50350601_78_dialog_content = "Dengar, ritme menetes berubah.",
  ui_story_5035_50350601_79_dialog_content = "Itu juga sesuatu yang Minos bisa sesuaikan sesuka hati, sangat cepat... kan?",
  ui_story_5035_50350601_80_dialog_content = "Um... Tidak, aku tidak bisa lari!",
  ui_story_5035_50350601_81_dialog_content = "(Dia masih bertanggung jawab ketika dorongan datang untuk mendorong!)",
  ui_story_5035_50350601_82_dialog_content = "Aku akan keluar dari sini perlahan, sangat pelan, tanpa membuat kamera goyang...",
  ui_story_5035_50350601_83_dialog_content = "...",
  ui_story_5035_50350601_84_dialog_content = "Fyuh!",
  ui_story_5035_50350601_85_dialog_content = "Meskipun hati saya di tenggorokan, untungnya tidak ada yang terjadi.",
  ui_story_5035_50350601_86_dialog_content = "Sekarang setelah saya tenang, saya punya masalah lain untuk dipertimbangkan!",
  ui_story_5035_50350601_87_dialog_content = "Bagaimana kalau membuat balada itu menjadi lagu tema rekaman itu?",
  ui_story_5035_50350601_88_dialog_content = "Saya juga lupa mengambil foto di showroom tadi!",
  ui_story_5035_50350601_89_dialog_content = "Anda telah pulih cukup cepat.",
  ui_story_5035_50350601_90_dialog_content = "Tee hee!",
  ui_story_5035_50350601_91_dialog_content = "Hah?!",
  ui_story_5035_50350601_92_dialog_content = "Aduh! Siapa yang mencolek bahuku?!",
  ui_story_5035_50350601_93_dialog_content = "Oh, maaf, ini Baba Yaga.",
  ui_story_5035_50350601_94_dialog_content = "Izinkan saya meminta maaf kepada Anda atas namanya. Saya harap itu tidak menyakitkan, PlayerName?",
  ui_story_5035_50350601_95_dialog_content = "Tidak, tidak, tidak apa-apa. Aku terkejut lebih dari terluka.",
  ui_story_5035_50350601_96_dialog_content = "Kenapa kamu di sini juga, Mia?",
  ui_story_5035_50350601_97_dialog_content = "Saya datang dengan Baba Yaga. Dia tertarik dengan tempat ini.",
  ui_story_5035_50350601_98_dialog_content = "Meskipun saya melakukan yang terbaik, saya masih tidak bisa mendapatkan tiket diskon ...",
  ui_story_5035_50350601_99_dialog_content = "Sudah kubilang giliranku untuk berdebat dengan gadis tiket!",
  ui_story_5035_50350601_100_dialog_content = "Hai, PlayerName, Mia sama pemalunya seperti biasa, kan?",
  ui_story_5035_50350601_101_dialog_content = "Tebak itu takdir bahwa kami bertemu Anda di sini!",
  ui_story_5035_50350601_102_dialog_content = "Dan ekspresi itu ketika kamu ditusuk oleh cakar baja ini... SANGAT LUCU!",
  ui_story_5035_50350601_103_dialog_content = "Baba Yaga—dan Mia—di belakangmu...!",
  ui_story_5035_50350601_104_dialog_content = "Oh?! Dan apa ekspresi ini?",
  ui_story_5035_50350601_105_dialog_content = "Wajahku... Apakah benar-benar menakutkan...?",
  ui_story_5035_50350601_106_dialog_content = "Keren!!!",
  ui_story_5035_50350601_107_dialog_content = "Aaaagh!",
  ui_story_5035_50350601_108_dialog_content = "Eclipsites bukanlah hal yang perlu ditakuti!",
  ui_story_5035_50350601_109_dialog_content = "Aturan kedua dari Swashbucklers' Way: Jangan pernah lari ketika seseorang dalam kesulitan, selalu bantu ketika Anda harus!",
  ui_story_5035_50350601_110_dialog_content = "Lihat saja aku mengayunkan Coolster seperti bos!",
  ui_story_5035_50350702_1_dialog_content = "Pff... Ada apa dengan teriakan beberapa Eclipsites? Saya tidak mengerti, tidak mengerti sama sekali.",
  ui_story_5035_50350702_2_dialog_content = "Benar-benar luar biasa, Nona Penyiksaan! Bolehkah saya mengambil beberapa foto lagi dari Anda dari sudut yang berbeda?",
  ui_story_5035_50350702_3_dialog_content = "Hehehehehe... Jadilah tamuku!",
  ui_story_5035_50350702_4_dialog_content = "Tapi ingat untuk tidak mempostingnya secara publik. Mia, gadis itu, sepertinya tidak suka menjadi pusat perhatian.",
  ui_story_5035_50350702_5_dialog_content = "Kalau tidak... Aku hanya perlu menghancurkan kameramu dan benda kecil di sebelahmu ini.",
  ui_story_5035_50350702_6_dialog_content = "Uh... B-Mengerti!",
  ui_story_5035_50350702_7_dialog_content = "Hei, tidak perlu untuk itu ...",
  ui_story_5035_50350702_8_dialog_content = "Saya minta maaf. Kami tidak bermaksud mengancammu...",
  ui_story_5035_50350702_9_dialog_content = "Tidak apa-apa! Saya selalu menghormati keinginan subjek saya!",
  ui_story_5035_50350702_10_dialog_content = "Apakah semua orang baik-baik saja?",
  ui_story_5035_50350702_11_dialog_content = "Aku mendengar keributan dari bawah. Untungnya tampaknya hanya beberapa Eclipsites.",
  ui_story_5035_50350702_12_dialog_content = "Kerusakan dengan rekaman di showroom telah diperbaiki, jadi jika Anda ingin masuk kembali...",
  ui_story_5035_50350702_13_dialog_content = "Tidak! Eh, tidak, tidak perlu, hahaha...",
  ui_story_5035_50350702_14_dialog_content = "Ayo tekan ke lokasi berikutnya!",
  ui_story_5035_50350702_15_dialog_content = "Jika itu masalahnya, saya akan mengucapkan selamat tinggal kepada semua orang untuk saat ini.",
  ui_story_5035_50350702_16_dialog_content = "Yah, karena kita sudah bertemu, kurasa aku harus bertanya...",
  ui_story_5035_50350702_17_dialog_content = "Apakah Anda, eh ... Anda berdua tertarik untuk bergabung dengan regu ekspedisi kami?",
  ui_story_5035_50350702_18_dialog_content = "Tidak terima kasih. Karena... Baba Yaga lebih suka mengalami tempat ini sendirian.",
  ui_story_5035_50350702_19_dialog_content = "Nah, pastikan untuk menjaga dirimu sendiri!",
  ui_story_5035_50350702_20_dialog_content = "Tunggu. Ada sesuatu yang ingin saya katakan.",
  ui_story_5035_50350702_21_dialog_content = "PlayerName—Saya tidak melihat <color=#FFB400>dia</color> denganmu.",
  ui_story_5035_50350702_22_dialog_content = "Sepertinya aku bertemu <color=#FFB400>dia</color> sebelum kalian semua.",
  ui_story_5035_50350702_23_dialog_content = "... Dia, siapa?",
  ui_story_5035_50350702_24_dialog_content = "Ya, meskipun <color=#FFB400>dia</color> dan saya juga kesulitan bertemu.",
  ui_story_5035_50350702_25_dialog_content = "Saya sedikit kecewa tidak melihat <color=#FFB400>dia</color> di sini bersamamu—",
  ui_story_5035_50350702_26_dialog_content = "A-Siapa sebenarnya yang kamu bicarakan...?",
  ui_story_5035_50350702_27_dialog_content = "Heehee! Hanya bercanda! Mia dan aku bisa menemukan <color=#FFB400>dia</color> diri.",
  ui_story_5035_50350702_28_dialog_content = "Namun, PlayerName, Aku harus memperingatkanmu-",
  ui_story_5035_50350702_29_dialog_content = "<color=#FFB400>Hati-hati. Jangan biarkan dia menangkapmu...</color>",
  ui_story_5035_50350702_30_dialog_content = "Karena, hanya aku yang bisa <color=#FFB400>menyeretnya ke dalam perjamuan cinta.</color>",
  ui_story_5035_50350702_31_dialog_content = "Apa, uh... Apa maksudmu dengan itu?",
  ui_story_5035_50350702_32_dialog_content = "Hehehe! Ekspresi yang benar-benar hilang itu juga SANGAT LUCU!",
  ui_story_5035_50350702_33_dialog_content = "Bagaimanapun, sampai jumpa!",
  ui_story_5035_50350702_34_dialog_content = "Nah sekarang, benar-benar ...",
  ui_story_5035_50350702_35_dialog_content = "Kenapa pemilik rumah hantu ini tidak mengajakku menulis cerita horor...",
  ui_story_5035_50350702_36_dialog_content = "Dia sudah pergi...",
  ui_story_5035_50350702_37_dialog_content = "(Siapa yang dibicarakan Baba Yaga? Tidak mungkin...)",
  ui_story_5035_50350702_38_dialog_content = "(Tapi dia sepertinya tidak tertarik untuk menjelaskan lebih jauh...)",
  ui_story_5035_50350702_39_dialog_content = "(Sudahlah. Mungkin aku akan mengetahuinya pada akhirnya.)",
  ui_story_5035_50350702_40_dialog_content = "Untuk semua teman kita yang menonton ini di TV di masa depan—ini dia Caelestite terakhir yang legendaris.",
  ui_story_5035_50350702_41_dialog_content = "Dan dia, adalah gadis algojo yang mengintai kedalaman rumah.",
  ui_story_5035_50350702_42_dialog_content = "Apa yang akan menjadi hasil dari kata-kata yang tidak jelas dan ambigu seperti itu...?",
  ui_story_5035_50350702_43_dialog_content = "Jangan hanya mengada-ada, Lilica!",
  ui_story_5035_50350702_44_dialog_content = "Haha, aku punya kamu! Aku bahkan tidak merekam!",
  ui_story_5035_50350702_45_dialog_content = "Tunggu, tunggu... Kesenangan sudah berakhir, sekarang kita harus bergerak.",
  ui_story_5035_50350702_46_dialog_content = "Ada ruang bawah tanah menunggu, jadi mari kita pergi.",
  ui_story_5035_50350702_47_dialog_content = "Anda terlihat muda, tetapi Anda tampak sangat tenang dan profesional.",
  ui_story_5035_50350702_48_dialog_content = "?!",
  ui_story_5035_50350702_49_dialog_content = "Bukan apa-apa... A-Semua bajingan paling keren seperti itu!",
  ui_story_5035_50350702_50_dialog_content = "Ayo bergerak kalau begitu! Ke ruang bawah tanah kita pergi!",
  ui_story_5035_50350702_51_dialog_content = "Aku akan terus mengantarmu.",
  ui_story_5035_50350702_52_dialog_content = "Baiklah! Syuting Into the Haunted House berlanjut!",
  ui_story_5035_50350801_1_dialog_content = "<color=#e8d9bb>Berbunyi!</color>",
  ui_story_5035_50350801_2_dialog_content = "Rumah hantu ini tidak dalam situasi terbaik, jadi mari kita cari lokasi terakhir!",
  ui_story_5035_50350801_3_dialog_content = "Bagan mengatakan tempat terakhir adalah ruang bawah tanah. Tuan Butler, bisakah kami menyusahkan Anda untuk menunjukkan jalan lagi kepada kami?",
  ui_story_5035_50350801_4_dialog_content = "Omong-omong, ketika saya menandatangani kontrak dengan Jonny, area yang tersedia untuk digunakan syuting di dalam rumah ini didefinisikan dengan jelas.",
  ui_story_5035_50350801_5_dialog_content = "Dan itu tidak termasuk ruang bawah tanah. Saya akan membahas masalah biaya lagi dengan direktur besok.",
  ui_story_5035_50350801_6_dialog_content = "Ayolah, jangan merusak film dengan pembicaraan tentang uang. Kita harus pergi.",
  ui_story_5035_50350801_7_dialog_content = "Hei, Lilica, apa yang kamu lakukan? Pertahankan!",
  ui_story_5035_50350801_8_dialog_content = "Baterainya bagus, dan tutup lensanya lepas. Adapun fokus ... Oh, itu akan dilakukan.",
  ui_story_5035_50350801_9_dialog_content = "Baik! Hai, PlayerName, datang ke sini sebentar!",
  ui_story_5035_50350801_10_dialog_content = "Aku?",
  ui_story_5035_50350801_11_dialog_content = "Yeah, kau terlihat cukup tajam.",
  ui_story_5035_50350801_12_dialog_content = "Apakah Anda ingin menjadi juru kamera saya? Ini pekerjaan yang menyenangkan.",
  ui_story_5035_50350801_13_dialog_content = "Kameramen? Bukankah itu yang kamu lakukan? Untuk apa Anda membutuhkan juru kamera?",
  ui_story_5035_50350801_14_dialog_content = "Saya ingin berada di kamera nanti. Ayo, bantu aku!",
  ui_story_5035_50350801_15_dialog_content = "Tentu, tapi bagaimana...?",
  ui_story_5035_50350801_16_dialog_content = "Ambil ini. Sekarang, letakkan di bahu Anda.",
  ui_story_5035_50350801_17_dialog_content = "Ooh!",
  ui_story_5035_50350801_18_dialog_content = "Hati-hati dengan itu. Ini benar-benar mahal.",
  ui_story_5035_50350801_19_dialog_content = "Jika Anda merusaknya, siapa bilang Anda tidak perlu membayar saya beberapa triliun Nightium?",
  ui_story_5035_50350801_20_dialog_content = "Sungguh pekerjaan yang berisiko! Aku tidak melakukannya!",
  ui_story_5035_50350801_21_dialog_content = "Haha, aku hanya bercanda! Ayo, arahkan lensa ke arahku.",
  ui_story_5035_50350801_22_dialog_content = "Ya, begitu saja.",
  ui_story_5035_50350801_23_dialog_content = "Kenapa kau mengacaukan kamera lagi, Lilica?",
  ui_story_5035_50350801_24_dialog_content = "Eh, karena...",
  ui_story_5035_50350801_25_dialog_content = "Jika sesuatu yang aneh terjadi, mungkin kita bisa menangkap sesuatu di kamera.",
  ui_story_5035_50350801_26_dialog_content = "Maksud kamu apa? Apakah sesuatu akan terjadi?",
  ui_story_5035_50350801_27_dialog_content = "Yah, tidak pasti! Hanya saja...",
  ui_story_5035_50350801_28_dialog_content = "Nah, Minos baru saja mengatakan sesuatu tentang ruang bawah tanah yang tidak berada dalam ruang lingkup bisnis rumah hantu?",
  ui_story_5035_50350801_29_dialog_content = "Ya, itulah yang saya katakan.",
  ui_story_5035_50350801_30_dialog_content = "Jadi tidak melanggar aturan rumah hantu bagi saya untuk menembak di ruang bawah tanah!",
  ui_story_5035_50350801_31_dialog_content = "Memang. Anda dapat terus merekam.",
  ui_story_5035_50350801_32_dialog_content = "Itu saja yang saya inginkan! Mengingat kami membawa kamera, tentu saja saya ingin memotret sebanyak yang saya bisa.",
  ui_story_5035_50350801_33_dialog_content = "Baiklah, ayo pergi, semuanya!",
  ui_story_5035_50350801_34_dialog_content = "Baik. Tapi pertama-tama, saya harus memberi tahu Anda, jika saya akan terlihat, Anda harus memberikan hak siar kepada mereka.",
  ui_story_5035_50350801_35_dialog_content = "Bukankah seseorang mengatakan sesuatu sebelumnya tentang tidak membawa uang berbicara ke dalam film kita?",
  ui_story_5035_50350801_36_dialog_content = "Dengan cara ini ke ruang bawah tanah. Jalannya bisa sedikit berbahaya, jadi harap berhati-hati.",
  ui_story_5035_50350801_37_dialog_content = "Apakah Anda tahu cara menggunakan kamera, PlayerName?",
  ui_story_5035_50350801_38_dialog_content = "Um, aku bisa mengambilnya dan mengarahkannya ke berbagai hal.",
  ui_story_5035_50350801_39_dialog_content = "Anda tahu ... jika Anda terlalu dekat dengan lensa, wajah Anda akan terlihat besar di depan kamera.",
  ui_story_5035_50350801_40_dialog_content = "Eh? K-Kamu mundur sedikit kalau begitu!",
  ui_story_5035_50350801_41_dialog_content = "Ayo, mari kita mengejar. Ingatlah untuk terus menyorot ke arahku!",
  ui_story_5035_50350801_42_dialog_content = "<color=#e8d9bb>Ta… ta… ta…</color>",
  ui_story_5035_50350801_43_dialog_content = "Jadi, Minos, mengapa ruang bawah tanah tidak termasuk dalam ruang lingkup perjanjian?",
  ui_story_5035_50350801_44_dialog_content = "Ruang bawah tanah rumah berhantu terdengar seperti kail yang bagus. Harga tiketnya bahkan bisa dinaikkan, pasti.",
  ui_story_5035_50350801_45_dialog_content = "Saya harus mulai dari ketika Nona Nina membeli mansion.",
  ui_story_5035_50350801_46_dialog_content = "Mantan pemilik sedang terburu-buru untuk menjual dan menawarkan harga rendah.",
  ui_story_5035_50350801_47_dialog_content = "Terlebih lagi, dia bahkan tidak memasukkan ruang bawah tanah saat menghitung luas total!",
  ui_story_5035_50350801_48_dialog_content = "Bisa dibilang ruang bawah tanah itu dilempar secara gratis.",
  ui_story_5035_50350801_49_dialog_content = "Oh, penjual yang sangat ramah!",
  ui_story_5035_50350801_50_dialog_content = "Saya hanya menemukannya ketika saya memeriksa tempat untuk Nona Nina, dan saya segera pergi untuk bertanya kepada pemilik sebelumnya.",
  ui_story_5035_50350801_51_dialog_content = "Dia mengatakan kepada saya bahwa itu telah lama ditinggalkan, berantakan total, dan berbau mengerikan.",
  ui_story_5035_50350801_52_dialog_content = "Dia tidak merasa nyaman memasukkan area seperti itu dalam harga yang diminta, jadi dia hanya menghilangkannya dari perhitungan.",
  ui_story_5035_50350801_53_dialog_content = "Dia juga memperingatkan saya agar tidak menjelajah ke ruang bawah tanah, karena tidak ada gunanya mencoba membersihkan kekacauan itu.",
  ui_story_5035_50350801_54_dialog_content = "Lebih baik menumpuk setumpuk tanah dan batu di atasnya dan berpura-pura tidak ada.",
  ui_story_5035_50350801_55_dialog_content = "Jadi Anda hanya mengikuti sarannya?",
  ui_story_5035_50350801_56_dialog_content = "Lebih atau kurang. Kami tidak punya banyak waktu untuk renovasi, dan saya pasti tidak bisa meluangkan waktu untuk membersihkan ruang bawah tanah.",
  ui_story_5035_50350801_57_dialog_content = "Yang mengatakan, saya tidak pergi sejauh untuk menguburnya.",
  ui_story_5035_50350801_58_dialog_content = "Saya mengubah pintu masuk ke ruang bawah tanah menjadi pintu tersembunyi. Ketika musim sepi rumah tiba, saya mungkin akan menemukan waktu untuk merenovasinya.",
  ui_story_5035_50350801_59_dialog_content = "Betapa rajinnya kamu, Minos...",
  ui_story_5035_50350801_60_dialog_content = "Kita sudah sampai.",
  ui_story_5035_50350801_61_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_5035_50350801_62_dialog_content = "Wow! Tersembunyi di bawah karpet!",
  ui_story_5035_50350801_63_dialog_content = "Tetap dekat. Di dalam sana agak gelap.",
  ui_story_5035_50350801_64_dialog_content = "Hati-Hati, PlayerName, jangan menabrak kamera.",
  ui_story_5035_50350801_65_dialog_content = "Aku tahu, aku tahu.",
  ui_story_5035_50350801_66_dialog_content = "K-Kamu menyebut ini \"sedikit\" gelap?! Aku bahkan tidak bisa melihat tanganku di depan wajahku!",
  ui_story_5035_50350801_67_dialog_content = "Kegelapan di sekeliling, debu di atas 'n *batuk* di tanah.",
  ui_story_5035_50350801_68_dialog_content = "Mino? Kamu ada di mana? aku rasa aku telah kehilanganmu...",
  ui_story_5035_50350801_69_dialog_content = "Aku menyalakan lampu.",
  ui_story_5035_50350801_70_dialog_content = "Wah, cerah sekali.",
  ui_story_5035_50350801_71_dialog_content = "Aku hanya berada di ruang bawah tanah sekali ketika aku datang untuk memeriksa rumah ini. Saya tidak pernah melihat sekeliling dengan benar.",
  ui_story_5035_50350801_72_dialog_content = "Saya tidak yakin apa yang bisa muncul di sini. Saya akan menyarankan semua orang untuk waspada.",
  ui_story_5035_50350801_73_dialog_content = "Itu tidak terlihat seburuk yang saya kira.",
  ui_story_5035_50350801_74_dialog_content = "Meskipun berantakan dengan semua sampah yang berserakan, sebenarnya tidak kotor. Dan untungnya, tidak ada bau seperti yang dikatakan pemilik sebelumnya.",
  ui_story_5035_50350801_75_dialog_content = "Anda bahkan dapat melihat bahwa seseorang mencoba untuk mengurusnya.",
  ui_story_5035_50350801_76_dialog_content = "Ada patung yang terbuat dari lilin yang meleleh di sana.",
  ui_story_5035_50350801_77_dialog_content = "Ini cukup kasar. Hal semacam ini tidak benar-benar menyenangkan mata.",
  ui_story_5035_50350801_78_dialog_content = "Bukankah pola di dalam debu ini terlihat seperti jejak kaki?",
  ui_story_5035_50350801_79_dialog_content = "Oh ya! Mereka melakukannya!",
  ui_story_5035_50350801_80_dialog_content = "Ada juga sidik jari di dinding, jauh lebih kecil dari milikku.",
  ui_story_5035_50350801_81_dialog_content = "Apakah mereka dibuat oleh anak-anak?",
  ui_story_5035_50350801_82_dialog_content = "Ada takik di pilar juga. Saya tahu mereka! Aku punya mereka di rumah saya juga.",
  ui_story_5035_50350801_83_dialog_content = "Saya tahu! Itu bekas gigi!",
  ui_story_5035_50350801_84_dialog_content = "... Bekas gigi, ass. Apa kamu, seekor anjing?",
  ui_story_5035_50350801_85_dialog_content = "Mereka penanda ketinggian. Takik baru dibuat sesekali untuk melihat seberapa besar seseorang tumbuh.",
  ui_story_5035_50350801_86_dialog_content = "Oh, begitu…",
  ui_story_5035_50350801_87_dialog_content = "Tidak tahu siapa seseorang yang begitu kecil. Lihat. Kedudukan tertinggi bahkan lebih pendek dari Sadie.",
  ui_story_5035_50350801_88_dialog_content = "Kamu...",
  ui_story_5035_50350801_89_dialog_content = "Itu benar. Takik ini, seperti sidik jari dan jejak kaki, semuanya dibuat oleh anak-anak.",
  ui_story_5035_50350801_90_dialog_content = "Mereka tidak semua sama, meskipun. Sepertinya ada lebih dari satu anak.",
  ui_story_5035_50350801_91_dialog_content = "Bagaimana mereka bisa tinggal di tempat seperti ini...?",
  ui_story_5035_50350801_92_dialog_content = "Hei, lihat ini.",
  ui_story_5035_50350801_93_dialog_content = "Ada tulisan di semua kertas bekas ini di lantai!",
  ui_story_5035_50350801_94_dialog_content = "Oh? Apa yang dikatakan?",
  ui_story_5035_50350801_95_dialog_content = "Sulit untuk melihat. Biarkan aku melihat lebih dekat...",
  ui_story_5035_50350801_96_dialog_content = "\"Ini adalah satu-satunya hal yang perlu kamu ingat.\"",
  ui_story_5035_50350801_97_dialog_content = "\"Anak-anak nakal akan <color=#FFB400>dihukum</color> oleh Nyonya.\"",
  ui_story_5035_50350801_98_dialog_content = "\"Pintu ruang bawah tanah akan dibuka, dan dia akan dibawa ke sana.\"",
  ui_story_5035_50350801_99_dialog_content = "\"Oh, dan bukan hanya dia, tapi juga teman kecil terdekatnya.\"",
  ui_story_5035_50350801_100_dialog_content = "\"Hukuman untuk kesalahan harus diingat.\"",
  ui_story_5035_50350801_101_dialog_content = "\"Jangan khawatir, teman. Tidak akan terjadi apa-apa padamu.\"",
  ui_story_5035_50350801_102_dialog_content = "\"Selama kamu baik-baik saja, pergilah ke ujung terjauh ruangan, dan berdiri menghadap ke sudut.\"",
  ui_story_5035_50350801_103_dialog_content = "\"Dengarkan baik-baik. Tidak peduli apa yang kamu dengar, kamu tidak boleh berbalik.\"",
  ui_story_5035_50350801_104_dialog_content = "\"Karena Nyonya tidak suka diamati saat dia mengaturnya <color=#FFB400>hukuman</color>.\"",
  ui_story_5035_50350801_105_dialog_content = "... Hmm, itu berakhir di sana. Betapa anehnya.",
  ui_story_5035_50350801_106_dialog_content = "Bukankah itu terdengar seperti semacam peringatan? Tidak ada cara untuk mengetahui seberapa benar semua itu.",
  ui_story_5035_50350801_107_dialog_content = "Nyonya... Mungkinkah itu Lady Astor yang disebutkan Minos sebelumnya?",
  ui_story_5035_50350801_108_dialog_content = "Saya tidak yakin. Lady Astor benar-benar lebih dari seorang legenda.",
  ui_story_5035_50350801_109_dialog_content = "Mungkinkah dia pernah menghukum anak-anak di ruang bawah tanah ini?",
  ui_story_5035_50350801_110_dialog_content = "Satu anak dihukum, dengan yang lain berdiri di sudut dan mendengarkan ...",
  ui_story_5035_50350801_111_dialog_content = "Itu benar-benar bengkok. Saya berharap itu ... tidak pernah benar-benar terjadi.",
  ui_story_5035_50350801_112_dialog_content = "Dilihat dari tulisan tangan, catatan ini ditulis oleh anak-anak.",
  ui_story_5035_50350801_113_dialog_content = "Mungkinkah mereka hanya mengarang cerita?",
  ui_story_5035_50350801_114_dialog_content = "Aku takut tidak. Lihatlah beberapa potongan kertas lainnya.",
  ui_story_5035_50350801_115_dialog_content = "Ada tulisan di semuanya. Dan mereka semua mengatakan hal yang serupa.",
  ui_story_5035_50350801_116_dialog_content = "\"Ini adalah satu-satunya hal yang perlu kamu ingat.\"",
  ui_story_5035_50350801_117_dialog_content = "\"Anak-anak nakal akan <color=#FFB400>dihukum</color> oleh Nyonya...\"",
  ui_story_5035_50350801_118_dialog_content = "Apakah Anda akan menulis cerita yang dibuat-buat ini berkali-kali?",
  ui_story_5035_50350801_119_dialog_content = "O-Tentu saja tidak.",
  ui_story_5035_50350801_120_dialog_content = "Sudahlah berkali-kali, aku akan lelah setelah menulisnya sekali. Aku bahkan tidak ingat berapa umurku terakhir kali aku benar-benar menulis sesuatu... Mungkin sepuluh?",
  ui_story_5035_50350801_121_dialog_content = "Menyalin sesuatu berkali-kali itu monoton. Siapa yang mau melakukan hal seperti itu?",
  ui_story_5035_50350801_122_dialog_content = "Kecuali…",
  ui_story_5035_50350801_123_dialog_content = "Kecuali terpaksa. Aku mengerti sekarang, ini adalah hukuman.",
  ui_story_5035_50350801_124_dialog_content = "Menghukum seorang anak dengan membuat mereka meniru semua itu? Bukankah itu...",
  ui_story_5035_50350801_125_dialog_content = "Tuan Butler, seberapa banyak yang Anda ketahui tentang pemilik sebelumnya?",
  ui_story_5035_50350801_126_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5035_50350801_127_dialog_content = "Tuan Butler?",
  ui_story_5035_50350801_128_dialog_content = "Saya menemukan sesuatu yang lain. Lihatlah ini.",
  ui_story_5035_50350801_129_dialog_content = "Oh? Sebuah buku catatan?! Apakah ada hal yang sama yang tertulis di dalamnya seperti potongan-potongan kertas itu?",
  ui_story_5035_50350801_130_dialog_content = "Tidak. Notebook ini jelas cukup baru dan baru saja ditinggalkan di sini.",
  ui_story_5035_50350801_131_dialog_content = "Di bagian depan tertulis \"Crew Work Record\", dan ternyata produsernya yang menulisnya.",
  ui_story_5035_50350801_132_dialog_content = "Produser? Bukankah itu kamu?",
  ui_story_5035_50350801_133_dialog_content = "Bagaimana saya bisa menulisnya? Mungkin kru film yang berbeda ada di sini di masa lalu.",
  ui_story_5035_50350801_134_dialog_content = "Mungkin. Apa yang tertulis di dalamnya, sih?",
  ui_story_5035_50350801_135_dialog_content = "\"Lokasi: Kamar tidur.\"",
  ui_story_5035_50350801_136_dialog_content = "\"Tempat ini adalah tempat pembuangan sampah. Jendela dan alas tiang semuanya berangin, dan sangat dingin hingga aku menggigil.\"",
  ui_story_5035_50350801_137_dialog_content = "\"Saya benar-benar menantikan untuk menonton TV sambil menunggu sutradara, tetapi potongan yang tidak berguna itu tidak dapat menangkap sinyal sama sekali.\"",
  ui_story_5035_50350801_138_dialog_content = "\"Dan bagian terburuknya adalah sutradaranya bahkan tidak muncul, tapi Eclipsites muncul.\"",
  ui_story_5035_50350801_139_dialog_content = "\"Setengah dari alat peraga kami rusak, dan tiga anggota kru terluka. Saya sudah memberi tahu direktur bahwa tidak mungkin kami bisa menembak di sini.\"",
  ui_story_5035_50350801_140_dialog_content = "Sepertinya mereka juga ada di kamar tidur.",
  ui_story_5035_50350801_141_dialog_content = "Saya kira bertemu Eclipsites di tempat ini cukup standar... Tidak heran itu di pasar dengan harga yang rendah.",
  ui_story_5035_50350801_142_dialog_content = "Entri berikutnya juga menyebutkan tempat yang familiar.",
  ui_story_5035_50350801_143_dialog_content = "\"Lokasi: Showroom.\"",
  ui_story_5035_50350801_144_dialog_content = "\"Aku sudah cukup. Jika sutradara bersikeras untuk melanjutkan syuting di sini, aku akan berhenti dan pulang.\"",
  ui_story_5035_50350801_145_dialog_content = "\"Balada menyeramkan itu tidak akan berhenti. Dan suara tetesan air terkutuk yang sepertinya mengikuti ritmenya.\"",
  ui_story_5035_50350801_146_dialog_content = "\"Apakah ini bagian dari estetika khusus pemiliknya? Jika demikian, mereka pantas mendapat tamparan di kepala mereka.\"",
  ui_story_5035_50350801_147_dialog_content = "\"Aku di sini untuk syuting film horor, bukan untuk bertemu hantu.\"",
  ui_story_5035_50350801_148_dialog_content = "Kami memiliki hal yang sama persis terjadi di showroom! Balada dan suara menetes, dia mendengar semuanya!",
  ui_story_5035_50350801_149_dialog_content = "Apakah Anda bersumpah Anda tidak menulis ini, Minos?",
  ui_story_5035_50350801_150_dialog_content = "Bukankah lebih menyeramkan jika saya menulisnya?",
  ui_story_5035_50350801_151_dialog_content = "M-Mungkin...",
  ui_story_5035_50350801_152_dialog_content = "Tapi lalu apa? Siapa yang memiliki buku catatan itu juga datang ke ruang bawah tanah?",
  ui_story_5035_50350801_153_dialog_content = "Oh maaf, pertanyaan bodoh. Kami menemukan buku catatan di sini.",
  ui_story_5035_50350801_154_dialog_content = "Ya. Berikut entri berikutnya.",
  ui_story_5035_50350801_155_dialog_content = "\"Lokasi: Ruang Bawah Tanah.\"",
  ui_story_5035_50350801_156_dialog_content = "...",
  ui_story_5035_50350801_157_dialog_content = "Apa? Lanjutkan...",
  ui_story_5035_50350801_158_dialog_content = "Lihat sendiri.",
  ui_story_5035_50350801_159_dialog_content = "Hah? Apa di bumi...",
  ui_story_5035_50350801_160_dialog_content = "...",
  ui_story_5035_50350801_161_dialog_content = "\"Dia disini.\"",
  ui_story_5035_50350801_162_dialog_content = "Itu saja?",
  ui_story_5035_50350801_163_dialog_content = "Siapa disini?",
  ui_story_5035_50350801_164_dialog_content = "Apakah Anda pikir itu bisa menjadi \"Nyonya\" yang disebutkan dalam potongan kertas ...?",
  ui_story_5035_50350801_165_dialog_content = "Tidak ada informasi lain. Ini adalah segalanya di ruang bawah tanah.",
  ui_story_5035_50350801_166_dialog_content = "Saya khawatir kita harus membayangkan apa yang bisa terjadi di sini di masa lalu.",
  ui_story_5035_50350801_167_dialog_content = "Apakah ada hal lain yang ingin Anda lihat?",
  ui_story_5035_50350801_168_dialog_content = "Sejujurnya, aku ingin pergi dari sini...",
  ui_story_5035_50350801_169_dialog_content = "M-Aku juga!",
  ui_story_5035_50350801_170_dialog_content = "Tunggu sebentar! Tahan dulu! Mengapa semua orang dalam suasana hati yang buruk?",
  ui_story_5035_50350801_171_dialog_content = "Kami hampir membungkus Rumah Hantu! Tentunya itu harus menjadi alasan untuk perayaan!",
  ui_story_5035_50350801_172_dialog_content = "Apakah kamu tidak takut, setelah melihat semua itu...?",
  ui_story_5035_50350801_173_dialog_content = "Ini sedikit menakutkan, tetapi semakin banyak alasan saya ingin tetap positif!",
  ui_story_5035_50350801_174_dialog_content = "Kalau tidak, kita akan menakuti diri kita sendiri sampai mati sebelum monster muncul!",
  ui_story_5035_50350801_175_dialog_content = "Nah, untuk mencairkan suasana dan memperingati ekspedisi ini, yuk foto bareng!",
  ui_story_5035_50350801_176_dialog_content = "Apa, di sini? Mungkin kita harus pergi dulu, sebelum...",
  ui_story_5035_50350801_177_dialog_content = "Tentu saja di sini! Itu tidak akan diingat sebaliknya.",
  ui_story_5035_50350801_178_dialog_content = "Tidak buruk. Beri saya salinannya, ya? Saya dapat menggunakannya untuk mempromosikan film baru.",
  ui_story_5035_50350801_179_dialog_content = "Saya ingin salinan juga, silakan. Ini akan membantu saya ketika saya bernegosiasi dengan pemilik.",
  ui_story_5035_50350801_180_dialog_content = "Melihat? Semua orang ada di kapal. Ayo!",
  ui_story_5035_50350801_181_dialog_content = "Baik. Ingin aku mengambilnya untukmu?",
  ui_story_5035_50350801_182_dialog_content = "Tidak tidak tidak! Foto grup membutuhkan semua orang dalam bidikan.",
  ui_story_5035_50350801_183_dialog_content = "Bagaimana dengan ini — semua orang datang kepadaku, selain PlayerName.",
  ui_story_5035_50350801_184_dialog_content = "Peras di sana ... Berdiri sedikit lebih dekat.",
  ui_story_5035_50350801_185_dialog_content = "Apakah ini baik?",
  ui_story_5035_50350801_186_dialog_content = "Ya! Besar! Sekarang, PlayerName, letakkan kamera di rak itu dan arahkan ke kami.",
  ui_story_5035_50350801_187_dialog_content = "Sekarang tekan tombol rana dan lari ke arah kami. Mengerti?",
  ui_story_5035_50350801_188_dialog_content = "Ah, saya pikir saya melihat apa yang Anda maksudkan.",
  ui_story_5035_50350801_189_dialog_content = "Coba saya lihat ... Di sini harus dilakukan, menunjuk pada kalian ...",
  ui_story_5035_50350801_190_dialog_content = "Ini tombol rana, kan?",
  ui_story_5035_50350801_191_dialog_content = "Ya! Beri kami hitungan mundur dulu, agar kami bisa bersiap-siap.",
  ui_story_5035_50350801_192_dialog_content = "Baiklah, aku mengerti. Semuanya, lihat ke sini!",
  ui_story_5035_50350801_193_dialog_content = "Menghitung mundur! 3... 2... 1...",
  ui_story_5035_50350801_194_dialog_content = "<color=#e8d9bb>Pertengkaran!</color>",
  ui_story_5035_50350801_195_dialog_content = "Aduh!",
  ui_story_5035_50350801_196_dialog_content = "A-Apa yang terjadi? Listrik padam?",
  ui_story_5035_50350801_197_dialog_content = "Aduh, seseorang menginjakku.",
  ui_story_5035_50350801_198_dialog_content = "Oh maaf! Eh, tunggu—aku tidak menginjak siapa pun!",
  ui_story_5035_50350801_199_dialog_content = "Ah!",
  ui_story_5035_50350801_200_dialog_content = "Apakah sesuatu menetes pada kalian?",
  ui_story_5035_50350801_201_dialog_content = "Beberapa jenis cairan beku...",
  ui_story_5035_50350801_202_dialog_content = "Ya, saya juga baru merasakannya...",
  ui_story_5035_50350801_203_dialog_content = "Kamu juga? Oh bagus!!",
  ui_story_5035_50350801_204_dialog_content = "Besar?!",
  ui_story_5035_50350801_205_dialog_content = "Itu berarti sesuatu pasti muncul kali ini!",
  ui_story_5035_50350801_206_dialog_content = "Apa, dan itu hal yang bagus?!",
  ui_story_5035_50350801_207_dialog_content = "PlayerName! Cepat, nyalakan night vision kamera!",
  ui_story_5035_50350801_208_dialog_content = "Wah, bisa gitu? Bagaimana saya harus menyalakannya?",
  ui_story_5035_50350801_209_dialog_content = "Harus ada tombol persegi tepat di bawah tombol rana. Tekan saja itu!",
  ui_story_5035_50350801_210_dialog_content = "Di bawah tombol rana...",
  ui_story_5035_50350801_211_dialog_content = "Ahhhh!",
  ui_story_5035_50350801_212_dialog_content = "Dengan cepat! Saya pikir saya melihat sesuatu di sana! DI SANA!",
  ui_story_5035_50350801_213_dialog_content = "Berhasil!",
  ui_story_5035_50350801_214_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_5035_50350801_215_dialog_content = "Oh! Saya dapat melihat...",
  ui_story_5035_50350801_216_dialog_content = "Apa itu? Ada apa disana?!",
  ui_story_5035_50350801_217_dialog_content = "I-Itu Minos, kurasa.",
  ui_story_5035_50350801_218_dialog_content = "Mino? Bukankah dia tepat di sebelah kita?",
  ui_story_5035_50350801_219_dialog_content = "Um, dia...",
  ui_story_5035_50350801_220_dialog_content = "Dia berdiri sendiri, menghadap ke sudut...",
  ui_story_5035_50350801_221_dialog_content = "Tunggu... F-Menghadap ke sudut?",
  ui_story_5035_50350801_222_dialog_content = "Apakah kalian ingat? Apa yang baru saja kita temukan tertulis di kertas...",
  ui_story_5035_50350801_223_dialog_content = "Hah?",
  ui_story_5035_50350801_224_dialog_content = "\"Anak-anak nakal akan dihukum oleh Nyonya.\"",
  ui_story_5035_50350801_225_dialog_content = "Yang satu dihukum, sementara yang lain... berdiri di sudut dan mendengarkan...",
  ui_story_5035_50350801_226_dialog_content = "Mana mungkin...",
  ui_story_5035_50350801_227_dialog_content = "Tapi bukankah Minos sekarang terlihat seperti...",
  ui_story_5035_50350801_228_dialog_content = "Tunggu! Kalau begitu cara kerjanya...",
  ui_story_5035_50350801_229_dialog_content = "Dan Minos adalah anak yang mendengarkan, lalu kita...",
  ui_story_5035_50350801_230_dialog_content = "<color=#e8d9bb>Menetes</color>",
  ui_story_5035_50350801_231_dialog_content = "Suara menetes... Ini tidak bagus.",
  ui_story_5035_50350801_232_dialog_content = "Oh tidak!!!",
  ui_story_5035_50350801_233_dialog_content = "Tetap tenang. aku akan mencari jalan keluar...",
  ui_story_5035_50350801_234_dialog_content = "<color=#e8d9bb>Seseorang harus menjadi <size=50>dihukum</size>.</color>",
  ui_story_5035_50350801_235_dialog_content = "?!",
  ui_story_5035_50350801_236_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5035_50350801_237_dialog_content = "Ahhh!",
  ui_story_5035_50350801_238_dialog_content = "<size=45>Ahhh!</size>",
  ui_story_5035_50350801_239_dialog_content = "<size=55>Aduh!</size>",
  ui_story_5035_50350801_240_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_5035_50350801_241_dialog_content = "<color=#e8d9bb>Ta… ta… ta…</color>",
  ui_story_5035_50350801_242_dialog_content = "<color=#e8d9bb>*langkah kaki mendekat*</color>",
  ui_story_5035_50350801_243_dialog_content = "Kenapa kameranya ada di tanah? Apa yang kamu lakukan?",
  ui_story_5035_50350801_244_dialog_content = "Di Sini, PlayerName.",
  ui_story_5035_50350801_245_dialog_content = "Oh... Uh... Bukankah kau baru saja...",
  ui_story_5035_50350801_246_dialog_content = "Sebuah sekering meledak. Aku baru saja memperbaikinya.",
  ui_story_5035_50350801_247_dialog_content = "Oh, apakah itu?",
  ui_story_5035_50350801_248_dialog_content = "Jadi Anda berdiri di sudut ...",
  ui_story_5035_50350801_249_dialog_content = "Karena di situlah sumbunya.",
  ui_story_5035_50350801_250_dialog_content = "...",
  ui_story_5035_50350801_251_dialog_content = "Anda tahu, tidak mudah memperbaiki sekring yang putus dalam gelap. Aku bisa menyalakan lampu kembali lebih cepat jika kamu tidak terlalu berisik.",
  ui_story_5035_50350801_252_dialog_content = "Jadi, apa yang baru saja terjadi? Apakah Anda melihat sesuatu?",
  ui_story_5035_50350801_253_dialog_content = "Uh, kami melihat... eh...",
  ui_story_5035_50350801_254_dialog_content = "Oh, itu gelap gulita. Bagaimana kami bisa melihat sesuatu?",
  ui_story_5035_50350801_255_dialog_content = "Fiuh! Syukurlah itu hanya kesalahpahaman lain.",
  ui_story_5035_50350801_256_dialog_content = "Awww, itu menyebalkan! Lagi?!",
  ui_story_5035_50350801_257_dialog_content = "Mengapa Anda begitu bersemangat tentang ini ?!",
  ui_story_5035_50350801_258_dialog_content = "Oh, apa pun. Lupakan. Kurasa aku tidak mendapatkan sesuatu yang lebih menarik untuk Into the Haunted House hari ini.",
  ui_story_5035_50350801_259_dialog_content = "*Ya-wn* aku lelah. Mari kita mengambil foto grup lagi dan kemudian kembali untuk beristirahat.",
  ui_story_5035_50350801_260_dialog_content = "Selalu dengan foto grup, ya ...",
  ui_story_5035_50350801_261_dialog_content = "Tentu saja! Gambar sebagai suvenir sangat penting!",
  ui_story_5035_50350801_262_dialog_content = "Saat Anda melakukannya, periksa apakah kamera tidak rusak. Jika sudah, PlayerName, Anda mungkin harus ... hmph.",
  ui_story_5035_50350801_263_dialog_content = "Apa?!",
  ui_story_5035_50350801_264_dialog_content = "F-Baik. Semuanya, berkumpullah!",
  ui_story_5035_50350801_265_dialog_content = "Baiklah, baiklah.",
  ui_story_5035_50350801_266_dialog_content = "Ayo kamera, kamera bagus... Kamu tidak rapuh kan?",
  ui_story_5035_50350801_267_dialog_content = "Jangan lupa untuk berlari.",
  ui_story_5035_50350801_268_dialog_content = "Kamu bisa melakukannya! Ayo ayo!",
  ui_story_5035_50350801_269_dialog_content = "3... 2... 1...",
  ui_story_5035_50350801_270_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_5035_50350901_1_dialog_content = "Ke Rumah Hantu—dibungkus!",
  ui_story_5035_50350901_2_dialog_content = "Selamat semuanya! Minos, di mana saya bisa mengembangkan gambar-gambar ini?",
  ui_story_5035_50350901_3_dialog_content = "Saya ingin memberi semua orang foto grup kami!",
  ui_story_5035_50350901_4_dialog_content = "Ikut denganku. Kantor saya kebetulan memiliki kamar gelap yang berfungsi.",
  ui_story_5035_50350901_5_dialog_content = "Kalian yang lain ikut juga. Aku akan membereskan kamarmu untuk malam ini.",
  ui_story_5035_50350901_6_dialog_content = "Juga... banyak yang terjadi malam ini. Kita mungkin harus merenungkan detailnya lagi setelah kita tenang.",
  ui_story_5035_50350901_7_dialog_content = "Kamu benar. Saya merasa seperti saya belum banyak menggunakan otak saya hari ini.",
  ui_story_5035_50350901_8_dialog_content = "Segala sesuatu yang terjadi membutuhkan refleksi panjang dan dalam, tetapi sudah terlambat untuk itu malam ini, mari kita pergi dan tidur.",
  ui_story_5035_50350901_9_dialog_content = "Oh, aku baru ingat—di ruang bawah tanah tadi, ketika lampu padam, apakah ada yang mengatakan sesuatu yang aneh?",
  ui_story_5035_50350901_10_dialog_content = "Aneh?",
  ui_story_5035_50350901_11_dialog_content = "Sesuatu di sepanjang baris \"Seseorang perlu dihukum\"? Aku tidak mengenali suara itu.",
  ui_story_5035_50350901_12_dialog_content = "Hah? Siapa yang akan mengatakan sesuatu seperti itu?",
  ui_story_5035_50350901_13_dialog_content = "Aku tidak mendengar apa-apa.",
  ui_story_5035_50350901_14_dialog_content = "Apa? Apakah tidak ada orang lain yang mendengarnya?",
  ui_story_5035_50350901_15_dialog_content = "Tidak mungkin ada yang lain...",
  ui_story_5035_50350901_16_dialog_content = "Ahhh! Berhenti membuatku takut!!",
  ui_story_5035_50350901_17_dialog_content = "Ayo pergi dari sini!",
  ui_story_5035_50350901_18_dialog_content = "Wow! Minos, kamarmu sangat rapi!",
  ui_story_5035_50350901_19_dialog_content = "Perhatikan apa yang Anda sentuh. Ada banyak peralatan kru di sini.",
  ui_story_5035_50350901_20_dialog_content = "Baiklah, mengerti. Jadi, di mana kamar gelapnya?",
  ui_story_5035_50350901_21_dialog_content = "Ah, ya... Lewat pintu kecil itu. Anda tahu cara menggunakan bahan kimia?",
  ui_story_5035_50350901_22_dialog_content = "Tentu saja! Saya seorang foto profesional—",
  ui_story_5035_50350901_23_dialog_content = "—penggemar elektronik...",
  ui_story_5035_50350901_24_dialog_content = "Apakah Anda bahkan tahu apa yang Anda katakan?",
  ui_story_5035_50350901_25_dialog_content = "Ha ha. Butuh sedikit waktu untuk mengembangkan foto, kalian tunggu aku.",
  ui_story_5035_50350901_26_dialog_content = "Fiuh, aku lelah. Aku butuh istirahat!",
  ui_story_5035_50350901_27_dialog_content = "Kunjungan ke Rumah Hantu Andersen ini benar-benar sepadan! Perjalanan yang sangat mendebarkan!",
  ui_story_5035_50350901_28_dialog_content = "Anda masih berpikir bahwa setelah betapa takutnya Anda ...",
  ui_story_5035_50350901_29_dialog_content = "Apa? Saya dapat menikmati dan takut akan hal-hal supernatural pada saat yang bersamaan.",
  ui_story_5035_50350901_30_dialog_content = "Sebaliknya, KARENA ketakutan akan hal-hal gaib, saya menyukai kemisteriusan mereka!",
  ui_story_5035_50350901_31_dialog_content = "Begitulah, ya?",
  ui_story_5035_50350901_32_dialog_content = "Tentu saja! Nona Nina membeli rumah ini untuk menangkap hati kami para pemburu hantu.",
  ui_story_5035_50350901_33_dialog_content = "Kita harus berterima kasih padanya karena telah mendirikan Rumah Hantu Andersen dengan sangat hati-hati. Itu pasti akan menjadi hit besar!",
  ui_story_5035_50350901_34_dialog_content = "Apakah kalian berpikir bahwa apa yang terjadi malam ini hanyalah bagian dari pengaturan rumah hantu?",
  ui_story_5035_50350901_35_dialog_content = "Hah?",
  ui_story_5035_50350901_36_dialog_content = "Nona Nina tentu saja membuat beberapa persiapan.",
  ui_story_5035_50350901_37_dialog_content = "Tapi, sejauh yang kami alami malam ini, banyak hal yang bukan bagian dari persiapan itu.",
  ui_story_5035_50350901_38_dialog_content = "Maksudmu, seperti pemadaman listrik di ruang bawah tanah?",
  ui_story_5035_50350901_39_dialog_content = "Ya. Sudah kubilang, ruang bawah tanah tidak pernah menjadi bagian dari rumah hantu.",
  ui_story_5035_50350901_40_dialog_content = "Mungkin itu hanya kecelakaan?",
  ui_story_5035_50350901_41_dialog_content = "Kecelakaan adalah bagian integral dari setiap peristiwa supernatural!",
  ui_story_5035_50350901_42_dialog_content = "Itu juga yang saya pikirkan.",
  ui_story_5035_50350901_43_dialog_content = "Menghadapi peristiwa yang tidak dapat dijelaskan, kecelakaan atau kebetulan adalah jawaban terbaik.",
  ui_story_5035_50350901_44_dialog_content = "Tepat! Kecelakaan cenderung banyak terjadi di sekitar saya dan PlayerName...",
  ui_story_5035_50350901_45_dialog_content = "Kecuali barusan, saya melihat kontradiksi.",
  ui_story_5035_50350901_46_dialog_content = "Oh? Kontradiksi apa?",
  ui_story_5035_50350901_47_dialog_content = "Ada cerita baru-baru ini di koran, saya tidak yakin apakah ada yang melihatnya?",
  ui_story_5035_50350901_48_dialog_content = "Sesuatu tentang hilangnya misterius bintang film horor.",
  ui_story_5035_50350901_49_dialog_content = "Oh! Saya pikir saya telah melihat judul itu!",
  ui_story_5035_50350901_50_dialog_content = "\"Aktris Film B-Horror yang Sedikit Dikenal Hilang\"?!",
  ui_story_5035_50350901_51_dialog_content = "Hal semacam itu memang terjadi di Umbraton, tapi...",
  ui_story_5035_50350901_52_dialog_content = "Ini jeritan aksi publisitas, bukan?",
  ui_story_5035_50350901_53_dialog_content = "Anda tahu, aktris itu membintangi film terakhir yang diambil oleh kru Jonny.",
  ui_story_5035_50350901_54_dialog_content = "Hah?! Pendahulu saya?",
  ui_story_5035_50350901_55_dialog_content = "Betul sekali. Hanya saja, saat itu nyonya belum membeli rumah berhantu, dan saya bukan bagian dari kru.",
  ui_story_5035_50350901_56_dialog_content = "Saya membacanya di catatan kru.",
  ui_story_5035_50350901_57_dialog_content = "Jadi apa yang terjadi? Bagaimana dia menghilang?",
  ui_story_5035_50350901_58_dialog_content = "Saya tidak punya ide. Catatan hanya menyebutkan bahwa aktris itu adalah bagian dari pemotretan dan tidak lebih.",
  ui_story_5035_50350901_59_dialog_content = "Jadi apa kontradiksinya?",
  ui_story_5035_50350901_60_dialog_content = "Apakah Anda ingat buku catatan kru yang kami temukan di ruang bawah tanah?",
  ui_story_5035_50350901_61_dialog_content = "Segala sesuatu di dalamnya ada hubungannya dengan film sebelumnya.",
  ui_story_5035_50350901_62_dialog_content = "Oh! Film yang dibintangi aktris yang hilang!",
  ui_story_5035_50350901_63_dialog_content = "Benar. Syuting film dipotong pendek, kemungkinan besar karena dia menghilang.",
  ui_story_5035_50350901_64_dialog_content = "Saya memastikan untuk melihat jadwal pemotretan yang ada di catatan.",
  ui_story_5035_50350901_65_dialog_content = "Kecuali ada kejadian tak terduga, penembakan itu dimaksudkan untuk selesai hari ini.",
  ui_story_5035_50350901_66_dialog_content = "Apakah Anda melihat masalahnya sekarang?",
  ui_story_5035_50350901_67_dialog_content = "Anda sedang berbicara tentang waktu?",
  ui_story_5035_50350901_68_dialog_content = "Ya. Sejauh menyangkut keluarga dan teman aktris itu, dia masih berada di lokasi syuting.",
  ui_story_5035_50350901_69_dialog_content = "Para kru tidak memiliki cara untuk menghubungi kerabatnya, dan keberadaannya tidak akan dipublikasikan.",
  ui_story_5035_50350901_70_dialog_content = "Jadi tidak ada yang akan tahu dia menghilang.",
  ui_story_5035_50350901_71_dialog_content = "Nah, letakkan seperti itu dan kedengarannya seperti ...",
  ui_story_5035_50350901_72_dialog_content = "<color=#e8d9bb>Tepuk tepuk tepuk!</color>",
  ui_story_5035_50350901_73_dialog_content = "Luar biasa! Apa alasan yang brilian!",
  ui_story_5035_50350901_74_dialog_content = "Kapan kamu muncul, Lilica? Apakah foto-fotonya sudah selesai?",
  ui_story_5035_50350901_75_dialog_content = "Ya. Aku hanya menunggu mereka kering.",
  ui_story_5035_50350901_76_dialog_content = "Bagaimanapun, teruskan. Jika tidak ada yang tahu bahwa aktris itu hilang, lalu bagaimana koran lokal melaporkannya?",
  ui_story_5035_50350901_77_dialog_content = "Hanya ada dua kemungkinan.",
  ui_story_5035_50350901_78_dialog_content = "Para kru, atau bahkan aktris itu sendiri, memberi tahu surat kabar tentang hilangnya itu.",
  ui_story_5035_50350901_79_dialog_content = "Oooh! Ya! Mereka satu-satunya yang bisa tahu!",
  ui_story_5035_50350901_80_dialog_content = "Benar. Tapi kemudian, apa alasan mereka harus melakukan hal seperti itu?",
  ui_story_5035_50350901_81_dialog_content = "Para kru tidak mendapatkan apa-apa jika berita hilangnya itu keluar. Tidak ada gunanya pergi ke pers hanya untuk publisitas negatif.",
  ui_story_5035_50350901_82_dialog_content = "Adapun aktris, mengapa dia ingin membocorkan berita tentang kepergiannya?",
  ui_story_5035_50350901_83_dialog_content = "Itu yang saya juga bertanya-tanya, tetapi belum berhasil.",
  ui_story_5035_50350901_84_dialog_content = "Jadi... Saya tidak berpikir aktris itu melakukannya sendiri.",
  ui_story_5035_50350901_85_dialog_content = "Dia tidak terlalu terkenal, jadi berita tentang kepergiannya tidak akan terlalu berarti.",
  ui_story_5035_50350901_86_dialog_content = "Sering kali ada biaya untuk mempublikasikan jenis laporan itu juga. Dari mana dia mendapatkan uang untuk itu?",
  ui_story_5035_50350901_87_dialog_content = "Mari kita fokus pada kemungkinan lain. Jika kru yang membocorkan cerita, apa motif mereka?",
  ui_story_5035_50350901_88_dialog_content = "Jika kita hanya mempertimbangkan kru...",
  ui_story_5035_50350901_89_dialog_content = "Mempublikasikan penghilangan itu akan menghabiskan biaya dan merusak reputasi mereka. Itu tidak akan layak.",
  ui_story_5035_50350901_90_dialog_content = "Satu-satunya pengecualian adalah jika kru berdiri untuk mendapatkan lebih banyak daripada kerugian mereka dalam menerbitkan berita.",
  ui_story_5035_50350901_91_dialog_content = "Oh?",
  ui_story_5035_50350901_92_dialog_content = "Saya akan mengatakan mereka sangat prihatin tentang keberadaannya.",
  ui_story_5035_50350901_93_dialog_content = "Mereka mungkin berpikir mereka entah bagaimana bisa menemukannya dan mendapatkannya kembali.",
  ui_story_5035_50350901_94_dialog_content = "<color=#e8d9bb>Tepuk tepuk tepuk!</color>",
  ui_story_5035_50350901_95_dialog_content = "Dikatakan dengan baik! Itu menjelaskannya kalau begitu!",
  ui_story_5035_50350901_96_dialog_content = "Ini kemungkinan besar.",
  ui_story_5035_50350901_97_dialog_content = "Masih banyak pertanyaan yang belum terjawab. Seperti mengapa mereka sangat ingin menemukannya? Dan bagaimana dia bisa menghilang?",
  ui_story_5035_50350901_98_dialog_content = "<color=#e8d9bb>Tepuk tepuk tepuk!</color>",
  ui_story_5035_50350901_99_dialog_content = "Tolong, Nona Lilica, bisakah Anda menahan diri untuk tidak bertepuk tangan? Saya mencoba untuk berpikir.",
  ui_story_5035_50350901_100_dialog_content = "Hah? Aku?",
  ui_story_5035_50350901_101_dialog_content = "Tapi aku tidak bertepuk tangan.",
  ui_story_5035_50350901_102_dialog_content = "<color=#e8d9bb>Tepuk tepuk tepuk!</color>",
  ui_story_5035_50350901_103_dialog_content = "Yah, siapa pun itu, bisakah kau hentikan kebisingannya?",
  ui_story_5035_50350901_104_dialog_content = "...",
  ui_story_5035_50350901_105_dialog_content = "...",
  ui_story_5035_50350901_106_dialog_content = "...",
  ui_story_5035_50350901_107_dialog_content = "<color=#e8d9bb>Tepuk tepuk tepuk! Tepuk tangan! TEPUK!</color>",
  ui_story_5035_50350901_108_dialog_content = "Kedengarannya seperti itu datang dari luar.",
  ui_story_5035_50350901_109_dialog_content = "T-Ada seseorang di luar sana?",
  ui_story_5035_50350901_110_dialog_content = "Aku berharap itu seseorang...",
  ui_story_5035_50350901_111_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5035_50350901_112_dialog_content = "<color=#e8d9bb>Bang bang!</color>",
  ui_story_5035_50350901_113_dialog_content = "<color=#e8d9bb>MENABRAK!</color>",
  ui_story_5035_50350901_114_dialog_content = "Graaagh!",
  ui_story_5035_50350901_115_dialog_content = "Bukan kalian lagi!",
  ui_story_5035_50350901_116_dialog_content = "Kita tidak bisa membiarkan mereka masuk! Minos mengatakan bahwa peralatan di sini sangat rapuh!",
  ui_story_5035_50350901_117_dialog_content = "Tentunya kita harus khawatir tentang menyelamatkan kulit kita sendiri terlebih dahulu?!",
  ui_story_5035_50350901_118_dialog_content = "Aku bisa kabur, tapi equipment tidak bisa!",
  ui_story_5035_50350901_119_dialog_content = "Anda benar-benar ada benarnya...",
  ui_story_5035_50350901_120_dialog_content = "Lupakan saja, ayo lawan mereka!",
  ui_story_5035_50351002_1_dialog_content = "Hmph, tidak sesulit yang saya kira.",
  ui_story_5035_50351002_2_dialog_content = "Sepertinya aku mulai terbiasa memberi Eclipsites pukulan sesekali.",
  ui_story_5035_50351002_3_dialog_content = "Kenapa kamu tidak pindah kalau begitu? Aku yakin Minos akan menyewakanmu kamar.",
  ui_story_5035_50351002_4_dialog_content = "Itu mengingatkan saya, apa yang dia lakukan? Saya tidak melihatnya selama pertarungan.",
  ui_story_5035_50351002_5_dialog_content = "Dia sama sekali tidak memperhatikan Eclipsites...",
  ui_story_5035_50351002_6_dialog_content = "Buku besar akun... Tidak masalah.",
  ui_story_5035_50351002_7_dialog_content = "Perjanjian sewa... Bagus.",
  ui_story_5035_50351002_8_dialog_content = "Mustahil. Harus ada jejak di suatu tempat. Aku akan melihat lagi...",
  ui_story_5035_50351002_9_dialog_content = "Whoa, ada apa dengan semua kertas di lantai?",
  ui_story_5035_50351002_10_dialog_content = "Apakah Anda mencoba mengubur diri Anda di dalamnya, Minos?",
  ui_story_5035_50351002_11_dialog_content = "Saya perlu mengkonfirmasi kredibilitas kru.",
  ui_story_5035_50351002_12_dialog_content = "Jika ada penyimpangan operasional, saya harus segera mengakhiri perjanjian kami.",
  ui_story_5035_50351002_13_dialog_content = "Saya tidak bisa membiarkan noda sedikit pun menodai bisnis Nona Nina.",
  ui_story_5035_50351002_14_dialog_content = "Wow! Sungguh pelayan yang berdedikasi!",
  ui_story_5035_50351002_15_dialog_content = "Ini semua adalah dokumen yang berhubungan dengan kru.",
  ui_story_5035_50351002_16_dialog_content = "Aktris itu tidak mungkin melewatkan apa pun.",
  ui_story_5035_50351002_17_dialog_content = "Pasti ada sebab, dan kemudian akibat.",
  ui_story_5035_50351002_18_dialog_content = "Jejak kertas ini harus menghubungkan semuanya, dan itu pasti tersembunyi di dokumen-dokumen ini.",
  ui_story_5035_50351002_19_dialog_content = "Itulah kunci untuk mengungkap semua ini. Aku harus menemukannya.",
  ui_story_5035_50351002_20_dialog_content = "Apa yang kamu katakan masuk akal tapi... Bukankah ini terlalu berlebihan?",
  ui_story_5035_50351002_21_dialog_content = "Saya belum pernah membaca begitu banyak kata sepanjang hidup saya.",
  ui_story_5035_50351002_22_dialog_content = "Saya sudah melewatinya sekali tetapi tidak menemukan sesuatu yang tidak diinginkan.",
  ui_story_5035_50351002_23_dialog_content = "Sekarang?",
  ui_story_5035_50351002_24_dialog_content = "Aku tidak pandai membaca. Saya pikir saya hanya akan menghalangi.",
  ui_story_5035_50351002_25_dialog_content = "Saya pikir foto yang saya kembangkan harus sudah siap sekarang. Biarkan aku pergi mendapatkan mereka.",
  ui_story_5035_50351002_26_dialog_content = "Daftar peralatan... biaya... kontrak...",
  ui_story_5035_50351002_27_dialog_content = "Tunggu, foto?",
  ui_story_5035_50351002_28_dialog_content = "Foto... foto...",
  ui_story_5035_50351002_29_dialog_content = "Itu dia! Foto!",
  ui_story_5035_50351002_30_dialog_content = "Ada apa, Minos? Anda mengejutkan saya!",
  ui_story_5035_50351002_31_dialog_content = "Pikiranku terlalu sempit.",
  ui_story_5035_50351002_32_dialog_content = "Saya tidak menemukan sesuatu yang luar biasa dalam dokumen mana pun.",
  ui_story_5035_50351002_33_dialog_content = "Karena apa yang luar biasa adalah apa yang BELUM saya lihat.",
  ui_story_5035_50351002_34_dialog_content = "Oh? Dan apakah itu?",
  ui_story_5035_50351002_35_dialog_content = "Gambar diam dari pertunjukan.",
  ui_story_5035_50351002_36_dialog_content = "Itu tidak harus diambil secara resmi, jadi saya bahkan tidak memikirkannya.",
  ui_story_5035_50351002_37_dialog_content = "Kebanyakan pemotretan biasanya menghasilkan banyak gambar diam, yang disimpan untuk kenang-kenangan atau untuk publisitas.",
  ui_story_5035_50351002_38_dialog_content = "Tapi saya belum melihat satu pun di semua dokumen ini.",
  ui_story_5035_50351002_39_dialog_content = "Tidak, itu tidak masuk akal. Baru hari ini, sutradara mengajak saya untuk mengambil beberapa gambar diam.",
  ui_story_5035_50351002_40_dialog_content = "Melihat mereka diambil kali ini, pasti ada beberapa dari terakhir kali juga.",
  ui_story_5035_50351002_41_dialog_content = "Mengambil foto dan menyimpannya adalah eksklusif satu sama lain.",
  ui_story_5035_50351002_42_dialog_content = "Mungkin foto-foto itu tidak dimaksudkan untuk dilihat orang lain...",
  ui_story_5035_50351002_43_dialog_content = "Foto sudah siap!!",
  ui_story_5035_50351002_44_dialog_content = "Mereka tidak buruk sama sekali! Mau datang untuk melihat?",
  ui_story_5035_50351002_45_dialog_content = "Sekarang?",
  ui_story_5035_50351002_46_dialog_content = "Saya pikir kami membuat beberapa kemajuan. Ini bukan waktu yang tepat untuk foto grup...",
  ui_story_5035_50351002_47_dialog_content = "Oh ayolah! Jangan terlalu tegang.",
  ui_story_5035_50351002_48_dialog_content = "Mungkin perubahan suasana hati akan membantu Anda berpikir.",
  ui_story_5035_50351002_49_dialog_content = "Ayo, semuanya, ke sini.",
  ui_story_5035_50351002_50_dialog_content = "Ekspresi Sadie tak ternilai harganya!",
  ui_story_5035_50351002_51_dialog_content = "Apa itu untukmu?",
  ui_story_5035_50351002_52_dialog_content = "Butler hebat kita harus ingat untuk melihat ke kamera lain kali!",
  ui_story_5035_50351002_53_dialog_content = "Oh.",
  ui_story_5035_50351002_54_dialog_content = "Wakil dan PlayerName terlihat bagus! Mereka bisa menjadi aktor!",
  ui_story_5035_50351002_55_dialog_content = "Ya... Saya tidak berpikir akting begitu sederhana.",
  ui_story_5035_50351002_56_dialog_content = "Itu hanya foto, jangan dibesar-besarkan...",
  ui_story_5035_50351002_57_dialog_content = "Tunggu sebentar! Ada... lima dari kita, kan?",
  ui_story_5035_50351002_58_dialog_content = "Satu dua tiga empat lima. Ya, lima!",
  ui_story_5035_50351002_59_dialog_content = "Jadi mengapa ada tangan ekstra di foto...?",
  ui_story_5035_50351002_60_dialog_content = "!!!",
  ui_story_5035_50351002_61_dialog_content = "Itu, itu benar! Ada tangan di sini yang sepertinya bukan milik siapa pun!",
  ui_story_5035_50351002_62_dialog_content = "Hah? Apa?! APA?!!",
  ui_story_5035_50351002_63_dialog_content = "... Saya yakin tidak ada orang lain di ruang bawah tanah selain kami.",
  ui_story_5035_50351002_64_dialog_content = "Benar, aku juga, tapi fotonya...",
  ui_story_5035_50351002_65_dialog_content = "Foto... foto...",
  ui_story_5035_50351002_66_dialog_content = "Mungkinkah ini sebabnya kru tidak menyimpan foto mereka?",
  ui_story_5035_50351002_67_dialog_content = "PlayerName, aku baru ingat...",
  ui_story_5035_50351002_68_dialog_content = "Apakah Anda ingat apa yang dikatakan Baba Yaga kepada kita...?",
  ui_story_5035_50351002_69_dialog_content = "PlayerName—Saya tidak melihat <color=#FFB400>dia</color> denganmu.",
  ui_story_5035_50351002_70_dialog_content = "Sepertinya aku bertemu <color=#FFB400>dia</color> sebelum kalian semua.",
  ui_story_5035_50351002_71_dialog_content = "<color=#FFB400>Hati-hati. Jangan biarkan dia menangkapmu...</color>",
  ui_story_5035_50351002_72_dialog_content = "Karena, hanya aku yang bisa <color=#FFB400>menyeretnya ke dalam perjamuan cinta.</color>",
  ui_story_5035_50351002_73_dialog_content = "Ya, sedikit.",
  ui_story_5035_50351002_74_dialog_content = "Kami mencoba menebak siapa yang terus dirujuk oleh Baba Yaga, tetapi kami tidak pernah mendapat jawaban langsung.",
  ui_story_5035_50351002_75_dialog_content = "Yah, sepertinya \"dia\" benar-benar ada...",
  ui_story_5035_50351002_76_dialog_content = "\"Hati-hati! Jangan biarkan dia menangkapmu...\"",
  ui_story_5035_50351002_77_dialog_content = "Baba Yaga memperingatkan kami untuk berhati-hati.",
  ui_story_5035_50351002_78_dialog_content = "Kami seharusnya mewaspadai seseorang, atau sesuatu, di mansion yang belum pernah kami lihat sebelumnya...",
  ui_story_5035_50351002_79_dialog_content = "Untuk waspada terhadap White Lady.",
  ui_story_5035_50351101_1_dialog_content = "(Apakah saya benar-benar harus mulai percaya pada hantu sekarang?)",
  ui_story_5035_50351101_2_dialog_content = "(Saya telah banyak memikirkannya dan terkadang benar-benar membiarkan imajinasi saya menjadi liar.)",
  ui_story_5035_50351101_3_dialog_content = "(Namun, setiap kali itu hanya lamunan yang fantastis. Saya tidak pernah memiliki jawaban konkret dengan satu atau lain cara.)",
  ui_story_5035_50351101_4_dialog_content = "(Tapi tiba-tiba, apa yang dulunya merupakan kemungkinan yang jauh berdiri tepat di depanku.)",
  ui_story_5035_50351101_5_dialog_content = "(Penyangga antara dunia kita telah hilang, dan sekarang kita sedekat White Lady dengan saya di foto itu.)",
  ui_story_5035_50351101_6_dialog_content = "(Saya harus bergegas dan menyelesaikan ini sebelum jari-jari itu menutup tenggorokan saya.)",
  ui_story_5035_50351101_7_dialog_content = "Jadi benar-benar ada—",
  ui_story_5035_50351101_8_dialog_content = "Jadi itu benar-benar benar! Rumah ini berhantu!",
  ui_story_5035_50351101_9_dialog_content = "Eh...?",
  ui_story_5035_50351101_10_dialog_content = "Betapa menakjubkan! Kami memiliki foto sebagai bukti definitif!",
  ui_story_5035_50351101_11_dialog_content = "Begitulah cara saya berguling, pemburu hantu terhebat di dunia! Saya membuatnya terlihat mudah!",
  ui_story_5035_50351101_12_dialog_content = "Mari kita selesaikan dengan kru!",
  ui_story_5035_50351101_13_dialog_content = "Tunggu, tidakkah kita harus memikirkan ini lebih jauh? Jika kita mengatakan benar-benar ada hantu...",
  ui_story_5035_50351101_14_dialog_content = "Dan mengapa kita pergi ke kru?",
  ui_story_5035_50351101_15_dialog_content = "Mereka sengaja menyembunyikan foto itu, mungkin karena mereka tahu keberadaan White Lady.",
  ui_story_5035_50351101_16_dialog_content = "Namun, ini masih hanya spekulasi. Kami masih tidak bisa menghubungkan kru dengan White Lady.",
  ui_story_5035_50351101_17_dialog_content = "Anda hanya akan memperingatkan mereka dengan bertindak gegabah. Saya menyarankan Anda untuk tidak terburu-buru melakukan apa pun.",
  ui_story_5035_50351101_18_dialog_content = "Hmph. Jika petunjuk yang kita miliki sekarang masih belum cukup untuk mengikat White Lady dengan kru...",
  ui_story_5035_50351101_19_dialog_content = "Bagaimana jika kita menambahkan aktris yang hilang ke dalam campuran?",
  ui_story_5035_50351101_20_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5035_50351101_21_dialog_content = "Ta-daa! Lihatlah wajahku yang sebenarnya!",
  ui_story_5035_50351101_22_dialog_content = "Saya hampir tidak melihat perbedaan dari sebelumnya.",
  ui_story_5035_50351101_23_dialog_content = "Saya sebenarnya sudah sangat ingin menanyakan alasan janggut palsu itu.",
  ui_story_5035_50351101_24_dialog_content = "Tapi—Tunggu sebentar, apa yang baru saja kamu katakan? Aktris yang hilang?!",
  ui_story_5035_50351101_25_dialog_content = "Betul sekali! \"Aktris Film B-Horror yang Dikenal Kecil\" yang hilang? Apakah Lilika!",
  ui_story_5035_50351101_26_dialog_content = "Apa?!",
  ui_story_5035_50351101_27_dialog_content = "Hah?",
  ui_story_5035_50351101_28_dialog_content = "Huh...",
  ui_story_5035_50351101_29_dialog_content = "Nah, itu membuat segalanya lebih mudah. Beritahu kami tentang semua hal tentang hilangnya itu.",
  ui_story_5035_50351101_30_dialog_content = "Mari saya mulai dengan film horor terakhir yang disutradarai Jonny.",
  ui_story_5035_50351101_31_dialog_content = "Saya selalu menyukai film, terutama film horor.",
  ui_story_5035_50351101_32_dialog_content = "Jadi saya sangat senang ketika Jonny meminta saya untuk membintangi film barunya.",
  ui_story_5035_50351101_33_dialog_content = "Lokasi pemotretan—seperti yang Anda semua tahu—direncanakan untuk rumah ini.",
  ui_story_5035_50351101_34_dialog_content = "Semuanya berjalan sesuai rencana, tapi saat kami sampai di basement... terjadi kecelakaan.",
  ui_story_5035_50351101_35_dialog_content = "Kecelakaan? Kecelakaan seperti apa?",
  ui_story_5035_50351101_36_dialog_content = "Itu semua sedikit berantakan. Pertama, saya mendengar tetesan air, dan kemudian denting lonceng.",
  ui_story_5035_50351101_37_dialog_content = "Oh, dan saya tidak bisa melupakan lilin! Saya melihat lilin ditempatkan tanpa alasan di sekitar ruang bawah tanah.",
  ui_story_5035_50351101_38_dialog_content = "Lalu... sesuatu muncul. Aku tidak bisa melihatnya dengan baik, tapi itu bukan seseorang.",
  ui_story_5035_50351101_39_dialog_content = "Itu ingin membunuhku. Keinginannya untuk melakukannya sangat kuat.",
  ui_story_5035_50351101_40_dialog_content = "Saya diserang dan terluka parah. Sangat buruk, pada kenyataannya, saya pikir saya akan mati di bawah sana.",
  ui_story_5035_50351101_41_dialog_content = "Tapi untungnya, keterampilan terbesar saya selalu melarikan diri.",
  ui_story_5035_50351101_42_dialog_content = "Aku berlari sangat lama di kegelapan malam. Saya berlari dan berlari, dan akhirnya kembali ke Umbraton, di mana seorang dokter berhasil menyelamatkan saya.",
  ui_story_5035_50351101_43_dialog_content = "Saya kedinginan selama dua hari penuh di kliniknya, tetapi setelah itu, yang terburuk berakhir dan saya bangun lagi.",
  ui_story_5035_50351101_44_dialog_content = "Menjalani semua yang pasti... menyayat hati.",
  ui_story_5035_50351101_45_dialog_content = "Jadi ketika kami berada di ruang bawah tanah, dan Anda meminta saya untuk mengambil kamera dan memotret...",
  ui_story_5035_50351101_46_dialog_content = "Memang. Jika terjadi kecelakaan lagi, setidaknya kebenarannya akan terekam kamera.",
  ui_story_5035_50351101_47_dialog_content = "Aku tidak percaya kamu kembali. Itu butuh nyali.",
  ui_story_5035_50351101_48_dialog_content = "Jika terserah saya, saya tidak akan pernah kembali dalam jarak satu mil dari tempat ini selama sisa hidup saya.",
  ui_story_5035_50351101_49_dialog_content = "Aku bahkan tidak akan kembali pada awalnya. Hantu sangat menakutkan. Mengapa menempatkan diri saya kembali dalam bahaya?",
  ui_story_5035_50351101_50_dialog_content = "Tapi kemudian saya mendapat kabar aneh bahwa Jonny dan krunya akan tetap syuting di lokasi yang sama.",
  ui_story_5035_50351101_51_dialog_content = "... Itu aneh, dengan apa yang telah terjadi dan sebagainya.",
  ui_story_5035_50351101_52_dialog_content = "Setelah itu, saya melihat berita hilangnya saya di koran.",
  ui_story_5035_50351101_53_dialog_content = "...",
  ui_story_5035_50351101_54_dialog_content = "Anda pasti kemudian sampai pada kesimpulan yang sama seperti yang saya lakukan.",
  ui_story_5035_50351101_55_dialog_content = "Atau mungkin sebelumnya, Anda membantu memandu alasan saya.",
  ui_story_5035_50351101_56_dialog_content = "Jadi... Saya tidak berpikir aktris itu melakukannya sendiri.",
  ui_story_5035_50351101_57_dialog_content = "Mari kita fokus pada kemungkinan lain. Jika kru yang membocorkan cerita, apa motif mereka?",
  ui_story_5035_50351101_58_dialog_content = "Hehe ... Saya tidak akan menyebutnya membimbing Anda, lebih seperti membantu Anda mengesampingkan beberapa opsi yang salah.",
  ui_story_5035_50351101_59_dialog_content = "Saya telah memikirkannya untuk waktu yang lama, dan menemukan beberapa teori mengerikan tentang perilaku aneh para kru.",
  ui_story_5035_50351101_60_dialog_content = "Rumah ini sebenarnya berhantu, dan para kru tahu tentang hantu itu.",
  ui_story_5035_50351101_61_dialog_content = "Mereka bermaksud untuk menembak di tempat-tempat yang benar-benar angker.",
  ui_story_5035_50351101_62_dialog_content = "Lalu tujuan mereka adalah...",
  ui_story_5035_50351101_63_dialog_content = "Itu semua adalah pengaturan. Menipu aktris yang tidak menaruh curiga sepertiku untuk ambil bagian...",
  ui_story_5035_50351101_64_dialog_content = "Betapapun pintar dan cerdiknya hantu buatan manusia, mereka sama sekali tidak berdampak seperti hantu yang sebenarnya.",
  ui_story_5035_50351101_65_dialog_content = "Mereka akan melakukan apa pun untuk membuat film horor tidak seperti yang lain.",
  ui_story_5035_50351101_66_dialog_content = "Sebuah pengaturan...",
  ui_story_5035_50351101_67_dialog_content = "Jadi mereka menerbitkan berita hilangnyamu hanya untuk membuatmu kembali lagi? Untuk menyelesaikan pemotretan?",
  ui_story_5035_50351101_68_dialog_content = "Ya, harus begitu.",
  ui_story_5035_50351101_69_dialog_content = "Pemotretan sudah mendekati akhir. Jika saya tidak menyelesaikan pekerjaan saya, semua yang telah difilmkan akan sia-sia.",
  ui_story_5035_50351101_70_dialog_content = "Konsekuensi dari tidak mendapatkan saya kembali adalah apa yang terjadi sekarang—memulai dari awal dengan aktris baru.",
  ui_story_5035_50351101_71_dialog_content = "Jadi itulah yang menanti saya... Saya harus benar-benar berterima kasih.",
  ui_story_5035_50351101_72_dialog_content = "Ah, tidak perlu berterima kasih padaku!",
  ui_story_5035_50351101_73_dialog_content = "Bagaimanapun, setelah saya mengetahui apa yang dilakukan kru, tidak mungkin saya membiarkan diri saya tertipu.",
  ui_story_5035_50351101_74_dialog_content = "Jadi saya membalikkan keadaan pada mereka. Jika kru ingin menemukan saya dengan menerbitkan berita hilangnya saya, maka saya benar-benar akan menghilang.",
  ui_story_5035_50351101_75_dialog_content = "Dan untuk memastikan tidak ada aktris lain yang menjadi korban seperti saya, saya memutuskan untuk mengekspos mereka.",
  ui_story_5035_50351101_76_dialog_content = "Oh! Jadi kau datang untuk menyelamatkan Goldie dan aku!",
  ui_story_5035_50351101_77_dialog_content = "<anim type=Shake><size=45>Pikiran</size> kamu adalah<size=45> sebuah </size>pertanda kiamat <size=50>kaboom</size>, tapi tidak oh tidak<size=45> Anda</size> adalah<size=45> sebuah</size> pahlawan<size=45> dalam kostum</size> </anim>",
  ui_story_5035_50351101_78_dialog_content = "Hehe! Tentu saja, tapi itu juga untuk memberi pelajaran kepada penipu yang tidak berguna itu.",
  ui_story_5035_50351101_79_dialog_content = "Kita bisa mengekspos rencana kru ke dunia jika kita bisa menemukan cukup bukti.",
  ui_story_5035_50351101_80_dialog_content = "Jadi, rencana besar Lilica adalah menyamar dan menyusup!",
  ui_story_5035_50351101_81_dialog_content = "\"Menyamar\" ... benar ...",
  ui_story_5035_50351101_82_dialog_content = "Apa? Itu berhasil, bukan?",
  ui_story_5035_50351101_83_dialog_content = "Dengan foto hantu ini, spekulasi kami terbukti benar!",
  ui_story_5035_50351101_84_dialog_content = "Aku harus meluruskan ini dengan mereka! Menghukum para pelanggar dan membersihkan industri!",
  ui_story_5035_50351101_85_dialog_content = "Apakah kalian ingin ikut denganku?",
  ui_story_5035_50351101_86_dialog_content = "Paling pasti. Para kru menyembunyikan sesuatu dari kami. Kontrak kami batal.",
  ui_story_5035_50351101_87_dialog_content = "Mereka tidak lagi diterima di Rumah Hantu Andersen.",
  ui_story_5035_50351101_88_dialog_content = "Para psikopat gila itu ingin memfilmkan saya di posisi terendah saya, tetapi saya akan menunjukkan kepada MEREKA bahwa saya bukan musuh yang mudah!",
  ui_story_5035_50351101_89_dialog_content = "Dengan semua yang telah mereka lakukan, tidak mungkin kita bersikap mudah terhadap mereka!",
  ui_story_5035_50351101_90_dialog_content = "Betul sekali! Tanpa belas kasihan!",
  ui_story_5035_50351101_91_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5035_50351101_92_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5035_50351101_93_dialog_content = "A-Apa itu?",
  ui_story_5035_50351101_94_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5035_50351101_95_dialog_content = "Langkah kaki... Langkah kaki berat...",
  ui_story_5035_50351101_96_dialog_content = "Apakah mereka mencoba merobohkan rumah?",
  ui_story_5035_50351101_97_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5035_50351101_98_dialog_content = "Jadi apakah kita masih harus keluar dan menakut-nakuti mereka?",
  ui_story_5035_50351101_99_dialog_content = "Mengapa Anda tidak pergi melihat-lihat ...",
  ui_story_5035_50351101_100_dialog_content = "Grah...",
  ui_story_5035_50351101_101_dialog_content = "Hei, kamu... Kamu... Eclipsite sungguhan?",
  ui_story_5035_50351101_102_dialog_content = "Permisi...",
  ui_story_5035_50351101_103_dialog_content = "Tidak ada apa pun tentang malam ini yang berjalan seperti yang seharusnya di Buku Pegangan Karyawan. Hal-hal yang saya lakukan untuk mencoba dan menghasilkan uang ...",
  ui_story_5035_50351101_104_dialog_content = "Gaah!!!",
  ui_story_5035_50351101_105_dialog_content = "Apa yang—!! Apa yang terjadi?!",
  ui_story_5035_50351101_106_dialog_content = "Apa sebenarnya benda itu? Seekor monster?",
  ui_story_5035_50351101_107_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5035_50351101_108_dialog_content = "Menyingkirlah, kalian anak-anak nakal yang mengerikan!",
  ui_story_5035_50351101_109_dialog_content = "Aku mulai menjadi BENAR-BENAR GILA!",
  ui_story_5035_50351101_110_dialog_content = "Eh? Uh, nona, aku...",
  ui_story_5035_50351101_111_dialog_content = "MENJIJIKKAN! Enyah!!",
  ui_story_5035_50351101_112_dialog_content = "Argh—",
  ui_story_5035_50351102_1_dialog_content = "<color=#e8d9bb>Ding... Ding...</color>",
  ui_story_5035_50351102_2_dialog_content = "Hei, apakah kamu mendengar keributan di lantai atas barusan?",
  ui_story_5035_50351102_3_dialog_content = "Ya! Aku mendengar sesuatu, pasti.",
  ui_story_5035_50351102_4_dialog_content = "Mungkin hanya pengunjung rumah hantu. Itu normal bagi mereka untuk menjadi panik.",
  ui_story_5035_50351102_5_dialog_content = "Ah, aku cemburu. Saya berharap saya bisa bersenang-senang di sini juga.",
  ui_story_5035_50351102_6_dialog_content = "Jangan bodoh. Kami di sini untuk bekerja dan mendapatkan uang.",
  ui_story_5035_50351102_7_dialog_content = "Jika Anda punya waktu untuk melamun, Anda punya waktu untuk memindahkan peralatan ke pintu masuk. Direktur menunggu.",
  ui_story_5035_50351102_8_dialog_content = "<color=#e8d9bb>Ding... Ding...</color>",
  ui_story_5035_50351102_9_dialog_content = "Apakah Anda mendengar itu? Benar-benar ada hantu di sini!",
  ui_story_5035_50351102_10_dialog_content = "Nah, duh. Tentu saja mereka akan mengatakan itu. Kalau tidak, bagaimana mereka bisa membuat orang membeli tiket?",
  ui_story_5035_50351102_11_dialog_content = "Siapa tahu? Mungkin benar. Aku merasa sangat ketakutan selama ini.",
  ui_story_5035_50351102_12_dialog_content = "Hampir seperti... Seseorang mengikutiku.",
  ui_story_5035_50351102_13_dialog_content = "Pff, siapa yang punya waktu untuk mengejarmu?",
  ui_story_5035_50351102_14_dialog_content = "Apakah Anda tidak mendengar? Wanita yang pertama kali membangun tempat ini selalu khawatir bahwa sesuatu yang keji akan menyelinap masuk dan mencoba membunuhnya.",
  ui_story_5035_50351102_15_dialog_content = "Jika hal keji itu mendapatkan orang yang salah...",
  ui_story_5035_50351102_16_dialog_content = "Hei, kamu banyak—",
  ui_story_5035_50351102_17_dialog_content = "Ahhh!",
  ui_story_5035_50351102_18_dialog_content = "Tidak tidak tidak! Itu bukan aku! Janji!",
  ui_story_5035_50351102_19_dialog_content = "Jangan bergerak!",
  ui_story_5035_50351102_20_dialog_content = "Hah? Oh, itu orang yang sebenarnya.",
  ui_story_5035_50351102_21_dialog_content = "Ya, saya sedang berbicara dengan Anda! Anda adalah bagian dari kru yang mengerikan itu!",
  ui_story_5035_50351102_22_dialog_content = "Saya telah melihat melalui skema Anda!",
  ui_story_5035_50351102_23_dialog_content = "Menipu aktris malang, menggunakan hidup mereka sebagai alat tawar-menawar untuk memuaskan keinginan mengerikan Anda sendiri!",
  ui_story_5035_50351102_24_dialog_content = "Itu... Itu kriminal...",
  ui_story_5035_50351102_25_dialog_content = "Bersalah begitu banyak, kita bisa menulis novel.",
  ui_story_5035_50351102_26_dialog_content = "Betul sekali! Kita bisa menulis novel!",
  ui_story_5035_50351102_27_dialog_content = "Sigh... Bukankah kamu baru saja menghafalnya? Kenapa kau menjatuhkan bola di saat kritis seperti itu...",
  ui_story_5035_50351102_28_dialog_content = "Salahkan Mino! Kata-katanya sangat sulit untuk diingat!",
  ui_story_5035_50351102_29_dialog_content = "Andalah yang ingin saya membantu Anda menulis beberapa \"kata sambutan pembuka yang terdengar cerdas\"!",
  ui_story_5035_50351102_30_dialog_content = "Baiklah, lupakan saja! Tidak masalah!",
  ui_story_5035_50351102_31_dialog_content = "Bagaimanapun, Anda banyak! Setelah sangat menyakitiku, sekarang mereka akan melakukan hal yang sama pada aktris baru!",
  ui_story_5035_50351102_32_dialog_content = "Saya punya cukup bukti untuk membuktikan bahwa tempat ini benar-benar angker!",
  ui_story_5035_50351102_33_dialog_content = "Karena Anda berani kembali, ini menunjukkan bahwa Anda pasti sudah tahu tentang hantu itu, dan ingin menggunakannya untuk kepentingan Anda sendiri!",
  ui_story_5035_50351102_34_dialog_content = "Ini akhir untukmu! Besok kamu akan dihukum oleh Geng Istvan!",
  ui_story_5035_50351102_35_dialog_content = "Tapi sebelum itu, aku punya sandwich buku jari menunggumu!",
  ui_story_5035_50351102_36_dialog_content = "Anda siap menghadapi kemarahan korban Anda?!!",
  ui_story_5035_50351102_37_dialog_content = "Hukuman? Sandwich buku jari? Kami dalam masalah sekarang!",
  ui_story_5035_50351102_38_dialog_content = "Hmph! Terlambat untuk menyesal sekarang!",
  ui_story_5035_50351102_39_dialog_content = "Oh tidak!!",
  ui_story_5035_50351102_40_dialog_content = "Um, bisakah saya mengajukan pertanyaan singkat?",
  ui_story_5035_50351102_41_dialog_content = "Siapa, um, siapa kamu sebenarnya?",
  ui_story_5035_50351102_42_dialog_content = "Hah? Anda tidak mengenali saya? Kami pernah...",
  ui_story_5035_50351102_43_dialog_content = "Eh? Tunggu sebentar.",
  ui_story_5035_50351102_44_dialog_content = "Kamu...",
  ui_story_5035_50351102_45_dialog_content = "Siapa kau?",
  ui_story_5035_50351102_X45_dialog_content = "Oh! Bukankah itu...",
  ui_story_5035_50351102_X46_dialog_content = "Kamu kenal mereka?",
  ui_story_5035_50351102_X47_dialog_content = "Ini Lester dan Konstantin!",
  ui_story_5035_50351102_X48_dialog_content = "PlayerName! Anda juga datang?",
  ui_story_5035_50351102_X49_dialog_content = "Rumah Hantu Andersen benar-benar populer.",
  ui_story_5035_50351102_X50_dialog_content = "Apakah ada kesalahpahaman? Mengapa Anda dua anggota kru?",
  ui_story_5035_50351102_46_dialog_content = "Apa yang sedang terjadi??",
  ui_story_5035_50351102_47_dialog_content = "Aku baru saja akan menanyakan itu! Anda telah memberi kami perhatian yang layak, tetapi saya rasa kami bahkan tidak saling mengenal!",
  ui_story_5035_50351102_48_dialog_content = "Apa ini semua tentang? Bukankah kalian syuting film bersama?",
  ui_story_5035_50351102_49_dialog_content = "Astaga! Saya minta maaf! Saya pikir Anda adalah anggota kru film, tetapi tampaknya saya salah!",
  ui_story_5035_50351102_50_dialog_content = "Saya sangat menyesal!",
  ui_story_5035_50351102_51_dialog_content = "Apa? Kami ADALAH anggota kru! Kecuali aku sudah dipecat?!",
  ui_story_5035_50351102_52_dialog_content = "Kami memindahkan alat peraga. Bukankah itu hal yang akan dilakukan awak kapal?",
  ui_story_5035_50351102_53_dialog_content = "Atribut?",
  ui_story_5035_50351102_54_dialog_content = "<color=#e8d9bb>Ding... Ding...</color>",
  ui_story_5035_50351102_55_dialog_content = "Baiklah, aku akan menggigit. Ada apa dengan peti mati dengan lonceng?",
  ui_story_5035_50351102_56_dialog_content = "Ya... Itulah kekurangan sial dari bekerja di film horor, semuanya memberi Anda heebie jeebies.",
  ui_story_5035_50351102_57_dialog_content = "Dia pengawas naskah, dan aku fotografernya.",
  ui_story_5035_50351102_58_dialog_content = "Jadi bagaimana jika kita adalah bagian dari kru? Itu tidak mengubah fakta bahwa kami tidak mengenal Anda.",
  ui_story_5035_50351102_59_dialog_content = "Hah? Tapi pengawas naskah dan fotografer sebelumnya...",
  ui_story_5035_50351102_60_dialog_content = "Apa yang sedang terjadi? Apakah mereka mengubah staf?",
  ui_story_5035_50351102_61_dialog_content = "Kami hanya mendapat pekerjaan ini baru-baru ini. Tapi asal kau tahu, kami bukan amatir—",
  ui_story_5035_50351102_62_dialog_content = "Astaga!",
  ui_story_5035_50351102_63_dialog_content = "A-Apa itu?",
  ui_story_5035_50351102_64_dialog_content = "Jika mereka memiliki anggota kru baru, apa yang terjadi dengan yang lama?",
  ui_story_5035_50351102_65_dialog_content = "Hmm…",
  ui_story_5035_50351102_66_dialog_content = "<color=#828282>Membanting!</color>",
  ui_story_5035_50351102_67_dialog_content = "!!!",
  ui_story_5035_50351102_68_dialog_content = "<color=#828282>Membanting!</color>",
  ui_story_5035_50351102_69_dialog_content = "<color=#828282>Membanting!</color>",
  ui_story_5035_50351102_70_dialog_content = "<color=#828282>Membanting!</color>",
  ui_story_5035_50351102_71_dialog_content = "<color=#e8d9bb>MEMBANTING!!!</color>",
  ui_story_5035_50351102_72_dialog_content = "Suara apakah itu...? Apa yang terjadi?",
  ui_story_5035_50351102_73_dialog_content = "Ini pintunya. Mereka semua hanya membanting.",
  ui_story_5035_50351102_74_dialog_content = "Seseorang ingin menjebak kita di sini.",
  ui_story_5035_50351102_75_dialog_content = "Siapa yang mau melakukan itu...?",
  ui_story_5035_50351102_76_dialog_content = "Lilika... Lilika...",
  ui_story_5035_50351102_77_dialog_content = "Bintangku yang tidak berguna...",
  ui_story_5035_50351102_78_dialog_content = "Akhirnya aku menemukanmu.",
  ui_story_5035_50351102_79_dialog_content = "(Setelah suara menyeramkan itu memudar, sosok sutradara Jonny perlahan muncul di hadapan kami.)",
  ui_story_5035_50351102_80_dialog_content = "(Dia berdiri di dekat pegangan tangga di lantai berikutnya, melihat ke arah kami.)",
  ui_story_5035_50351102_81_dialog_content = "(Perbedaan ketinggian mengintensifkan tatapannya yang cermat, menekan kami dari lantai atas.)",
  ui_story_5035_50351102_82_dialog_content = "(Ketegangan menembus udara, hanya dipatahkan oleh sedikit suara kertakan gigi.)",
  ui_story_5035_50351102_83_dialog_content = "Direct-ect-atau Jon-ny.",
  ui_story_5035_50351102_84_dialog_content = "Saya harus mengakui, Anda melakukan pekerjaan dengan baik.",
  ui_story_5035_50351102_85_dialog_content = "Saya sangat menyukai apa yang kami rekam bersama. Itu sangat mungkin karya terbaik saya.",
  ui_story_5035_50351102_86_dialog_content = "Sayang sekali Anda tidak memiliki apa yang diperlukan untuk berhasil di industri ini.",
  ui_story_5035_50351102_87_dialog_content = "Anda bahkan tidak mengerti konsep <color=#FFB400>menyelesaikan</color> film.",
  ui_story_5035_50351102_88_dialog_content = "Itu sebabnya Anda mencari saya di mana-mana? Untuk menyelesaikan film?",
  ui_story_5035_50351102_89_dialog_content = "Tidak lagi.",
  ui_story_5035_50351102_90_dialog_content = "Film itu selesai sejak hari kau kehabisan kami.",
  ui_story_5035_50351102_91_dialog_content = "Tidak peduli apa lagi yang Anda lakukan, itu ditakdirkan untuk ember murah di toko film diskon. Tercela, hal itu.",
  ui_story_5035_50351102_92_dialog_content = "Ada alasan lain aku mencarimu.",
  ui_story_5035_50351102_93_dialog_content = "Saya ingin tahu seberapa banyak Anda dapat melihat dalam gelap.",
  ui_story_5035_50351102_94_dialog_content = "Mereka yang melihat terlalu banyak tidak dapat diizinkan untuk berbicara, Anda tahu.",
  ui_story_5035_50351102_95_dialog_content = "Tidak bisa diizinkan untuk berbicara? Apa yang sedang kamu kerjakan...?",
  ui_story_5035_50351102_96_dialog_content = "Direktur! Direktur Joni!",
  ui_story_5035_50351102_97_dialog_content = "Ini dia! Aku sudah mencarimu kemana-mana.",
  ui_story_5035_50351102_98_dialog_content = "Saya sedang melihat naskah dan ingin mendiskusikan kalimat ini dengan Anda.",
  ui_story_5035_50351102_99_dialog_content = "Garis yang mana? Biarku lihat.",
  ui_story_5035_50351102_100_dialog_content = "Disini...",
  ui_story_5035_50351102_101_dialog_content = "Oh tidak! Dia tidak tahu apa-apa!",
  ui_story_5035_50351102_102_dialog_content = "Goldie!! Berhenti!",
  ui_story_5035_50351102_103_dialog_content = "Hah? Apa...?",
  ui_story_5035_50351102_104_dialog_content = "Sst—",
  ui_story_5035_50351102_105_dialog_content = "Anda telah dibungkus.",
  ui_story_5035_50351102_106_dialog_content = "Dia...",
  ui_story_5035_50351102_107_dialog_content = "Ahhhh—!",
  ui_story_5035_50351201_1_dialog_content = "Dia... Dia membunuh Goldie?!",
  ui_story_5035_50351201_2_dialog_content = "...",
  ui_story_5035_50351201_3_dialog_content = "Aku takut begitu.",
  ui_story_5035_50351201_4_dialog_content = "Menambahkan satu lagi ke jumlah tubuh tidak berarti apa-apa baginya.",
  ui_story_5035_50351201_5_dialog_content = "Awak syuting terakhir semuanya mengalami kecelakaan yang tidak menguntungkan, bukan begitu, Jonny?",
  ui_story_5035_50351201_6_dialog_content = "Mereka semua...?",
  ui_story_5035_50351201_7_dialog_content = "Menarik, Pak Produser. Apa yang membuatmu mengatakan itu?",
  ui_story_5035_50351201_8_dialog_content = "Lilica salah ketika dia mengira seluruh kru ada di dalamnya.",
  ui_story_5035_50351201_9_dialog_content = "Semua ini, dari awal hingga akhir, adalah ide Anda.",
  ui_story_5035_50351201_10_dialog_content = "Tidak ada satu pun yang tersisa di semua dokumen yang Anda tinggalkan.",
  ui_story_5035_50351201_11_dialog_content = "Saya pikir itu karena Anda menyembunyikan keberadaan hantu.",
  ui_story_5035_50351201_12_dialog_content = "Jelas sekarang bahwa apa yang Anda sembunyikan bukanlah hal supernatural.",
  ui_story_5035_50351201_13_dialog_content = "Itu adalah anggota awak asli, darah dan daging yang akan menjadi sasaran tembakan.",
  ui_story_5035_50351201_14_dialog_content = "Catatan personel dapat diedit, tetapi foto tidak berbohong.",
  ui_story_5035_50351201_15_dialog_content = "Mereka akan mengungkapkan bahwa Anda mengganti seluruh kru Anda,",
  ui_story_5035_50351201_16_dialog_content = "karena kau membunuh mereka semua.",
  ui_story_5035_50351201_17_dialog_content = "Well, well, well... Aku tahu itu adalah pilihan yang tepat untuk bekerja denganmu, Tn. Produser. Anda benar-benar cukup jeli.",
  ui_story_5035_50351201_18_dialog_content = "Saya sebenarnya berterima kasih kepada Anda karena telah menyelesaikannya. Berarti saya tidak perlu bertele-tele, membuat kata-kata hampa yang membosankan.",
  ui_story_5035_50351201_19_dialog_content = "Kamu benar. Semua mantan kru saya mengalami kecelakaan yang tidak menguntungkan... Semua kecuali domba hitam pahlawan wanita saya, yang sekarang ada di sini.",
  ui_story_5035_50351201_20_dialog_content = "Apakah Anda tahu apa yang telah Anda lakukan? Kematian mereka akan menjadi film yang benar-benar mendebarkan.",
  ui_story_5035_50351201_21_dialog_content = "Berkat pelarian egois Anda, rekaman berharga menjadi sia-sia, dan begitu banyak nyawa.",
  ui_story_5035_50351201_22_dialog_content = "Kau... Kau...",
  ui_story_5035_50351201_23_dialog_content = "Jangan bicara begitu murah tentang yang hidup, dasar monster.",
  ui_story_5035_50351201_24_dialog_content = "Bagaimana Anda bisa membunuh mereka ...",
  ui_story_5035_50351201_25_dialog_content = "Bukan hanya Goldie... Seluruh kru...",
  ui_story_5035_50351201_26_dialog_content = "MENGAPA?!!",
  ui_story_5035_50351201_27_dialog_content = "Aku sudah memberitahumu. Mereka yang melihat terlalu banyak tidak dapat diizinkan untuk berbicara.",
  ui_story_5035_50351201_28_dialog_content = "Saya selalu menganggap layar perak sebagai hal yang ajaib.",
  ui_story_5035_50351201_29_dialog_content = "Melalui kekuatannya, orang dapat melihat diri mereka sendiri tercermin dan memahami kehidupan mereka. Bagaimanapun, seni meniru kehidupan.",
  ui_story_5035_50351201_30_dialog_content = "Bagi kami auteurs, itu adalah perisai yang sempurna.",
  ui_story_5035_50351201_31_dialog_content = "Dan saya ingin mempertahankan perisai ini. Saya tidak akan membiarkan rahasia saya bocor dari balik layar.",
  ui_story_5035_50351201_32_dialog_content = "Rahasia? Maksudmu seperti mengetahui tempat ini berhantu dan masih datang ke sini untuk memotret?!",
  ui_story_5035_50351201_33_dialog_content = "Ah, jadi itu menurutmu.",
  ui_story_5035_50351201_34_dialog_content = "Sangat bagus. Dan sebenarnya cukup dekat dengan kebenaran, meskipun Anda mendapatkan satu hal mendasar yang salah.",
  ui_story_5035_50351201_35_dialog_content = "Aku di sini bukan karena hantu.",
  ui_story_5035_50351201_36_dialog_content = "Hantu ada di sini karena aku.",
  ui_story_5035_50351201_37_dialog_content = "!!!",
  ui_story_5035_50351201_38_dialog_content = "Apa? Maksudnya apa...?",
  ui_story_5035_50351201_39_dialog_content = "Saya satu-satunya yang dapat membuat tempat ini mengungkapkan nilai sebenarnya.",
  ui_story_5035_50351201_40_dialog_content = "Karena tidak ada yang mengerti tempat ini lebih baik dari saya, dan tidak ada yang tahu <color=#FFB400>dia</color> lebih baik.",
  ui_story_5035_50351201_41_dialog_content = "Ketika saya masih muda, orang tua saya selalu memperingatkan saya untuk tidak terlalu penasaran dengan peta yang ditinggalkan leluhur keluarga.",
  ui_story_5035_50351201_42_dialog_content = "Tapi sungguh... Tempat ini, keberadaannya... Mereka mempesona.",
  ui_story_5035_50351201_43_dialog_content = "Kalau saja nenek moyang saya masih hidup! Dia akan tercengang dengan pekerjaanku!",
  ui_story_5035_50351201_44_dialog_content = "Jiwa wanita yang dia layani dengan sangat baik telah berlama-lama di sini selama berabad-abad.",
  ui_story_5035_50351201_45_dialog_content = "Saya membangunkan kesadarannya yang hilang, dan dia menghidupkan kembali inspirasi saya yang sekarat.",
  ui_story_5035_50351201_46_dialog_content = "Ya, kami saling menghidupkan kembali.",
  ui_story_5035_50351201_47_dialog_content = "Adapun Anda dan dua awak itu, Anda hanyalah produk dari percobaan awal saya.",
  ui_story_5035_50351201_48_dialog_content = "Lagi pula, saya belum melihat <color=#FFB400>dia</color> untuk waktu yang sangat lama.",
  ui_story_5035_50351201_49_dialog_content = "Kau…!",
  ui_story_5035_50351201_50_dialog_content = "Dia benar-benar menakjubkan. Manifestasi pertamanya melampaui harapan terliar saya.",
  ui_story_5035_50351201_51_dialog_content = "Jika Anda tidak menghancurkan salinan master dengan kecanggungan Anda yang menyedihkan, itu akan menjadi mahakarya yang akan membuat Umbraton terguncang.",
  ui_story_5035_50351201_52_dialog_content = "Dan itulah... mengapa kau membunuh orang yang tidak bersalah?",
  ui_story_5035_50351201_53_dialog_content = "Kamu terus syuting, terus merilis film horor... sepanjang hari kamu bisa bekerja dengan hantu ini?",
  ui_story_5035_50351201_54_dialog_content = "Terima kasih saya telah menghargai pekerjaan saya yang lebih biasa-biasa saja.",
  ui_story_5035_50351201_55_dialog_content = "Sebagai pecinta film horor, Anda harus tahu lebih baik dari yang lain bahwa penjahat lebih penting daripada pahlawan.",
  ui_story_5035_50351201_56_dialog_content = "Saya dapat melewati ratusan aktris, tetapi hanya ada satu <color=#FFB400>dia</color>.",
  ui_story_5035_50351201_57_dialog_content = "<color=#FFB400>Dia</color> adalah bintangku yang sebenarnya.",
  ui_story_5035_50351201_58_dialog_content = "Apakah maksudnya dia bepergian ke mana-mana menembak dengan hantu?!",
  ui_story_5035_50351201_59_dialog_content = "Ini gila.",
  ui_story_5035_50351201_60_dialog_content = "Ini menjadi lebih buruk.",
  ui_story_5035_50351201_61_dialog_content = "Karena cara yang sama digunakan untuk merekam beberapa film...",
  ui_story_5035_50351201_62_dialog_content = "Ada kru lain yang mati di tanganmu, kan?",
  ui_story_5035_50351201_63_dialog_content = "Oh benar! Jangan bilang mereka juga—",
  ui_story_5035_50351201_64_dialog_content = "Ck ck, Pak Produser. Aku tidak akan menanyakan itu jika aku jadi kamu.",
  ui_story_5035_50351201_65_dialog_content = "Sebenarnya, saya berharap saya tahu lebih sedikit, dan bahwa saya tidak memiliki mata atau telinga.",
  ui_story_5035_50351201_66_dialog_content = "Karena saya yakin Anda tahu apa artinya mendengar jawabannya.",
  ui_story_5035_50351201_67_dialog_content = "...",
  ui_story_5035_50351201_68_dialog_content = "Berhentilah menjadi begitu sok. Jawabannya sudah jelas sejak Anda muncul.",
  ui_story_5035_50351201_69_dialog_content = "Kami sama seperti kru lainnya. Kami tahu terlalu banyak rahasia Anda.",
  ui_story_5035_50351201_70_dialog_content = "Itulah sebabnya Anda menutup semua pintu.",
  ui_story_5035_50351201_71_dialog_content = "Anda tidak pernah bermaksud membiarkan siapa pun melarikan diri dari rumah berhantu.",
  ui_story_5035_50351201_72_dialog_content = "Oh, Tuan Produser, tidak perlu ada permusuhan seperti itu.",
  ui_story_5035_50351201_73_dialog_content = "Kami telah berbagi rahasia, bukan?",
  ui_story_5035_50351201_74_dialog_content = "Suka atau tidak, kita tampaknya berada di kapal yang sama.",
  ui_story_5035_50351201_75_dialog_content = "Izinkan saya untuk menyambut Anda semua.",
  ui_story_5035_50351201_76_dialog_content = "Selamat datang ke <color=#FFB400>awak kapal</color>!",
  ui_story_5035_50351201_77_dialog_content = "<color=#e8d9bb>Menetes</color>",
  ui_story_5035_50351201_78_dialog_content = "!!!",
  ui_story_5035_50351201_79_dialog_content = "Bisakah kalian mendengar itu? Kedengarannya seperti air yang menetes.",
  ui_story_5035_50351201_80_dialog_content = "<color=#e8d9bb>Menetes</color>",
  ui_story_5035_50351201_81_dialog_content = "Itu... Ini semakin dekat.",
  ui_story_5035_50351201_82_dialog_content = "Ya, tapi apa itu?!",
  ui_story_5035_50351201_83_dialog_content = "Tunggu! Kamera!",
  ui_story_5035_50351201_84_dialog_content = "Cepat, Lilica, angkat kameranya!",
  ui_story_5035_50351201_85_dialog_content = "Apa?",
  ui_story_5035_50351201_86_dialog_content = "Film lurus ke depan! Buru-buru!",
  ui_story_5035_50351201_87_dialog_content = "Oh baiklah!",
  ui_story_5035_50351201_88_dialog_content = "Merekam... Mengarahkan kamera...",
  ui_story_5035_50351201_89_dialog_content = "!!!",
  ui_story_5035_50351201_90_dialog_content = "G-teman, lihat!",
  ui_story_5035_50351201_91_dialog_content = "Itu di sana...",
  ui_story_5035_50351201_92_dialog_content = "Ahhhh!",
  ui_story_5035_50351201_93_dialog_content = "Apa? Apa itu? Apa yang kamu lihat?",
  ui_story_5035_50351201_94_dialog_content = "Ini dia datang, ini dia...",
  ui_story_5035_50351201_95_dialog_content = "Bagaimana ini mungkin... Aku sangat bingung.",
  ui_story_5035_50351201_96_dialog_content = "Apakah dia akan membunuh kita...?",
  ui_story_5035_50351201_97_dialog_content = "Jangan hanya berdiri di sana! Lari!",
  ui_story_5035_50351201_98_dialog_content = "Lari... Ya! Mari kita pergi dari sini!",
  ui_story_5035_50351201_99_dialog_content = "Tetap dekat denganku. Ayo naik ke lantai atas!",
  ui_story_5035_50351201_100_dialog_content = "<color=#e8d9bb>Pit... Pat... Pit... Pat...</color>",
  ui_story_5035_50351201_101_dialog_content = "Jalankan, jalankan semua yang Anda inginkan. Tapi pintu keluarnya tidak di sana.",
  ui_story_5035_50351201_102_dialog_content = "Di mana tepatnya Anda pikir Anda akan lari, jika Anda bahkan tidak bisa keluar dari rumah besar ini?",
  ui_story_5035_50351201_103_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5035_50351201_104_dialog_content = "Graaaah!!",
  ui_story_5035_50351201_105_dialog_content = "Grr...",
  ui_story_5035_50351201_106_dialog_content = "Apa, LEBIH EKlipsites?! Dan itu harus sekarang!",
  ui_story_5035_50351201_107_dialog_content = "Sepertinya semua Eclipsites yang tidak aktif di rumah telah datang. Saya tidak tahu apakah ini perbuatan Jonny juga.",
  ui_story_5035_50351201_108_dialog_content = "Bahkan jika kamu benar, dan kita sedang membicarakan semua Eclipsites di mansion...",
  ui_story_5035_50351201_109_dialog_content = "Bukankah masih terlalu banyak Eclipsites, Minos?",
  ui_story_5035_50351201_110_dialog_content = "Biasanya tidak sebanyak ini.",
  ui_story_5035_50351201_111_dialog_content = "Menurut saya PlayerName's benar, dan penampilan mereka entah bagaimana terkait dengan Jonny.",
  ui_story_5035_50351201_112_dialog_content = "Ini adalah metode yang jauh lebih baik untuk mengeluarkan seluruh kru daripada menyuruh Nyonya Putih memburu mereka satu per satu.",
  ui_story_5035_50351201_113_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5035_50351201_114_dialog_content = "Jangan mencoba melawan mereka! Cepat, belok ke sini!",
  ui_story_5035_50351201_115_dialog_content = "*Huff* Berapa lama kita akan berlari, tepatnya?",
  ui_story_5035_50351201_116_dialog_content = "Kita harus kehilangan mereka, pertama dan terutama.",
  ui_story_5035_50351201_117_dialog_content = "Tunggu! Di depan! Lihat lurus ke depan!",
  ui_story_5035_50351201_118_dialog_content = "Ada apa?",
  ui_story_5035_50351201_119_dialog_content = "Saya pikir saya melihat dua gadis kecil di koridor!",
  ui_story_5035_50351201_120_dialog_content = "Gadis kecil? Siapa...?",
  ui_story_5035_50351201_121_dialog_content = "anak anjing... anak anjing...",
  ui_story_5035_50351201_122_dialog_content = "Kami telah menemukan Anda!",
  ui_story_5035_50351201_123_dialog_content = "Anak anjing? Tapi tak satu pun dari kita disebut Puppy...?",
  ui_story_5035_50351201_124_dialog_content = "Apakah maksud mereka...",
  ui_story_5035_50351201_125_dialog_content = "Disini! Cepat! Kami di sini!",
  ui_story_5035_50351201_126_dialog_content = "Ayo main game, Puppy.",
  ui_story_5035_50351201_127_dialog_content = "Anda menang jika Anda bisa mencapai akhir sebelum kita menghitung sampai sepuluh.",
  ui_story_5035_50351201_128_dialog_content = "Ayo, Anjing. Pergi untuk garis finish!",
  ui_story_5035_50351201_129_dialog_content = "Ayo, cari rute lain! Saya tidak berpikir kita harus terus maju di sini ...",
  ui_story_5035_50351201_130_dialog_content = "The Eclipsites sedang mengejar! Cepat, lari!",
  ui_story_5035_50351201_131_dialog_content = "Tapi di depan...",
  ui_story_5035_50351201_132_dialog_content = "Ya! Itu saja, Puppy.",
  ui_story_5035_50351201_133_dialog_content = "Kita sudah setengah jalan... Kamu harus lebih cepat!",
  ui_story_5035_50351201_134_dialog_content = "Hei, apa yang kalian berdua lakukan di sini? Patty, Patty?!",
  ui_story_5035_50351201_135_dialog_content = "Patty menyukai rumah berhantu.",
  ui_story_5035_50351201_136_dialog_content = "Patsy juga!",
  ui_story_5035_50351201_137_dialog_content = "Itu sebabnya kami ingin datang berkunjung.",
  ui_story_5035_50351201_138_dialog_content = "Baiklah, tapi aku khawatir tidak ada waktu untuk bermain denganmu sekarang.",
  ui_story_5035_50351201_139_dialog_content = "Pegang tanganku!",
  ui_story_5035_50351201_140_dialog_content = "Saya ingin kiri.",
  ui_story_5035_50351201_141_dialog_content = "Jadi saya akan mengambil hak.",
  ui_story_5035_50351201_142_dialog_content = "Lari!!",
  ui_story_5035_50351302_1_dialog_content = "Graaaah!!",
  ui_story_5035_50351302_2_dialog_content = "hai!",
  ui_story_5035_50351302_3_dialog_content = "<color=#e8d9bb>Menghancurkan! Memukul! salah!</color>",
  ui_story_5035_50351302_4_dialog_content = "Hmph, hanya itu?",
  ui_story_5035_50351302_5_dialog_content = "Sungguh salahmu menganggapku hanya seorang thespian! Bagi diri saya yang suka berpetualang, orang-orang ini hanyalah pejalan kaki.",
  ui_story_5035_50351302_6_dialog_content = "Kerja bagus, Sadi! Kami mengurus semua Eclipsites yang mengejar kami!",
  ui_story_5035_50351302_7_dialog_content = "Selanjutnya... Hah?",
  ui_story_5035_50351302_8_dialog_content = "Di mana orang lain?",
  ui_story_5035_50351302_9_dialog_content = "Hah?",
  ui_story_5035_50351302_10_dialog_content = "Aku hanya mengikutimu. Apakah Anda tidak mengikuti seseorang?",
  ui_story_5035_50351302_11_dialog_content = "Tapi aku... aku mengikutimu!",
  ui_story_5035_50351302_12_dialog_content = "...",
  ui_story_5035_50351302_13_dialog_content = "<color=#e8d9bb>Acak, acak ...</color>",
  ui_story_5035_50351302_14_dialog_content = "Sunyi sekali…",
  ui_story_5035_50351302_15_dialog_content = "Sst! Tetap tenang.",
  ui_story_5035_50351302_16_dialog_content = "Semakin tenang, semakin mudah untuk mendengar kita.",
  ui_story_5035_50351302_17_dialog_content = "Mungkin tempat ini sudah aman?",
  ui_story_5035_50351302_18_dialog_content = "Tidak ada Eclipsites, dan tidak ada hantu dengan suara tetesan airnya yang menyeramkan.",
  ui_story_5035_50351302_19_dialog_content = "Siapa tahu? Mungkin ada sesuatu yang menunggu kita di sudut itu.",
  ui_story_5035_50351302_20_dialog_content = "Jangan coba-coba menakutiku. Aku punya nyali dalam sekop.",
  ui_story_5035_50351302_21_dialog_content = "Tapi, sekarang setelah kamu menyebutkannya... Bukankah ide yang baik bagi kita untuk berhenti berkeliaran tanpa tujuan?",
  ui_story_5035_50351302_22_dialog_content = "Bagaimana jika kita menemukan segerombolan Eclipsites itu, atau bahkan⁠—",
  ui_story_5035_50351302_23_dialog_content = "Saya tidak berpikir kita bisa melakukan ini sendiri.",
  ui_story_5035_50351302_24_dialog_content = "... Saya kira Anda benar.",
  ui_story_5035_50351302_25_dialog_content = "Bagaimana kalau kita menemukan ruangan untuk bersembunyi?",
  ui_story_5035_50351302_26_dialog_content = "Lihat! Saya pikir kita bisa membuka pintu di sana!",
  ui_story_5035_50351302_27_dialog_content = "Sst! Diam-diam...",
  ui_story_5035_50351302_28_dialog_content = "<color=#e8d9bb>*Kriek*</color>",
  ui_story_5035_50351302_29_dialog_content = "Bisakah kita menguncinya?",
  ui_story_5035_50351302_30_dialog_content = "Biarkan aku melihat... Oh! Saya pikir kita bisa!",
  ui_story_5035_50351302_31_dialog_content = "Lebih baik menguncinya dengan cepat.",
  ui_story_5035_50351302_32_dialog_content = "Mm-hmm!",
  ui_story_5035_50351302_33_dialog_content = "<color=#e8d9bb>Bang</color>",
  ui_story_5035_50351302_34_dialog_content = "*Huff*—Ayo... Aku mengerti, aku mengerti.",
  ui_story_5035_50351302_35_dialog_content = "Fiuh…",
  ui_story_5035_50351302_36_dialog_content = "Setidaknya kita akhirnya bisa bernapas! Aku takut setengah mati.",
  ui_story_5035_50351302_37_dialog_content = "Mari kita beristirahat di sini sebentar. Kita bisa bergabung kembali dengan yang lain segera setelah kita mendengar gerakan mereka.",
  ui_story_5035_50351302_38_dialog_content = "Ya, mari kita istirahat.",
  ui_story_5035_50351302_39_dialog_content = "Namun…",
  ui_story_5035_50351302_40_dialog_content = "Bukankah sesuatu tentang ruangan ini terlihat familiar?",
  ui_story_5035_50351302_41_dialog_content = "Hmm?",
  ui_story_5035_50351302_42_dialog_content = "Itu benar! Bukankah ini ruang pamer?",
  ui_story_5035_50351302_43_dialog_content = "Bagaimana kita bisa kembali ke sini...?",
  ui_story_5035_50351302_44_dialog_content = "Jika saya ingat benar, bukankah showroom tempat kami pertama kali mendengar tetesan air?",
  ui_story_5035_50351302_45_dialog_content = "Umm... Tolong jangan katakan hal seperti itu. Bagaimana saya dimaksudkan untuk beristirahat sekarang?",
  ui_story_5035_50351302_46_dialog_content = "Pikirkan hal lain, alihkan pikiran Anda.",
  ui_story_5035_50351302_47_dialog_content = "Saya tahu, mari rekam video di sini sebagai kenang-kenangan!",
  ui_story_5035_50351302_48_dialog_content = "Sekarang?? Anda benar-benar memiliki bakat untuk memilih waktu yang salah ...",
  ui_story_5035_50351302_49_dialog_content = "Tidak pernah ada waktu yang salah! Kamera dimaksudkan untuk mendokumentasikan semua jenis momen!",
  ui_story_5035_50351302_50_dialog_content = "Apakah Anda senang atau takut, semuanya layak untuk direkam.",
  ui_story_5035_50351302_51_dialog_content = "Lagi pula, kamera bisa menangkap jejak White Lady. Bukankah itu lebih baik daripada tidak melihat sama sekali?",
  ui_story_5035_50351302_52_dialog_content = "Yah, itu memang benar...",
  ui_story_5035_50351302_53_dialog_content = "<color=#e8d9bb>Memotong-!</color>",
  ui_story_5035_50351302_54_dialog_content = "Ahhhh!!!",
  ui_story_5035_50351302_55_dialog_content = "...?! Apa yang terjadi?",
  ui_story_5035_50351302_56_dialog_content = "Pintu! Sesuatu hanya...",
  ui_story_5035_50351302_57_dialog_content = "<color=#e8d9bb>Memotong-!</color>",
  ui_story_5035_50351302_58_dialog_content = "Pintunya sedang terbelah!",
  ui_story_5035_50351302_59_dialog_content = "<color=#e8d9bb>Memotong-!</color>",
  ui_story_5035_50351302_60_dialog_content = "Siapa di sana?!",
  ui_story_5035_50351302_61_dialog_content = "Lilica dan Sadie? Ahahaha, penemuan yang sangat bermanfaat!",
  ui_story_5035_50351302_62_dialog_content = "Ayo, wanita terkemuka saya! Pemotretan akan segera dimulai.",
  ui_story_5035_50351302_63_dialog_content = "Direktur Joni?!",
  ui_story_5035_50351302_64_dialog_content = "Aku memperingatkanmu! Tetap kembali!",
  ui_story_5035_50351302_65_dialog_content = "Ancaman? Ooh, sulit, kan?",
  ui_story_5035_50351302_66_dialog_content = "Sekarang aku semakin penasaran.",
  ui_story_5035_50351302_67_dialog_content = "Misalkan saya tidak tinggal kembali ... Apa sebenarnya yang akan Anda lakukan?",
  ui_story_5035_50351302_68_dialog_content = "APA sebenarnya yang akan kamu LAKUKAN PADAKU?!!",
  ui_story_5035_50351302_69_dialog_content = "<color=#e8d9bb>Memotong-!</color>",
  ui_story_5035_50351302_70_dialog_content = "Ahhhh!",
  ui_story_5035_50351302_71_dialog_content = "Joni! Saya telah menangkap semua ini di kamera!",
  ui_story_5035_50351302_72_dialog_content = "Anda tahu apa yang akan terjadi jika ini keluar? Berhentilah selagi kamu masih bisa!",
  ui_story_5035_50351302_73_dialog_content = "Anda mendapatkannya di tape?",
  ui_story_5035_50351302_74_dialog_content = "Luar biasa, benar-benar luar biasa! Kamu sangat berbakat, Lilica, sangat tajam.",
  ui_story_5035_50351302_75_dialog_content = "Tapi rekaman ini tidak akan keluar. Bahkan, saya akan mengedit bagian-bagiannya menjadi film!",
  ui_story_5035_50351302_76_dialog_content = "Ini akan membuat film menjadi lebih sempurna.",
  ui_story_5035_50351302_77_dialog_content = "Kau... Kau...",
  ui_story_5035_50351302_78_dialog_content = "Lagi pula...",
  ui_story_5035_50351302_79_dialog_content = "Siapa yang bisa percaya bahwa film itu nyata?",
  ui_story_5035_50351302_80_dialog_content = "<color=#e8d9bb>Memotong-!</color>",
  ui_story_5035_50351302_81_dialog_content = "Ahh!",
  ui_story_5035_50351302_82_dialog_content = "Ahhh!",
  ui_story_5035_50351302_83_dialog_content = "Ya! Itu dia! Terus berlanjut!",
  ui_story_5035_50351302_84_dialog_content = "Jangan biarkan teriakan itu berhenti!",
  ui_story_5035_50351302_85_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5035_50351302_86_dialog_content = "AHHHHH!",
  ui_story_5035_50351302_87_dialog_content = "Sekali lagi harus melakukan trik.",
  ui_story_5035_50351302_88_dialog_content = "Hahaha... Hahahaha!!",
  ui_story_5035_50351302_89_dialog_content = "Ahhhhhhh!",
  ui_story_5035_50351302_90_dialog_content = "?!",
  ui_story_5035_50351302_91_dialog_content = "Hah?",
  ui_story_5035_50351302_92_dialog_content = "Oh, itu datang dari sana.",
  ui_story_5035_50351302_93_dialog_content = "Ini mulai, itu mulai!",
  ui_story_5035_50351302_94_dialog_content = "Oh tidak tidak tidak! Kameranya bahkan tidak berputar.",
  ui_story_5035_50351302_95_dialog_content = "Tidak, tidak, tidak, saya tidak melewatkan satu tembakan pun, sama sekali tidak...",
  ui_story_5035_50351302_96_dialog_content = "Huff.. sip..",
  ui_story_5035_50351302_97_dialog_content = "Huff.. sip..",
  ui_story_5035_50351302_98_dialog_content = "Dia pergi?",
  ui_story_5035_50351302_99_dialog_content = "S-sepertinya begitu.",
  ui_story_5035_50351302_100_dialog_content = "Aku tidak yakin apa yang baru saja terjadi, tapi... apa kau mendengar suara itu?",
  ui_story_5035_50351302_101_dialog_content = "Ya. Aku hanya memikirkannya. Kedengarannya agak jauh, mungkin dari lantai bawah di suatu tempat.",
  ui_story_5035_50351302_102_dialog_content = "Dan bukankah itu... terdengar agak familiar?",
  ui_story_5035_50351302_103_dialog_content = "Ya! Kedengarannya agak seperti PlayerName.",
  ui_story_5035_50351401_1_dialog_content = "<color=#e8d9bb>Tiga Menit Yang Lalu</color>",
  ui_story_5035_50351401_2_dialog_content = "Fiuh, akhirnya kehilangan Eclipsites. Apakah semua orang baik-baik saja?",
  ui_story_5035_50351401_3_dialog_content = "Masih utuh. Meskipun sepertinya kita kehilangan lebih dari sekedar Eclipsites.",
  ui_story_5035_50351401_4_dialog_content = "Hah?",
  ui_story_5035_50351401_5_dialog_content = "Kamu benar! Dimana Lilica dan Sadie?!",
  ui_story_5035_50351401_6_dialog_content = "Kita pasti terpisah dalam semua kekacauan. Saya tidak tahu di mana mereka bisa berada sekarang.",
  ui_story_5035_50351401_7_dialog_content = "Ini buruk. Keduanya bukan yang terbaik untuk menangani masalah. Kita harus kembali untuk mereka!",
  ui_story_5035_50351401_8_dialog_content = "Mereka mungkin masih di lantai dua.",
  ui_story_5035_50351401_9_dialog_content = "Bisakah Anda mencari mereka dengan kemampuan psikis Anda, PlayerName?",
  ui_story_5035_50351401_10_dialog_content = "aku sedang mengerjakannya...",
  ui_story_5035_50351401_11_dialog_content = "Tunggu!",
  ui_story_5035_50351401_12_dialog_content = "Hah? Apa?",
  ui_story_5035_50351401_13_dialog_content = "Ketika kita pertama kali sampai di sini... apakah itu di koridor?",
  ui_story_5035_50351401_14_dialog_content = "Kapan muncul?!",
  ui_story_5035_50351401_15_dialog_content = "Kami tidak mungkin melewatkan sesuatu yang besar.",
  ui_story_5035_50351401_16_dialog_content = "Oh tidak, tidak! Patty belum pernah melihatnya.",
  ui_story_5035_50351401_17_dialog_content = "Apa ini? Peti mati?",
  ui_story_5035_50351401_18_dialog_content = "Oh ya, bukankah ini baru saja disampaikan oleh kru?",
  ui_story_5035_50351401_19_dialog_content = "Tapi siapa yang memindahkannya ke sini?",
  ui_story_5035_50351401_20_dialog_content = "Tidak masalah. Mari kita lupakan saja untuk saat ini. Menemukan Lilica dan Sadie lebih penting.",
  ui_story_5035_50351401_21_dialog_content = "Mari kita berkeliling saja.",
  ui_story_5035_50351401_22_dialog_content = "Ah iya. Hanya pergi sekitar.",
  ui_story_5035_50351401_23_dialog_content = "Memimpin, PlayerName.",
  ui_story_5035_50351401_24_dialog_content = "M-aku?",
  ui_story_5035_50351401_25_dialog_content = "Mmhmm!",
  ui_story_5035_50351401_26_dialog_content = "Namun…",
  ui_story_5035_50351401_27_dialog_content = "Oke, baiklah! Aku pergi dulu! Itu hanya penyangga. Apa yang harus ditakuti?",
  ui_story_5035_50351401_28_dialog_content = "Cobalah untuk mengikuti! Semakin cepat kita menemukan⁠—",
  ui_story_5035_50351401_29_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5035_50351401_30_dialog_content = "Ahhhh—!",
  ui_story_5035_50351401_31_dialog_content = "Hah?",
  ui_story_5035_50351401_32_dialog_content = "Oh, itu datang dari sana.",
  ui_story_5035_50351401_33_dialog_content = "Suara itu! Itu-itu datang dari dalam peti mati!",
  ui_story_5035_50351401_34_dialog_content = "Aku juga mendengarnya!",
  ui_story_5035_50351401_35_dialog_content = "Apakah Anda yakin itu hanya alat bantu?",
  ui_story_5035_50351401_36_dialog_content = "*Hiks*",
  ui_story_5035_50351401_37_dialog_content = "Tolong... Hantu...",
  ui_story_5035_50351401_38_dialog_content = "Apa yang akan kita lakukan? Kita tidak bisa begitu saja berjalan ke sana!",
  ui_story_5035_50351401_39_dialog_content = "Haruskah kita menemukan rute yang berbeda? Meskipun, membalikkan punggung kita sedikit ...",
  ui_story_5035_50351401_40_dialog_content = "Mungkin yang terbaik adalah memeriksa ulang.",
  ui_story_5035_50351401_41_dialog_content = "Aku akan membukanya.",
  ui_story_5035_50351401_42_dialog_content = "Buka peti mati?!",
  ui_story_5035_50351401_43_dialog_content = "Paling tidak, kita akan tahu apa yang kita hadapi.",
  ui_story_5035_50351401_44_dialog_content = "Hati-hati...",
  ui_story_5035_50351401_45_dialog_content = "Itu akan baik-baik saja.",
  ui_story_5035_50351401_46_dialog_content = "Aku siap.",
  ui_story_5035_50351401_47_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5035_50351401_48_dialog_content = "Hanya sedikit lebih dekat...",
  ui_story_5035_50351401_49_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5035_50351401_50_dialog_content = "Sedikit lagi...",
  ui_story_5035_50351401_51_dialog_content = "<color=#e8d9bb>Bam, bam!</color>",
  ui_story_5035_50351401_52_dialog_content = "...",
  ui_story_5035_50351401_53_dialog_content = "<color=#e8d9bb>BAM BAM BAM BAM!!!</color>",
  ui_story_5035_50351401_54_dialog_content = "Hiss.. Huh…",
  ui_story_5035_50351401_55_dialog_content = "Suaranya sangat keras! Itu bisa merasakan kita mendekat!",
  ui_story_5035_50351401_56_dialog_content = "Kembali!",
  ui_story_5035_50351401_57_dialog_content = "Saya minta maaf, tapi saya tidak bisa melangkah lebih jauh.",
  ui_story_5035_50351401_58_dialog_content = "Hah?",
  ui_story_5035_50351401_59_dialog_content = "Ada sesuatu di sana. Sesuatu yang bisa membunuhku.",
  ui_story_5035_50351401_60_dialog_content = "Aku tahu itu. Ini bukan penyangga, tapi peti mati yang nyata...",
  ui_story_5035_50351401_61_dialog_content = "Ada apa dengan semua hal tidak masuk akal yang terjadi hari ini??",
  ui_story_5035_50351401_62_dialog_content = "Benar, mari kita ubah rute dan jauhi itu.",
  ui_story_5035_50351401_63_dialog_content = "Apakah ada jalan keluar lain?",
  ui_story_5035_50351401_64_dialog_content = "Melihat itu muncul begitu saja di sini entah dari mana, tidak bisakah itu muncul di tempat lain juga?",
  ui_story_5035_50351401_65_dialog_content = "Jadi apa yang Anda katakan adalah ...",
  ui_story_5035_50351401_66_dialog_content = "Kita harus membukanya. Semua orang, bersama.",
  ui_story_5035_50351401_67_dialog_content = "Apakah kita serius melakukan ini?",
  ui_story_5035_50351401_68_dialog_content = "Lebih aman untuk mengetahui apa yang kita hadapi daripada membiarkannya menunggu kita dalam kegelapan.",
  ui_story_5035_50351401_69_dialog_content = "Bagaimana menurutmu?",
  ui_story_5035_50351401_70_dialog_content = "Kamu tidak salah...",
  ui_story_5035_50351401_71_dialog_content = "Aku... aku takut, tapi...",
  ui_story_5035_50351401_72_dialog_content = "Aku benar-benar ingin tahu apa yang ada di sana...",
  ui_story_5035_50351401_73_dialog_content = "*Hiks*",
  ui_story_5035_50351401_74_dialog_content = "Oke, ayo pergi! Semua orang, pada saat yang sama!",
  ui_story_5035_50351401_75_dialog_content = "Ini hanya sedikit bahaya maut. Tidak ada yang belum pernah kita hadapi sebelumnya!",
  ui_story_5035_50351401_76_dialog_content = "Betul sekali! Tidak ada yang perlu ditakuti, tidak ada sama sekali...",
  ui_story_5035_50351401_77_dialog_content = "Baik. Sekarang, tetap fokus dan tetap dekat.",
  ui_story_5035_50351401_78_dialog_content = "Bersiaplah untuk menanggapi apa pun yang terjadi pada saat itu juga.",
  ui_story_5035_50351401_79_dialog_content = "Semua bersama-sama sekarang, maju ...",
  ui_story_5035_50351401_80_dialog_content = "Berhenti! Berhenti di sana!",
  ui_story_5035_50351401_81_dialog_content = "Hah?",
  ui_story_5035_50351401_82_dialog_content = "Direktur Joni?!",
  ui_story_5035_50351401_83_dialog_content = "Jangan bergerak! Beri aku waktu, tolong, aku mohon!",
  ui_story_5035_50351401_84_dialog_content = "Tidak mungkin bidikan ini dapat direproduksi! Saya tidak bisa melewatkan kesempatan ini.",
  ui_story_5035_50351401_85_dialog_content = "Satu menit! Hanya 60 detik singkat. Percayalah padaku! Bagaimanapun, saya seorang profesional.",
  ui_story_5035_50351401_86_dialog_content = "A-apa maksudmu dengan itu?",
  ui_story_5035_50351401_87_dialog_content = "Apa yang kamu lakukan sekarang, Jonny?",
  ui_story_5035_50351401_88_dialog_content = "JUGA!!! Apa sebenarnya peti mati ini?",
  ui_story_5035_50351401_89_dialog_content = "Petir. Saya ingin cahaya dari sudut ini.",
  ui_story_5035_50351401_90_dialog_content = "Dekatkan kamera...",
  ui_story_5035_50351401_91_dialog_content = "Di sana! Itu benar.",
  ui_story_5035_50351401_92_dialog_content = "Dan akhirnya, mikrofon! Sial, tombolnya macet lagi!",
  ui_story_5035_50351401_93_dialog_content = "Anda akan langsung ke tumpukan sampah besok, sobat.",
  ui_story_5035_50351401_94_dialog_content = "Di mana pengawas naskah? NASKAH!!",
  ui_story_5035_50351401_95_dialog_content = "Lupakan. Aku akan melakukannya sendiri.",
  ui_story_5035_50351401_96_dialog_content = "Hanya satu detik lebih lama sekarang. Ini dia!",
  ui_story_5035_50351401_97_dialog_content = "Aku harus menyalakannya. Astor sangat menyukai baunya yang terbakar.",
  ui_story_5035_50351401_98_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5035_50351401_99_dialog_content = "Baiklah, pemeran! Maaf telah membuatmu menunggu.",
  ui_story_5035_50351401_100_dialog_content = "Sekarang, kita akan menembak akhir yang mendebarkan dari One Cut of Screams!",
  ui_story_5035_50351401_101_dialog_content = "Saya percaya bahwa adegan ini akan menyempurnakan film saya, sebuah karya yang sangat artistik namun memiliki bobot komersial yang nyata, dan akan membuat karir semua orang di ruangan ini!",
  ui_story_5035_50351401_102_dialog_content = "Saya merasa terhormat telah mendapat kehormatan bekerja dengan Anda semua, dan <color=#FFB400>Astor</color>, pada karya visioner ini.",
  ui_story_5035_50351401_103_dialog_content = "Astor?",
  ui_story_5035_50351401_104_dialog_content = "Oh tidak, bukan nama itu lagi...",
  ui_story_5035_50351401_105_dialog_content = "Jadi, tanpa basa-basi lagi...",
  ui_story_5035_50351401_106_dialog_content = "Persiapkan dirimu untuk bertemu denganku <color=#FFB400>wanita terkemuka</color>!",
  ui_story_5035_50351401_107_dialog_content = "Wanita terkemuka?!!",
  ui_story_5035_50351401_108_dialog_content = "Aksi terakhir One Cut of Screams, adegan satu, ambil satu —",
  ui_story_5035_50351401_109_dialog_content = "TINDAKAN!",
  ui_story_5035_50351401_110_dialog_content = "<color=#e8d9bb>Ding... Ding...</color>",
  ui_story_5035_50351401_111_dialog_content = "Ahhhhhhhh!!!!!!",
  ui_story_5035_50351401_112_dialog_content = "Peti mati! Lonceng di peti mati berdering!",
  ui_story_5035_50351401_113_dialog_content = "<color=#e8d9bb>Der, der!</color>",
  ui_story_5035_50351401_114_dialog_content = "Aneh. Tidak ada yang mendekatinya kali ini ...",
  ui_story_5035_50351401_115_dialog_content = "<color=#e8d9bb>Bang, bang — Bang, bang!</color>",
  ui_story_5035_50351401_116_dialog_content = "AHHH!!!!",
  ui_story_5035_50351401_117_dialog_content = "Tutup! Tutup peti mati adalah ...",
  ui_story_5035_50351401_118_dialog_content = "<color=#e8d9bb>BANG—!!</color>",
  ui_story_5035_50351401_119_dialog_content = "*Uhuk uhuk*",
  ui_story_5035_50351401_120_dialog_content = "Ada yang keluar!",
  ui_story_5035_50351401_121_dialog_content = "A-apa itu?",
  ui_story_5035_50351401_122_dialog_content = "Ini... SS-Dia...",
  ui_story_5035_50351401_123_dialog_content = "Wanita Putih yang muncul di belakang kita saat itu...",
  ui_story_5035_50351401_124_dialog_content = "Dia <color=#FFB400>Astor</color>!",
  ui_story_5035_50351401_125_dialog_content = "*Meraung*",
  ui_story_5035_50351401_126_dialog_content = "Ini mengingatkan saya pada adegan dari film Jonny lainnya.",
  ui_story_5035_50351401_127_dialog_content = "adegan apa?",
  ui_story_5035_50351401_128_dialog_content = "Monster memanjat keluar dari peti mati, hanya untuk menyeret seseorang ke dalamnya.",
  ui_story_5035_50351401_129_dialog_content = "Kemudian tutup peti mati ditutup dengan bunyi dentingan terakhir yang mengerikan.",
  ui_story_5035_50351401_130_dialog_content = "Akhirnya, percikan darah memerciki lensa kamera, dan \"The End\" muncul di layar di tengah semua warna merah tua.",
  ui_story_5035_50351401_131_dialog_content = "Ditarik ke peti mati...",
  ui_story_5035_50351401_132_dialog_content = "Tunggu, apakah itu berarti kita...",
  ui_story_5035_50351401_133_dialog_content = "Syuting jenis adegan yang sama?!",
  ui_story_5035_50351401_134_dialog_content = "Dia, dia datang!",
  ui_story_5035_50351401_135_dialog_content = "Grrraarrr!!",
  ui_story_5035_50351401_136_dialog_content = "Dia datang! Cepat, lari! LARI!",
  ui_story_5035_50351401_137_dialog_content = "Graar!!",
  ui_story_5035_50351401_138_dialog_content = "Dia mengejar!",
  ui_story_5035_50351401_139_dialog_content = "Betapa dekat?",
  ui_story_5035_50351401_140_dialog_content = "Aku tidak tahu! Aku tidak melihat ke belakang!",
  ui_story_5035_50351401_141_dialog_content = "Eww, apa bau.",
  ui_story_5035_50351401_142_dialog_content = "Patsy akan pingsan.",
  ui_story_5035_50351401_143_dialog_content = "Oh tidak! Jika kita terus berjalan ke arah ini...",
  ui_story_5035_50351401_144_dialog_content = "Apa?",
  ui_story_5035_50351401_145_dialog_content = "Jika Jonny mengunci pintu di depan, maka ini adalah jalan buntu.",
  ui_story_5035_50351401_146_dialog_content = "APA?! Jadi apa yang kita lakukan sekarang?!",
  ui_story_5035_50351401_147_dialog_content = "Kembali dan temukan rute yang berbeda.",
  ui_story_5035_50351401_148_dialog_content = "Graar!!",
  ui_story_5035_50351401_149_dialog_content = "Sepertinya dia bukan penggemarnya!",
  ui_story_5035_50351401_150_dialog_content = "Maka satu-satunya pilihan kita adalah menerobos pintu di ujung koridor.",
  ui_story_5035_50351401_151_dialog_content = "Tidak apa-apa, tidak terlalu sulit untuk mendobrak pintu!",
  ui_story_5035_50351401_152_dialog_content = "Ini tidak begitu sederhana. Saya memperkuat semua pintu di rumah hantu agar tahan terhadap Luminatics.",
  ui_story_5035_50351401_153_dialog_content = "Diperkuat?! Mengapa Anda memilih untuk melakukan sesuatu yang sama sekali tidak perlu?!",
  ui_story_5035_50351401_154_dialog_content = "Yah, saya pikir beberapa tamu bisa bereaksi berlebihan dan merusak gedung.",
  ui_story_5035_50351401_155_dialog_content = "Saya tidak pernah berharap perlu menghancurkannya sendiri.",
  ui_story_5035_50351401_156_dialog_content = "Jadi tidak ada yang bisa kita lakukan?!",
  ui_story_5035_50351401_157_dialog_content = "Jangan khawatir! Bahkan jika pintunya keras, kita bisa menghancurkan dinding di sebelahnya.",
  ui_story_5035_50351401_158_dialog_content = "Betul sekali! Anda tidak memperkuat dinding, kan?",
  ui_story_5035_50351401_159_dialog_content = "Tidak. Tapi mereka cukup solid dalam dirinya sendiri, dan memecahkannya mungkin membutuhkan waktu.",
  ui_story_5035_50351401_160_dialog_content = "Satu hal yang tidak kita miliki adalah waktu...",
  ui_story_5035_50351401_161_dialog_content = "Ini adalah dinding.",
  ui_story_5035_50351401_162_dialog_content = "Mari kita berikan semua yang kita punya.",
  ui_story_5035_50351401_163_dialog_content = "Siap!",
  ui_story_5035_50351401_164_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5035_50351401_165_dialog_content = "Lubang!",
  ui_story_5035_50351401_166_dialog_content = "Anda sebaiknya mengambil langkah sedikit!",
  ui_story_5035_50351401_167_dialog_content = "Dia benar-benar dekat...",
  ui_story_5035_50351401_168_dialog_content = "(Dan di belakangnya adalah... Jonny?)",
  ui_story_5035_50351401_169_dialog_content = "...",
  ui_story_5035_50351401_170_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5035_50351401_171_dialog_content = "Hampir sampai!",
  ui_story_5035_50351401_172_dialog_content = "Graar!!",
  ui_story_5035_50351401_173_dialog_content = "Ayo cepat! Dia tepat di atasku!",
  ui_story_5035_50351401_174_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5035_50351401_175_dialog_content = "Kami mengerti! Semuanya, lewati dengan cepat!",
  ui_story_5035_50351401_176_dialog_content = "PlayerName, Ayo pergi!",
  ui_story_5035_50351401_177_dialog_content = "Baiklah, baiklah!",
  ui_story_5035_50351401_178_dialog_content = "Kita bisa mencapai lantai dua di depan! Kami akan memiliki lebih banyak ruang di sana untuk bergerak.",
  ui_story_5035_50351401_179_dialog_content = "Besar! Sekarang⁠—",
  ui_story_5035_50351401_180_dialog_content = "AHHH!",
  ui_story_5035_50351401_181_dialog_content = "Vice? Kau baik-baik saja?",
  ui_story_5035_50351401_182_dialog_content = "Sesuatu... Sesuatu menarikku...",
  ui_story_5035_50351401_183_dialog_content = "!!!",
  ui_story_5035_50351401_184_dialog_content = "Dia punya Wakil!",
  ui_story_5035_50351401_185_dialog_content = "Peti mati bodoh, lepaskan dia!",
  ui_story_5035_50351401_186_dialog_content = "Biar saya bantu...",
  ui_story_5035_50351401_187_dialog_content = "Graar!!",
  ui_story_5035_50351401_188_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5035_50351401_189_dialog_content = "Mino!!",
  ui_story_5035_50351401_190_dialog_content = "Kami akan membantumu mengeluarkan Vice dari sana, Puppy!",
  ui_story_5035_50351401_191_dialog_content = "Hoo—ha! Hoo—ha!",
  ui_story_5035_50351401_192_dialog_content = "Dia terlalu kuat... Aku tidak bisa bebas.",
  ui_story_5035_50351401_193_dialog_content = "Apa yang bisa kita lakukan...? Harus ada sesuatu...",
  ui_story_5035_50351401_194_dialog_content = "YA! Itulah tampilannya! Kita perlu close-up di sini! Merapatkan!",
  ui_story_5035_50351401_195_dialog_content = "Anda bajingan!",
  ui_story_5035_50351401_196_dialog_content = "Sst—",
  ui_story_5035_50351401_197_dialog_content = "Jangan bicara padaku! Bicaralah dengan karakter dalam film.",
  ui_story_5035_50351401_198_dialog_content = "Ini adalah mahakarya yang akan Anda ciptakan dengan mengorbankan hidup Anda! Di mana profesionalisme Anda?",
  ui_story_5035_50351401_199_dialog_content = "Kamu...",
  ui_story_5035_50351401_200_dialog_content = "Jadi biarkan profesional yang menanganinya!",
  ui_story_5035_50351401_201_dialog_content = "<color=#e8d9bb>Dor! Dor! Dor!</color>",
  ui_story_5035_50351401_202_dialog_content = "Ahhhh! Siapa yang menyalakan lampu kilat?!",
  ui_story_5035_50351401_203_dialog_content = "Seluruh adegan ini sia-sia!!",
  ui_story_5035_50351401_204_dialog_content = "Graaaa...",
  ui_story_5035_50351401_205_dialog_content = "Dia melepaskannya!",
  ui_story_5035_50351401_206_dialog_content = "Sekarang! Menjauh darinya!",
  ui_story_5035_50351401_207_dialog_content = "Ya!",
  ui_story_5035_50351401_208_dialog_content = "Apakah itu Lilica barusan?",
  ui_story_5035_50351401_209_dialog_content = "Pilihan sinematografimu menyedihkan, Jonny.",
  ui_story_5035_50351401_210_dialog_content = "Tempat terbaik untuk memotret adegan ini adalah dari tempat saya berdiri. Dan Anda menyebut diri Anda seorang profesional, sungguh!",
  ui_story_5035_50351401_211_dialog_content = "Lilika...",
  ui_story_5035_50351401_212_dialog_content = "Saya tidak pernah berpikir Anda akan secara sukarela kembali kepada saya.",
  ui_story_5035_50351401_213_dialog_content = "Anda mengajari saya bahwa seorang aktris selalu menyelesaikan syutingnya.",
  ui_story_5035_50351401_214_dialog_content = "Saya percaya saya berutang akhir!",
  ui_story_5035_50351401_215_dialog_content = "Ah... Lebih baik lagi.",
  ui_story_5035_50351401_216_dialog_content = "Aku hanya khawatir bahwa adegan itu terlalu pendek.",
  ui_story_5035_50351401_217_dialog_content = "Tapi sekarang setelah kau di sini...",
  ui_story_5035_50351401_218_dialog_content = "Apa yang kamu khawatirkan?",
  ui_story_5035_50351401_219_dialog_content = "Mino! Syukurlah kamu baik-baik saja!",
  ui_story_5035_50351401_220_dialog_content = "...",
  ui_story_5035_50351401_221_dialog_content = "Tentu saja. Saya hanya tidak menyangka akan dipukul dengan peti mati.",
  ui_story_5035_50351401_222_dialog_content = "Saya produser film ini. Jika Direktur Jonny ingin berkelahi di acara itu, dia akan mendapatkannya.",
  ui_story_5035_50351401_223_dialog_content = "Anda semua sangat berdedikasi!",
  ui_story_5035_50351401_224_dialog_content = "Aku akan menyerahkan sisanya kepada kalian. Aku sudah selesai akting.",
  ui_story_5035_50351401_225_dialog_content = "Izinkan saya untuk memperkenalkan diri lagi: Ini adalah Super Sadie Swashbuckler 666, seorang swashbuckler yang tidak pernah bajingan.",
  ui_story_5035_50351401_226_dialog_content = "Hari ini saya akan memukul Anda sampai Anda menggigit debu dan menderita apa yang adil!",
  ui_story_5035_50351401_227_dialog_content = "\"Penjahat Jonny Tertangkap,\" surat kabar akan berkata, di tribun besok dipajang!",
  ui_story_5035_50351401_228_dialog_content = "Wow, saya tidak tahu Anda bisa sajak juga!",
  ui_story_5035_50351401_229_dialog_content = "Haha, saya belajar dengan mendengarkan Anda!",
  ui_story_5035_50351401_230_dialog_content = "Oke semuanya, bersiaplah untuk bergemuruh!",
  ui_story_5035_50351401_231_dialog_content = "Tidak ada yang menakutkan tentang hantu yang bisa dilihat dan disentuh! Itu hanya monster lain!",
  ui_story_5035_50351401_232_dialog_content = "Anda benar-benar ingin mengalahkan saya bahkan tanpa membaca \"Akting 101: Tips Penting\"?!",
  ui_story_5035_50351401_233_dialog_content = "Hanya ada satu wanita terkemuka, dan itu AKU!",
  ui_story_5035_50351401_234_dialog_content = "Sekarang semua orang begitu bersemangat, ini tidak bisa lebih baik!",
  ui_story_5035_50351401_235_dialog_content = "Babak terakhir One Cut of Screams, adegan dua, ambil satu—",
  ui_story_5035_50351401_236_dialog_content = "TINDAKAN!",
  ui_story_5035_50351402_1_dialog_content = "<color=#e8d9bb>Memukul! Gedebuk!</color>",
  ui_story_5035_50351402_2_dialog_content = "Grraaarr!!",
  ui_story_5035_50351402_3_dialog_content = "<color=#e8d9bb>Woosh—!!</color>",
  ui_story_5035_50351402_4_dialog_content = "Apakah kalian baik-baik saja?!",
  ui_story_5035_50351402_5_dialog_content = "*Batuk-batuk*",
  ui_story_5035_50351402_6_dialog_content = "Argh…",
  ui_story_5035_50351402_7_dialog_content = "Uh, aku tidak bisa merasakan tubuhku.",
  ui_story_5035_50351402_8_dialog_content = "Bagaimana dengan Astor? Apakah kita mendapatkannya?",
  ui_story_5035_50351402_9_dialog_content = "Belum…",
  ui_story_5035_50351402_10_dialog_content = "Tapi dia tampaknya sangat lemah.",
  ui_story_5035_50351402_11_dialog_content = "Grr... Graa...",
  ui_story_5035_50351402_12_dialog_content = "Kami mengalahkan setiap ons misteri darinya dalam perkelahian itu.",
  ui_story_5035_50351402_13_dialog_content = "Ya, dia mengeluarkan Darkflow yang kuat. Dia seperti Eclipsite tua biasa sekarang.",
  ui_story_5035_50351402_14_dialog_content = "Mungkin dia hanya semacam Eclipsite khusus untuk memulai.",
  ui_story_5035_50351402_15_dialog_content = "Kami mendekati akhir sekarang. Siapa yang akan bertahan lebih lama, dia atau kita?",
  ui_story_5035_50351402_16_dialog_content = "Selama kita⁠—",
  ui_story_5035_50351402_17_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5035_50351402_18_dialog_content = "!!!",
  ui_story_5035_50351402_19_dialog_content = "Uh-oh, lilin itu!",
  ui_story_5035_50351402_20_dialog_content = "Ini memperkuat Astor.",
  ui_story_5035_50351402_21_dialog_content = "Hampir sampai, Astor. Hanya sedikit lagi.",
  ui_story_5035_50351402_22_dialog_content = "Tahan sebentar lagi...",
  ui_story_5035_50351402_23_dialog_content = "Graaaa...",
  ui_story_5035_50351402_24_dialog_content = "Pergi ke mereka! Pergi, dan konsumsilah! Makan satu saja, dan semua kekuatanmu akan pulih.",
  ui_story_5035_50351402_25_dialog_content = "Jika Anda bisa makan satu, Anda bisa makan semuanya!",
  ui_story_5035_50351402_26_dialog_content = "Graar...",
  ui_story_5035_50351402_27_dialog_content = "Sayangnya, saya tidak bisa membantu. Saya memiliki masalah yang lebih mendesak untuk diperhatikan.",
  ui_story_5035_50351402_28_dialog_content = "Aku harus menangkap setiap gerakanmu.",
  ui_story_5035_50351402_29_dialog_content = "Gambar-gambar ini jauh lebih penting daripada tindakan nyata. saya yakin anda mengerti...",
  ui_story_5035_50351402_30_dialog_content = "Graar!!",
  ui_story_5035_50351402_31_dialog_content = "Yang bisa saya lakukan adalah membantu Anda menyalakannya.",
  ui_story_5035_50351402_32_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5035_50351402_33_dialog_content = "Apakah kamu merasakannya? Kehangatan yang sudah lama hilang.",
  ui_story_5035_50351402_34_dialog_content = "Selama panas masih menggelora di dalam diri Anda, Anda tidak benar-benar mati.",
  ui_story_5035_50351402_35_dialog_content = "Setidaknya untuk saat ini, Anda masih hidup! Aku telah membuatmu hidup kembali!",
  ui_story_5035_50351402_36_dialog_content = "Lihat saja mereka. Orang-orang itu memiliki vitalitas yang Anda inginkan, namun tidak menunjukkan rasa hormat atau terima kasih untuk itu.",
  ui_story_5035_50351402_37_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5035_50351402_38_dialog_content = "Pergi mengambil apa yang Anda layak, dan mereka tidak.",
  ui_story_5035_50351402_39_dialog_content = "Grraaarr!!",
  ui_story_5035_50351402_40_dialog_content = "Ini dia datang lagi!",
  ui_story_5035_50351402_41_dialog_content = "Kita harus padamkan lilinnya, atau dia akan terus memulihkan kekuatannya!",
  ui_story_5035_50351402_42_dialog_content = "Oke, mari kita berpisah. Vice dan aku akan mengalihkan perhatiannya, sementara yang lain memikirkan cara untuk memadamkan lilin itu.",
  ui_story_5035_50351402_43_dialog_content = "Siap!",
  ui_story_5035_50351402_44_dialog_content = "Anda mengalihkan perhatiannya? Apakah kalian berdua akan baik-baik saja?",
  ui_story_5035_50351402_45_dialog_content = "Kami akan mencari tahu.",
  ui_story_5035_50351402_46_dialog_content = "Lebih baik sekarang daripada tidak sama sekali. Ayo berikan semua yang kita punya!",
  ui_story_5035_50351402_47_dialog_content = "Rapid Torrent!",
  ui_story_5035_50351402_48_dialog_content = "Mari kita tuntun dia mundur.",
  ui_story_5035_50351402_49_dialog_content = "Diterima!",
  ui_story_5035_50351402_50_dialog_content = "Lilica, Sadie—SEKARANG!",
  ui_story_5035_50351402_51_dialog_content = "Baiklah!",
  ui_story_5035_50351402_52_dialog_content = "Bisakah saya mengalahkan sutradara saat saya melakukannya?",
  ui_story_5035_50351402_53_dialog_content = "Anda dapat melakukan apa pun yang Anda inginkan setelah lilin padam!",
  ui_story_5035_50351402_54_dialog_content = "Kedengarannya menyenangkan! Aku ingin pergi juga!",
  ui_story_5035_50351402_55_dialog_content = "Tidak mudah menghadapi Astor, tapi kita selalu bisa mengeroyok Jonny!",
  ui_story_5035_50351402_56_dialog_content = "Hei, kau menghalangi tembakanku.",
  ui_story_5035_50351402_57_dialog_content = "Tunggu saja sampai kami menghancurkan kamera Anda!",
  ui_story_5035_50351402_58_dialog_content = "Jika Anda tidak ingin itu terjadi, Anda sebaiknya menyerahkan lilin!",
  ui_story_5035_50351402_59_dialog_content = "Itu bukan properti film, jangan terlalu memperhatikannya.",
  ui_story_5035_50351402_60_dialog_content = "Berhentilah membuang waktu dengannya, kalian berdua! Minos dan Vice hanya bisa menahan Astor sebentar.",
  ui_story_5035_50351402_61_dialog_content = "Kemudian rasakan tinjuku, kamu—",
  ui_story_5035_50351402_62_dialog_content = "<color=#e8d9bb>MEMBANTING!!!</color>",
  ui_story_5035_50351402_63_dialog_content = "*Batuk* Apa itu?",
  ui_story_5035_50351402_64_dialog_content = "Graaagh!",
  ui_story_5035_50351402_65_dialog_content = "gerhana?! Semuanya sudah berakhir!",
  ui_story_5035_50351402_66_dialog_content = "Oh tidak! Aku tidak memperhatikan!",
  ui_story_5035_50351402_67_dialog_content = "Kita terkepung!",
  ui_story_5035_50351402_68_dialog_content = "Anda memang mengatakan bahwa Astor mirip dengan Eclipsites.",
  ui_story_5035_50351402_69_dialog_content = "Pernahkah Anda bertanya-tanya mengapa ada begitu banyak Eclipsites di rumah berhantu hari ini?",
  ui_story_5035_50351402_70_dialog_content = "!!!",
  ui_story_5035_50351402_71_dialog_content = "Betul sekali! Eclipsites tingkat tinggi menarik Eclipsites lainnya!",
  ui_story_5035_50351402_72_dialog_content = "Anda membawa mereka ke sini dengan mengendalikan Astor!",
  ui_story_5035_50351402_73_dialog_content = "Hal-hal itu merusak pemandangan. Saya tidak ingin mereka dalam adegan apapun.",
  ui_story_5035_50351402_74_dialog_content = "Tapi saya memang membutuhkan beberapa pengawal untuk memastikan pemotretan berjalan lancar.",
  ui_story_5035_50351402_75_dialog_content = "Jika ada aktor yang berperilaku buruk, mereka akan membantu mengembalikan semuanya ke jalurnya.",
  ui_story_5035_50351402_76_dialog_content = "Banyak sekali Eclipsite...",
  ui_story_5035_50351402_77_dialog_content = "Saya tidak yakin saya memiliki kekuatan untuk menghadapi mereka semua.",
  ui_story_5035_50351402_78_dialog_content = "Aduh!",
  ui_story_5035_50351402_79_dialog_content = "Vice!",
  ui_story_5035_50351402_80_dialog_content = "Oh tidak, mereka sepertinya kehilangan tenaga di sana juga.",
  ui_story_5035_50351402_81_dialog_content = "Kita tidak bisa mengalahkan Astor atau memadamkan lilin, dan kita bahkan tidak bisa menangani Eclipsites ini...",
  ui_story_5035_50351402_82_dialog_content = "Kali ini sepertinya kita...",
  ui_story_5035_50351402_83_dialog_content = "Ya, itu saja! Lanjutkan! Katakan!",
  ui_story_5035_50351402_84_dialog_content = "Katakan semuanya sudah berakhir untukmu!",
  ui_story_5035_50351402_85_dialog_content = "Apa-apaan kau…!",
  ui_story_5035_50351402_86_dialog_content = "Ayo lari, PlayerName.",
  ui_story_5035_50351402_87_dialog_content = "Lari?",
  ui_story_5035_50351402_88_dialog_content = "Ya. Aku sangat pandai melarikan diri! Ikuti saja aku.",
  ui_story_5035_50351402_89_dialog_content = "Selama kita keluar dari sini, kita bisa mengekspos diri Jonny yang sebenarnya kepada dunia! Dia harus dihukum!",
  ui_story_5035_50351402_90_dialog_content = "Bisakah kita... benar-benar keluar dari sini...?",
  ui_story_5035_50351402_91_dialog_content = "Bahkan jika kita keluar dari sini, bagaimana dengan yang lain yang masih di dalam rumah?",
  ui_story_5035_50351402_92_dialog_content = "Yang lain...",
  ui_story_5035_50351402_93_dialog_content = "Semuanya, DENGARKAN!!",
  ui_story_5035_50351402_94_dialog_content = "Pukul mereka dengan keras! Tak kenal belas kasihan!",
  ui_story_5035_50351402_95_dialog_content = "Eh? Siapa itu?!",
  ui_story_5035_50351402_96_dialog_content = "Graah!",
  ui_story_5035_50351402_97_dialog_content = "Aku berakting sebagai Eclipsite hari ini! Jangan Anda mengambil kredit untuk pekerjaan saya!",
  ui_story_5035_50351402_98_dialog_content = "Apa yang sedang terjadi? Eclipsites saling bertarung?",
  ui_story_5035_50351402_99_dialog_content = "Beberapa Eclipsites sebenarnya adalah staf rumah hantu dengan kostum!",
  ui_story_5035_50351402_100_dialog_content = "Grahhh!!!",
  ui_story_5035_50351402_101_dialog_content = "Terlalu keras, TERLALU KERAS!",
  ui_story_5035_50351402_102_dialog_content = "Dari mana semua tambahan yang tidak berguna ini berasal? Turun dari set saya!",
  ui_story_5035_50351402_103_dialog_content = "Kami sedang syuting di sini, mengerti? Kamera berputar!",
  ui_story_5035_50351402_104_dialog_content = "Cepat! Sekarang! Sementara orang itu masih linglung!",
  ui_story_5035_50351402_105_dialog_content = "Anda mendengar, kan? PlayerName membutuhkan lilin itu.",
  ui_story_5035_50351402_106_dialog_content = "Baiklah, aku tahu!",
  ui_story_5035_50351402_107_dialog_content = "Apa itu?!",
  ui_story_5035_50351402_108_dialog_content = "Kena kau! Aku sudah melakukannya!",
  ui_story_5035_50351402_109_dialog_content = "PlayerName, Anda membutuhkan empat ini, berat?",
  ui_story_5035_50351402_110_dialog_content = "Wow! Anda berhasil meraih lilin!",
  ui_story_5035_50351402_111_dialog_content = "Hai! Letakkan!",
  ui_story_5035_50351402_112_dialog_content = "Heehee! Anda tidak bisa menangkap saya!",
  ui_story_5035_50351402_113_dialog_content = "Nih, satu lagi!",
  ui_story_5035_50351402_114_dialog_content = "Burung pipit kecil yang menyusahkan! Aku akan segera mendapatkanmu!",
  ui_story_5035_50351402_115_dialog_content = "Kita belum selesai, Jonny.",
  ui_story_5035_50351402_116_dialog_content = "Sadi? Lihat kamu. Pernah yang berubah-ubah, ya?",
  ui_story_5035_50351402_117_dialog_content = "Tetap saja, Anda hanya berhasil meraih dua lilin. Yang lain masih menyala.",
  ui_story_5035_50351402_118_dialog_content = "Kembali padaku, Astor! Kembali ke saya dan melahap burung pipit ini.",
  ui_story_5035_50351402_119_dialog_content = "Grrraarrr!!",
  ui_story_5035_50351402_120_dialog_content = "Jadi ada lilin lain.",
  ui_story_5035_50351402_121_dialog_content = "Seperti yang ini?",
  ui_story_5035_50351402_122_dialog_content = "!!!",
  ui_story_5035_50351402_123_dialog_content = "Tunggu, kapan kamu mendapatkannya?!",
  ui_story_5035_50351402_124_dialog_content = "Sepertinya Anda sudah lupa bahwa saya adalah orang yang suka berpetualang!",
  ui_story_5035_50351402_125_dialog_content = "Astor datang! Cepat, tiup lilinnya!",
  ui_story_5035_50351402_126_dialog_content = "Ya.",
  ui_story_5035_50351402_127_dialog_content = "Giliranmu untuk membungkus, Jonny.",
  ui_story_5035_50351402_128_dialog_content = "*tiup lilin*",
  ui_story_5035_50351402_129_dialog_content = "Grr... Graa... Raa...",
  ui_story_5035_50351402_130_dialog_content = "Graar...",
  ui_story_5035_50351402_131_dialog_content = "Besar! Dia kehilangan kekuatannya!",
  ui_story_5035_50351402_132_dialog_content = "Sepertinya kita yang dibiarkan berdiri.",
  ui_story_5035_50351402_133_dialog_content = "Jangan mendahului dirimu sendiri. Dia belum sepenuhnya turun, dan siapa bilang Jonny tidak menyembunyikan lilin lagi?",
  ui_story_5035_50351402_134_dialog_content = "Tapi selagi dia lemah, ayo masuk dan selesaikan ini!",
  ui_story_5035_50351402_135_dialog_content = "Siap!",
  ui_story_5035_50351402_136_dialog_content = "Tor Cepat—",
  ui_story_5035_50351402_137_dialog_content = "Tidaaaak!!!",
  ui_story_5035_50351402_138_dialog_content = "Anda tidak bisa melakukan ini! Tidak mungkin! Benar-benar tidak!",
  ui_story_5035_50351402_139_dialog_content = "Ini adalah akhir yang mengerikan! Ini bukan bagaimana film saya berakhir!",
  ui_story_5035_50351402_140_dialog_content = "Orang ini ingin melindungi Astor?",
  ui_story_5035_50351402_141_dialog_content = "Kami baru saja akan menyerang. Apakah dia tidak takut mati?",
  ui_story_5035_50351402_142_dialog_content = "Lihat apa yang dilakukan orang-orang mengerikan ini padamu! Gaun indahmu robek.",
  ui_story_5035_50351402_143_dialog_content = "Oh, Astor! Astor saya, wanita terkemuka saya ...",
  ui_story_5035_50351402_144_dialog_content = "Aku tahu kamu pasti lelah. Anda pasti sangat kedinginan, karena lampu dipadamkan satu per satu.",
  ui_story_5035_50351402_145_dialog_content = "Dunia memang selalu kejam. Tidak ada yang pernah berbagi kehangatan mereka dengan Anda.",
  ui_story_5035_50351402_146_dialog_content = "Tapi jangan takut, Astorku. Kamu punya aqw.",
  ui_story_5035_50351402_147_dialog_content = "Ayo, rasakan kehangatanku.",
  ui_story_5035_50351402_148_dialog_content = "Habiskan aku, Astor, dan kamu akan memiliki kekuatan untuk menghadapi mereka.",
  ui_story_5035_50351402_149_dialog_content = "Dia... Dia bergerak ke arahnya!",
  ui_story_5035_50351402_150_dialog_content = "... Dia gila.",
  ui_story_5035_50351402_151_dialog_content = "Haruskah kita menghentikannya?",
  ui_story_5035_50351402_152_dialog_content = "Bagaimana...? Dengan menghabisinya?",
  ui_story_5035_50351402_153_dialog_content = "Lilika!",
  ui_story_5035_50351402_154_dialog_content = "Hah? Apakah dia memanggilku?",
  ui_story_5035_50351402_155_dialog_content = "Angkat kameramu, Lilica! Anda harus memfilmkan adegan yang akan terungkap!",
  ui_story_5035_50351402_156_dialog_content = "Aku mohon, rekam. Anda harus memfilmkannya.",
  ui_story_5035_50351402_157_dialog_content = "A-Apa yang kamu coba lakukan kali ini?",
  ui_story_5035_50351402_158_dialog_content = "Itu perlu diedit ke dalam rekaman yang kita rekam sebelumnya.",
  ui_story_5035_50351402_159_dialog_content = "Ya ya ya, ini akan membuat akhir yang sempurna. Jauh lebih baik dari yang dibayangkan!",
  ui_story_5035_50351402_160_dialog_content = "Karya terakhir saya, magnum opus saya, yang akan membawa Astor ke tingkat yang baru. Sayangnya, tidak ada yang lebih cocok untuk peran utama selain saya.",
  ui_story_5035_50351402_161_dialog_content = "Hanya Astor dan saya sendiri yang bisa memfilmkan sesuatu yang layak menjadi puncak karir saya.",
  ui_story_5035_50351402_162_dialog_content = "Kamu gila! Anda akan mengorbankan diri sendiri?!",
  ui_story_5035_50351402_163_dialog_content = "Nyalakan kameramu!!!",
  ui_story_5035_50351402_164_dialog_content = "Aku merasakannya, napas sedingin es Astor menimpaku.",
  ui_story_5035_50351402_165_dialog_content = "Cepat sekarang! Ini adalah seni yang sempurna! Anda tidak boleh melewatkan satu tembakan pun!",
  ui_story_5035_50351402_166_dialog_content = "Jangan konyol. Anda tidak mungkin menyebut seni ini.",
  ui_story_5035_50351402_167_dialog_content = "Apa?!",
  ui_story_5035_50351402_168_dialog_content = "Siapa! Siapa yang berbicara?!",
  ui_story_5035_50351402_169_dialog_content = "Seni harus diwujudkan dari semangat dan usaha.",
  ui_story_5035_50351402_170_dialog_content = "Menipu orang lain bukanlah dedikasi.",
  ui_story_5035_50351402_171_dialog_content = "Dan bergumam pada mayat bukanlah emosi.",
  ui_story_5035_50351402_172_dialog_content = "Tidak ada apa pun di sini yang bisa disebut \"seni.\"",
  ui_story_5035_50351402_173_dialog_content = "Saya tidak melihat apa pun selain realisasi ambisi menyedihkan Anda.",
  ui_story_5035_50351402_174_dialog_content = "Goldie?! Kamu hidup?!",
  ui_story_5035_50351402_175_dialog_content = "Jadi aku bisa membuat akhir untukmu.",
  ui_story_5035_50351402_176_dialog_content = "Salah satu yang benar-benar akan memuaskan penonton.",
  ui_story_5035_50351402_177_dialog_content = "Apakah Anda ingat lilin ini? Sudah lama menyala dan mungkin yang pertama Anda nyalakan.",
  ui_story_5035_50351402_178_dialog_content = "Aku membawanya kembali untukmu.",
  ui_story_5035_50351402_179_dialog_content = "Tidak!!! Tidak sekarang!",
  ui_story_5035_50351402_180_dialog_content = "Cepat, Astor! Kami kehabisan waktu!",
  ui_story_5035_50351402_181_dialog_content = "Satu dorongan lagi! Potong leherku dengan mandibulamu!",
  ui_story_5035_50351402_182_dialog_content = "Makan saya! MAKAN SAYA SEKARANG!",
  ui_story_5035_50351402_183_dialog_content = "Cepat!",
  ui_story_5035_50351402_184_dialog_content = "Terima kasih atas semua kerja kerasmu, Jonny.",
  ui_story_5035_50351402_185_dialog_content = "Inilah akhirnya.'",
  ui_story_5035_50351402_186_dialog_content = "*Tiup lilin terakhir*",
  ui_story_5035_50351402_187_dialog_content = "Tidak!",
  ui_story_5035_50351402_188_dialog_content = "Astor! Astor! Apakah kamu masih disini?!",
  ui_story_5035_50351402_189_dialog_content = "Aku di sini! Dengarkan baik-baik, ini aku!",
  ui_story_5035_50351402_190_dialog_content = "Jawab aku! Tolong, saya mohon, jawab saya!",
  ui_story_5035_50351402_191_dialog_content = "Kami sudah hampir selesai, Astor! Hampir menciptakan sebuah mahakarya!",
  ui_story_5035_50351402_192_dialog_content = "<anim type=Shake><size=50>Astor! Astor—!!!</size></anim>",
  ui_story_5035_50351501_1_dialog_content = "<color=#e8d9bb>*Kerumunan bergumam*</color>",
  ui_story_5035_50351501_2_dialog_content = "Apakah Anda mendengar itu? Ada suara keras di rumah ini sekarang.",
  ui_story_5035_50351501_3_dialog_content = "Aku mendengar apa yang terdengar seperti raungan, tapi apa pun itu, itu jelas tidak normal.",
  ui_story_5035_50351501_4_dialog_content = "(Aku benar-benar ingin tahu... Apa sebenarnya yang terjadi dengan Minos dan PlayerName di sana?)",
  ui_story_5035_50351501_5_dialog_content = "(Tidak, tidak! Jika saya masuk, tidak akan ada yang menjaga pintu masuk.)",
  ui_story_5035_50351501_6_dialog_content = "Saya mendengar bahwa tempat ini baru saja dibuka sebagai rumah hantu.",
  ui_story_5035_50351501_7_dialog_content = "Anda benar! Lihat tandanya!",
  ui_story_5035_50351501_8_dialog_content = "(Uh-oh, teriakan mereka sepertinya memiliki efek menarik turis yang tak terduga...!)",
  ui_story_5035_50351501_9_dialog_content = "Ini adalah grand opening Rumah Hantu Andersen hari ini! Ingin merasakan sensasi seramnya?",
  ui_story_5035_50351501_10_dialog_content = "Rumah hantu ya? Jadi efek suara itu hanya untuk menakuti orang?",
  ui_story_5035_50351501_11_dialog_content = "Apa pun. Mari kita masuk dan melihat-lihat. Kita bisa menjamin jika itu membosankan.",
  ui_story_5035_50351501_12_dialog_content = "Jadi pengalaman ini gratis kan, Bu?",
  ui_story_5035_50351501_13_dialog_content = "Um…",
  ui_story_5035_50351501_14_dialog_content = "Tunggu sebentar! Jangan biarkan orang lain masuk.",
  ui_story_5035_50351501_15_dialog_content = "Eh? Jane? Dimana kamu...?",
  ui_story_5035_50351501_16_dialog_content = "(Um, dan di belakang Jane adalah... gerbong Persekutuan Umbraton?!)",
  ui_story_5035_50351501_17_dialog_content = "<color=#e8d9bb>Wah...</color>",
  ui_story_5035_50351501_18_dialog_content = "Tempat ini pasti tidak mudah ditemukan.",
  ui_story_5035_50351501_19_dialog_content = "Sepertinya bukan tipe properti Anderson.",
  ui_story_5035_50351501_20_dialog_content = "Apakah itu... Paman Istvan?!",
  ui_story_5035_50351501_21_dialog_content = "Oh, selamat siang, Nina.",
  ui_story_5035_50351501_22_dialog_content = "Gadis malang, sepertinya kamu masih tidak tahu apa yang terjadi di rumahmu.",
  ui_story_5035_50351501_23_dialog_content = "Selamat atas pembukaannya, Bu Nina.",
  ui_story_5035_50351501_24_dialog_content = "(Sheol juga ada di sini? Bukan... Masalah dengan izin usahaku, kan?)",
  ui_story_5035_50351501_25_dialog_content = "Um, bisakah semuanya menunggu sebentar? Saya perlu menghubungi orang yang bertanggung jawab ...",
  ui_story_5035_50351501_26_dialog_content = "Apakah maksud Anda Minos? Dia sudah di sini.",
  ui_story_5035_50351501_27_dialog_content = "Selamat siang, semuanya.",
  ui_story_5035_50351501_28_dialog_content = "Ini dia.",
  ui_story_5035_50351501_29_dialog_content = "Biarkan aku pergi!!!",
  ui_story_5035_50351501_30_dialog_content = "Anda semua harus memberikan hidup Anda untuk film saya!",
  ui_story_5035_50351501_31_dialog_content = "Hmph! Tunggu saja sampai Anda melihat bagaimana saya membelokkan setiap tembakan Anda di kaset!",
  ui_story_5035_50351501_32_dialog_content = "Aku akan merusak penampilan dan reputasimu!",
  ui_story_5035_50351501_33_dialog_content = "Saya menganggap ini adalah pembuat onar?",
  ui_story_5035_50351501_34_dialog_content = "Ya, Raja Bayangan.",
  ui_story_5035_50351501_35_dialog_content = "Dia membuat kekacauan di mana-mana di dalam dan hampir melukai beberapa tamu.",
  ui_story_5035_50351501_36_dialog_content = "Omong kosong! Ini ART!",
  ui_story_5035_50351501_37_dialog_content = "Dan, dia adalah sutradara yang menggunakan Eclipsite untuk syuting filmnya!",
  ui_story_5035_50351501_38_dialog_content = "Dia bahkan bertindak lebih jauh dengan membunuh krunya sendiri terakhir kali dia syuting di sini!",
  ui_story_5035_50351501_39_dialog_content = "Aku hanya hidup karena aku hebat dalam melarikan diri! Aku akan punya bukti juga, jika rekaman itu tidak rusak.",
  ui_story_5035_50351501_40_dialog_content = "Tutup mulutmu!",
  ui_story_5035_50351501_41_dialog_content = "Hati-hati dengan kakinya, Lilica!",
  ui_story_5035_50351501_42_dialog_content = "<color=#828282>Membanting!</color>",
  ui_story_5035_50351501_43_dialog_content = "Ahhh!",
  ui_story_5035_50351501_44_dialog_content = "Apa cara yang lebih baik untuk memberinya pelajaran selain dengan tongkat jalan yang bagus?",
  ui_story_5035_50351501_45_dialog_content = "Bawa dia pergi. Tuduh dia karena menjadi gangguan publik.",
  ui_story_5035_50351501_46_dialog_content = "Oh, dan sita semua asetnya.",
  ui_story_5035_50351501_47_dialog_content = "Baiklah!",
  ui_story_5035_50351501_48_dialog_content = "Tapi, Pak Istvan!",
  ui_story_5035_50351501_49_dialog_content = "Tenang saja.",
  ui_story_5035_50351501_50_dialog_content = "Kami tidak mengikuti prosedur kaku di Umbraton, karena seringkali, hukum melindungi orang jahat.",
  ui_story_5035_50351501_51_dialog_content = "Adapun tuduhan wanita muda ini terhadapnya ...",
  ui_story_5035_50351501_52_dialog_content = "Pergi dan lakukan penyelidikan menyeluruh, Jane.",
  ui_story_5035_50351501_53_dialog_content = "Dapatkan ke bawah secepat Anda bisa, dan Istvan Gang akan melakukan sisanya.",
  ui_story_5035_50351501_54_dialog_content = "Aku mengerti.",
  ui_story_5035_50351501_55_dialog_content = "Tunggu! A-Apa sebenarnya yang terjadi di sini?!",
  ui_story_5035_50351501_56_dialog_content = "Direktur Jonny mendapatkan apa yang pantas dia dapatkan,",
  ui_story_5035_50351501_57_dialog_content = "tapi bagi Nina kebenaran belum terungkap.",
  ui_story_5035_50351501_58_dialog_content = "Heheh... Jika Anda ingin tahu, Nona Nina—",
  ui_story_5035_50351501_59_dialog_content = "Maka tunggu saja rilis mendebarkan dari Into the Haunted House!",
  ui_story_5035_50351501_60_dialog_content = "<color=#e8d9bb>Pinggiran Umbraton: Rumah Hantu Andersen (beberapa hari kemudian)</color>",
  ui_story_5035_50351501_61_dialog_content = "<color=#e8d9bb>*Kerumunan bergumam*</color>",
  ui_story_5035_50351501_62_dialog_content = "Wah, ramai sekali di sini!",
  ui_story_5035_50351501_63_dialog_content = "Aku bahkan tidak bisa melihat di mana garis berakhir!",
  ui_story_5035_50351501_64_dialog_content = "(Wakil dan saya kembali ke Rumah Hantu Andersen, kali ini atas undangan Minos.)",
  ui_story_5035_50351501_65_dialog_content = "(Dia bersikeras untuk menebus insiden terakhir kali, tetapi mengingat betapa populernya bisnis ini sekarang ...)",
  ui_story_5035_50351501_66_dialog_content = "Tidak ada orang lain yang bisa masuk ke sana, pasti!",
  ui_story_5035_50351501_67_dialog_content = "Anda di sini untuk keluar dari pekerjaan juga, PlayerName?",
  ui_story_5035_50351501_68_dialog_content = "Sepertinya pikiran besar kita berpikiran sama hari ini.",
  ui_story_5035_50351501_69_dialog_content = "Bersiaplah, merpati! Jangan tertidur bahkan sebelum kita masuk!",
  ui_story_5035_50351501_70_dialog_content = "Selamat pagi kawan-kawan!",
  ui_story_5035_50351501_71_dialog_content = "Apakah Anda datang karena tiket setengah harga juga?",
  ui_story_5035_50351501_72_dialog_content = "Setengah harga? Tiket untuk rumah hantu ini perlu dipesan terlebih dahulu hari ini, jadi apakah Anda benar-benar berpikir mereka menawarkan tiket setengah harga?",
  ui_story_5035_50351501_73_dialog_content = "Hah?",
  ui_story_5035_50351501_74_dialog_content = "Apakah kalian tidak tahu? Belum nonton Into the Haunted House? Ini adalah hit total di Umbraton!",
  ui_story_5035_50351501_75_dialog_content = "Rumah Hantu Andersen ini adalah tempat yang sebenarnya di mana mereka menembaknya!",
  ui_story_5035_50351501_76_dialog_content = "Sudah viral! Jika Anda tidak menontonnya, Anda benar-benar keluar dari lingkaran!",
  ui_story_5035_50351501_77_dialog_content = "Wendy... Kamu tahu itu PlayerName dan Wakil ada di dalamnya?",
  ui_story_5035_50351501_78_dialog_content = "Hah?! B-Benarkah?!",
  ui_story_5035_50351501_79_dialog_content = "Wendy telah menghindari pertunjukan. Dia bilang dia hanya akan menontonnya setelah datang ke sini.",
  ui_story_5035_50351501_80_dialog_content = "Pepi dan yang lainnya ingin sekali merusaknya, tapi dia tidak membiarkan mereka.",
  ui_story_5035_50351501_81_dialog_content = "Saya ingin datang dan mengalami sendiri kengerian itu!",
  ui_story_5035_50351501_82_dialog_content = "Ini bagus, PlayerName! Sepertinya Nina dan Minos tidak perlu khawatir lagi soal penjualan tiket.",
  ui_story_5035_50351501_83_dialog_content = "Oh? Apakah mata saya menipu saya, teman-teman?",
  ui_story_5035_50351501_84_dialog_content = "Wow! Sungguh reuni yang luar biasa!",
  ui_story_5035_50351501_85_dialog_content = "Sekelompok teman yang berani, melarikan diri hidup-hidup dari bahaya yang mengerikan dan kemudian bertemu lagi di tempat yang sama!",
  ui_story_5035_50351501_86_dialog_content = "Saya harus menyatakan sebagai catatan: ini tidak ditulis! Saya tidak mengatur ini hanya untuk peringkat!",
  ui_story_5035_50351501_87_dialog_content = "Apa Minos juga mengundangmu, Lilica?",
  ui_story_5035_50351501_88_dialog_content = "Sst, PlayerName... Aku sedang syuting! Syuting!",
  ui_story_5035_50351501_89_dialog_content = "Hai pemirsa! Selamat datang di \"Into the Haunted House: The Aftershow\"!",
  ui_story_5035_50351501_90_dialog_content = "Wanita terkemuka kami Sadie akan menunjukkan kami di sekitar rumah berhantu.",
  ui_story_5035_50351501_91_dialog_content = "Hei, yo, ini Super Sadie Swashbuckler 666, siap melayani Anda!",
  ui_story_5035_50351501_92_dialog_content = "Selamat, Sadi! Anda berhasil menjadi pusat perhatian!",
  ui_story_5035_50351501_93_dialog_content = "Saya hanya bekerja untuk menjadi seorang swashbuckler nyata.",
  ui_story_5035_50351501_94_dialog_content = "Oh? Jadi, Anda tidak berpikir bahwa menjadi seorang aktris adalah buang-buang waktu lagi?",
  ui_story_5035_50351501_95_dialog_content = "Aku sudah memikirkannya.",
  ui_story_5035_50351501_96_dialog_content = "Membantu yang lemah, memperjuangkan keadilan, dan hidup mandiri! ITULAH semangat swashbuckling sejati.",
  ui_story_5035_50351501_97_dialog_content = "Saya tidak terlalu terobsesi dengan nama yang swashbuckler lagi.",
  ui_story_5035_50351501_98_dialog_content = "Luar biasa, Sadi! Saya senang Anda telah menyadari hal ini!",
  ui_story_5035_50351501_99_dialog_content = "I-Bukan apa-apa.",
  ui_story_5035_50351501_100_dialog_content = "Bagus sekali! Suasana ini sempurna! MEMOTONG!",
  ui_story_5035_50351501_101_dialog_content = "Sepertinya semua orang telah tiba.",
  ui_story_5035_50351501_102_dialog_content = "Keadaan mencegah saya menjadi tuan rumah yang sempurna terakhir kali, jadi tolong, izinkan saya untuk menebusnya kepada Anda.",
  ui_story_5035_50351501_103_dialog_content = "Lihat rumah hantu yang baru dan lebih baik, lalu datang makan siang di rumah Andersen!",
  ui_story_5035_50351501_104_dialog_content = "Baik Minos dan pembantu saya Sanae luar biasa di dapur!",
  ui_story_5035_50351501_105_dialog_content = "Haha, Anda memberi saya terlalu banyak pujian, Nona.",
  ui_story_5035_50351501_106_dialog_content = "Anda berdua berhubungan baik lagi, saya menerimanya.",
  ui_story_5035_50351501_107_dialog_content = "Anda bisa mengatakan itu. Kesalahpahaman kami telah beres.",
  ui_story_5035_50351501_108_dialog_content = "Untung saya punya kaset Lilica. Kalau tidak, penjelasan saya akan tampak sedikit lemah.",
  ui_story_5035_50351501_109_dialog_content = "Ha ha ha! Nah, dalam hal ini, tetap pantau untuk proyek masa depan saya!",
  ui_story_5035_50351501_110_dialog_content = "Anda tahu, saya hanya berpikir saya mungkin memiliki lebih banyak bakat untuk mengarahkan daripada yang saya lakukan untuk akting!",
  ui_story_5035_50351501_111_dialog_content = "Ah, benarkah? Berpikir untuk mengubah karier?",
  ui_story_5035_50351501_112_dialog_content = "Saya sedang mempertimbangkannya! Tapi ada banyak kerumitan yang datang dengan mengarahkan, dan saya bahkan tidak tahu harus mulai dari mana...",
  ui_story_5035_50351501_113_dialog_content = "Kebetulan sekali! Saya tidak percaya bahwa semua orang ada di sini!",
  ui_story_5035_50351501_114_dialog_content = "Sepertinya ini hari keberuntunganku!",
  ui_story_5035_50351501_115_dialog_content = "Oh! Goldie! Sudah selamanya!",
  ui_story_5035_50351501_116_dialog_content = "Apa yang telah Anda lakukan? Apakah Anda sedang mengerjakan proyek lain?",
  ui_story_5035_50351501_117_dialog_content = "Saya mengambil jeda singkat dari akting untuk saat ini. aku pernah⁠—",
  ui_story_5035_50351501_118_dialog_content = "Tunggu sebentar! Tunggu, tunggu, tunggu, tunggu...",
  ui_story_5035_50351501_119_dialog_content = "(Kenapa dia terlihat begitu akrab?!)",
  ui_story_5035_50351501_120_dialog_content = "Oh! Saya tahu! Ini dia!!",
  ui_story_5035_50351501_121_dialog_content = "ITU GOLDIE!!!",
  ui_story_5035_50351501_122_dialog_content = "Apakah kalian mendengar itu? Ini Goldie!",
  ui_story_5035_50351501_123_dialog_content = "Apa? Betulkah? Goldie sebenarnya ada di sini?!",
  ui_story_5035_50351501_124_dialog_content = "<color=#e8d9bb>*Kerumunan bergumam*</color>",
  ui_story_5035_50351501_125_dialog_content = "Wow! Semua orang semakin bersemangat!",
  ui_story_5035_50351501_126_dialog_content = "Goldie! Disini! Saya ingin mengajukan beberapa pertanyaan!",
  ui_story_5035_50351501_127_dialog_content = "Senang bertemu dengan Anda! Saya Brandy, magang di The Daily Scoop!",
  ui_story_5035_50351501_128_dialog_content = "Ada kekhawatiran tentang adegan di Into the Haunted House di mana Anda menghadapi bahaya yang mengerikan. Apakah mereka benar-benar terjadi?",
  ui_story_5035_50351501_129_dialog_content = "Yah, saya berasumsi bahwa semua orang telah melihat laporan terbaru tentang insiden ini.",
  ui_story_5035_50351501_130_dialog_content = "Kami benar-benar terjebak dalam rencana Jonny.",
  ui_story_5035_50351501_131_dialog_content = "Bagaimana Anda bertahan dari apa yang tampaknya menjadi kematian Anda yang tak terhindarkan?",
  ui_story_5035_50351501_132_dialog_content = "Yah... Mungkin terdengar sedikit aneh, tapi yang kulakukan adalah...",
  ui_story_5035_50351501_133_dialog_content = "<color=#FFB400>Sama sekali tidak ada.</color>",
  ui_story_5035_50351501_134_dialog_content = "Pada saat itu, lantai di bawah saya tiba-tiba runtuh, dan segala macam sampah di atas kepala saya berjatuhan pada saat yang bersamaan. Itu menakutkan.",
  ui_story_5035_50351501_135_dialog_content = "Saya tidak tahu bagaimana⁠—mungkin beberapa barang yang jatuh terlalu besar⁠—tetapi mereka tersangkut di atas saya dan bahkan tidak menyentuh saya!",
  ui_story_5035_50351501_136_dialog_content = "Sebuah batu bata tersangkut di sudut dinding, balok-balok jatuh di atas tiang-tiang batu, dan papan-papan kayu jatuh di atas balok-balok itu, mencegah benda-benda yang lebih kecil jatuh.",
  ui_story_5035_50351501_137_dialog_content = "Saya akhirnya terkurung di ruang berlubang yang terbentuk dari sampah yang jatuh, dan ada cukup ruang bagi saya untuk berdiri.",
  ui_story_5035_50351501_138_dialog_content = "Hah?",
  ui_story_5035_50351501_139_dialog_content = "Kemudian saya mulai memilih jalan keluar saya, sepotong demi sepotong, seperti membongkar sebuah bangunan dari balok-balok mainan. Itu benar-benar agak menyenangkan!",
  ui_story_5035_50351501_140_dialog_content = "Segera setelah saya melepaskan diri, saya mendengar keributan dan mengikuti suara itu.",
  ui_story_5035_50351501_141_dialog_content = "Sepanjang jalan, saya kebetulan menemukan lilin yang dijatuhkan sutradara. Itu membantu menerangi jalan saya.",
  ui_story_5035_50351501_142_dialog_content = "Dan Anda tahu sisanya, jika Anda pernah melihat pertunjukannya.",
  ui_story_5035_50351501_143_dialog_content = "Jadi, masih ada pertanyaan?",
  ui_story_5035_50351501_144_dialog_content = "A-Apakah itu benar-benar yang terjadi?!",
  ui_story_5035_50351501_145_dialog_content = "Keberuntungan semacam itu hanya bisa digambarkan sebagai keajaiban!",
  ui_story_5035_50351501_146_dialog_content = "Mungkin itu sebuah keajaiban. Tapi sekali lagi, keajaiban terjadi setiap hari.",
  ui_story_5035_50351501_147_dialog_content = "Fakta bahwa kita dilahirkan ke dunia ini adalah keajaiban tersendiri!",
  ui_story_5035_50351501_148_dialog_content = "Wow, Anda benar-benar mendapatkan kehadiran bintang pop ...",
  ui_story_5035_50351501_149_dialog_content = "Urgh! Saya akhirnya berhasil untuk Anda!",
  ui_story_5035_50351501_150_dialog_content = "Goldie, aku sangat senang kau baik-baik saja!",
  ui_story_5035_50351501_151_dialog_content = "Saya sudah memutuskan! Aku akan mulai syuting adegan ini denganmu!",
  ui_story_5035_50351501_152_dialog_content = "Wow, semua peserta utama hadir. Tolong izinkan saya mewawancarai Anda!",
  ui_story_5035_50351501_153_dialog_content = "Setelah Into the Haunted House disiarkan, ada satu pertanyaan membara di benak semua orang.",
  ui_story_5035_50351501_154_dialog_content = "Apakah Lady Astor, yang turun dari peti mati itu, benar-benar hantu?",
  ui_story_5035_50351501_155_dialog_content = "Ah, aku tahu ini akan datang. Secara teknis⁠—",
  ui_story_5035_50351501_156_dialog_content = "Anda harus masuk ke dalam dan mencari tahu sendiri.",
  ui_story_5035_50351501_157_dialog_content = "Hah?",
  ui_story_5035_50351501_158_dialog_content = "Anda perlu melihatnya sendiri. Hanya dengan begitu Anda akan menemukan jawaban yang memuaskan.",
  ui_story_5035_50351501_159_dialog_content = "Mendengar itu membuat sulit untuk menolak membeli tiket masuk!",
  ui_story_5035_50351501_160_dialog_content = "Tolong berjanjilah padaku kalian semua akan menerima wawancara denganku setelah aku melewati rumah hantu!",
  ui_story_5035_50351501_161_dialog_content = "Terima kasih atas kata-kata baik Anda tentang Rumah Hantu Andersen, Nona Sadie.",
  ui_story_5035_50351501_162_dialog_content = "... Saya hanya mengatakan apa yang saya pikirkan.",
  ui_story_5035_50351501_163_dialog_content = "Meski begitu, saya pikir Sadie punya ide yang tepat.",
  ui_story_5035_50351501_164_dialog_content = "Sekarang Eclipsite sudah diurus, seharusnya tidak ada lagi aktivitas paranormal.",
  ui_story_5035_50351501_165_dialog_content = "Mempertahankan beberapa mistik rumah untuk penonton adalah ide yang bagus.",
  ui_story_5035_50351501_166_dialog_content = "Mungkin fenomena paranormal yang sebenarnya tidak pernah ada di sini sejak awal.",
  ui_story_5035_50351501_167_dialog_content = "Tapi bisa juga sebagai PlayerName dikatakan. Bagaimana jika misteri baru menunggu kita di tempat lain?",
  ui_story_5035_50351501_168_dialog_content = "Sangat bagus bahwa Anda bisa berpikir seperti itu!",
  ui_story_5035_50351501_169_dialog_content = "Hehe! Kita tidak bisa meledakkan gelembung penonton sekarang, bukan?",
  ui_story_5035_50351501_170_dialog_content = "Terutama karena \"Into the Haunted House: The Aftershow\" masih dalam produksi!",
  ui_story_5035_50351501_171_dialog_content = "\"Ke Rumah Hantu: Pertunjukan Selepas\"?!",
  ui_story_5035_50351501_172_dialog_content = "WOW! Itu detektif berjanggut dengan rambut merah muda! Lilika! Aku penggemarmu!",
  ui_story_5035_50351501_173_dialog_content = "Ah! Lilika! Ini benar-benar dia!",
  ui_story_5035_50351501_174_dialog_content = "Hah? Tunggu! Satu per satu, semuanya!",
  ui_story_5035_50351501_175_dialog_content = "Saya tidak tahu bahwa Lilica akan menjadi begitu terkenal dalam semalam.",
  ui_story_5035_50351501_176_dialog_content = "Dia benar-benar membuat mimpinya menjadi kenyataan, menjadi nama rumah tangga!",
  ui_story_5035_50351501_177_dialog_content = "Luar biasa! Saya mendapat tanda tangan dari Goldie dan Lilica!",
  ui_story_5035_50351501_178_dialog_content = "Tunggu! Di sana! Bukankah orang-orang itu juga ada di Into the Haunted House?",
  ui_story_5035_50351501_179_dialog_content = "Saya kira demikian! Ya, itu mereka!",
  ui_story_5035_50351501_180_dialog_content = "Mata indah dan rambut perak itu... dan ekor itu! Ditambah gadis dengan topi bisbol dan pria kurus!",
  ui_story_5035_50351501_181_dialog_content = "(B-Bagaimana saya termasuk dalam daftar itu?!)",
  ui_story_5035_50351501_182_dialog_content = "A-Apa yang harus saya lakukan?! Aku belum siap untuk ketenaran!",
  ui_story_5035_50351501_183_dialog_content = "T-Mereka menyerang langsung ke arah kita!!!",
  ui_story_5035_50351501_184_dialog_content = "Mari kita pergi dari sini! Lari!!!",
  ui_story_5035_50351501_185_dialog_content = "Cepat, di sini!",
  ui_story_5035_50351501_186_dialog_content = "Um, saat Anda berlari, bisakah Anda melihat sekilas ke kamera?",
  ui_story_5035_50351501_187_dialog_content = "Dan⁠—",
  ui_story_5035_50351501_188_dialog_content = "Jangan berhenti berteriak!",
  ui_story_5035_50351501_189_dialog_content = "Hehe! Sepertinya kegembiraan di sekitar sini tidak akan tenang dalam waktu dekat.",
  ui_story_5035_50351501_190_dialog_content = "Saya mungkin harus kembali dan mengawasi.",
  ui_story_5035_50351501_191_dialog_content = "Dengan begitu banyak turis hari ini, saya perlu membuat beberapa rencana darurat...",
  ui_story_5035_50351501_192_dialog_content = "AH! seekor kecoa!",
  ui_story_5035_50351501_193_dialog_content = "Di mana stafnya? Saya punya keluhan!",
  ui_story_5035_50351501_194_dialog_content = "Aku datang!",
  ui_story_5035_50351501_195_dialog_content = "Nona, seseorang telah berada di toilet ini selama berjam-jam. Apakah Anda memiliki satu lagi?",
  ui_story_5035_50351501_196_dialog_content = "Aku takut tidak. Yang lain cukup jauh.",
  ui_story_5035_50351501_197_dialog_content = "Saya sarankan menunggu sedikit lebih lama. Aku takut aku harus mengurus sesuatu yang lain sekarang.",
  ui_story_5035_50351501_198_dialog_content = "Ayolah…",
  ui_story_5035_50351501_199_dialog_content = "Katakan, apakah kamu sudah selesai di sana ?! Apakah Anda basah sendiri atau sesuatu???",
  ui_story_5035_50351501_200_dialog_content = "Tidak ada cukup toilet untuk digunakan, jadi bisakah kamu cepat saja?!",
  ui_story_5035_50351501_201_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5035_50351501_202_dialog_content = "Halo? HAI!",
  ui_story_5035_50351501_203_dialog_content = "Aneh... Benar-benar sunyi di sana...",
  ui_story_5035_50351501_204_dialog_content = "Apakah ada orang di dalam?",
  ui_story_5035_50351501_205_dialog_content = "<color=#e8d9bb>Tetes... Tetes...</color>"
}
return config
